3 */\n  white-space: normal; /* 1 */\n}\n\n/**\n * Add the correct vertical alignment in Chrome, Firefox, and Opera.\n */\nprogress {\n  vertical-align: baseline;\n}\n\n/**\n * Remove the default vertical scrollbar in IE 10+.\n */\ntextarea {\n  overflow: auto;\n}\n\n/**\n * 1. Add the correct box sizing in IE 10.\n * 2. Remove the padding in IE 10.\n */\n[type=checkbox],\n[type=radio] {\n  box-sizing: border-box; /* 1 */\n  padding: 0; /* 2 */\n}\n\n/**\n * Correct the cursor style of increment and decrement buttons in Chrome.\n */\n[type=number]::-webkit-inner-spin-button,\n[type=number]::-webkit-outer-spin-button {\n  height: auto;\n}\n\n/**\n * 1. Correct the odd appearance in Chrome and Safari.\n * 2. Correct the outline style in Safari.\n */\n[type=search] {\n  -webkit-appearance: textfield; /* 1 */\n  outline-offset: -2px; /* 2 */\n}\n\n/**\n * Remove the inner padding in Chrome and Safari on macOS.\n */\n[type=search]::-webkit-search-decoration {\n  -webkit-appearance: none;\n}\n\n/**\n * 1. Correct the inability to style clickable types in iOS and Safari.\n * 2. Change font properties to `inherit` in Safari.\n */\n::-webkit-file-upload-button {\n  -webkit-appearance: button; /* 1 */\n  font: inherit; /* 2 */\n}\n\n/* Interactive\n   ========================================================================== */\n/*\n * Add the correct display in Edge, IE 10+, and Firefox.\n */\ndetails {\n  display: block;\n}\n\n/*\n * Add the correct display in all browsers.\n */\nsummary {\n  display: list-item;\n}\n\n/* Misc\n   ========================================================================== */\n/**\n * Add the correct display in IE 10+.\n */\ntemplate {\n  display: none;\n}\n\n/**\n * Add the correct display in IE 10.\n */\n[hidden] {\n  display: none;\n}\n\nhtml {\n  font-size: 62.5%;\n  box-sizing: border-box;\n  height: 100%;\n}\n\n*, *:before, *:after {\n  box-sizing: inherit;\n}\n\nbody {\n  font-family: \"Poppins\", sans-serif;\n  font-size: 1.4rem;\n}\n\na {\n  text-decoration: none;\n}\n\nul {\n  padding: 0;\n  list-style: none;\n  margin: 0;\n}\n\nli {\n  list-style: none;\n}\n\nimg {\n  width: 100%;\n  height: auto;\n}\n\n.contenedor {\n  width: 95%;\n  max-width: 1200px;\n  margin: 0 auto;\n}\n\n.contenedor-sm {\n  width: 95%;\n  max-width: 60rem;\n  margin: 0 auto;\n}\n\n.box {\n  padding: 1rem;\n  background-color: #FFFFFF;\n}\n\ninput[type=number]:focus {\n  outline: none !important;\n}\n\nh1 {\n  font-size: 4.2rem;\n  margin: 0;\n}\n\nh2 {\n  font-size: 3.4rem;\n  margin: 0;\n}\n\nh3 {\n  font-size: 2.6rem;\n  margin: 0;\n}\n\nh4 {\n  font-size: 2rem;\n  margin: 0;\n}\n\nh5 {\n  font-size: 1.7rem;\n  margin: 0;\n}\n\np {\n  margin: 1rem 0;\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.formulario{\r\n    display: flex;\r\n    flex-direction: column;\r\n    /*\r\n    &__legend{\r\n        color: v.$gris;\r\n        font-size: 2.2rem;\r\n        margin-bottom: 2rem;\r\n    }*/\r\n    &__fieldset{\r\n        border: none;\r\n        padding: 0;\r\n    }\r\n    &__campo{\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: .6rem;\r\n        margin: 0 0 1.5rem 0;\r\n    }\r\n    &__contenedor-icono{\r\n        display: flex;\r\n        border-radius: .5rem;\r\n        overflow: hidden;\r\n    }\r\n    &__icono{\r\n        background-color: v.$gris60;\r\n        width: 4rem;\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        i{\r\n           color: v.$blanco;\r\n           font-size: 2rem;\r\n        }\r\n    }\r\n    &__label{\r\n        display: block;\r\n        font-size: 1.4rem;\r\n        font-weight: 500;\r\n        color: rgba(v.$negro90, 0.85);\r\n    }\r\n    &__input, &__select{\r\n        outline: none;\r\n        font-size: 1.2rem;\r\n        padding: .5rem;\r\n        border: 1px solid darken(v.$gris20, 20);\r\n        border-radius: .5rem;\r\n        &--file{\r\n            border: none;\r\n        }\r\n        &--sociales{\r\n            @extend .formulario__input;\r\n            flex: 1;\r\n            border-top-left-radius: 0;\r\n            border-bottom-left-radius: 0;\r\n        }\r\n    }\r\n    &__contentinputfile{\r\n        margin: 0 auto;\r\n        height: 15rem;\r\n        width: 15rem;\r\n        border: 2px dashed v.$gris20;\r\n        position: relative;\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        &--sm{\r\n            height: 9rem;\r\n            width: 10rem;\r\n        }\r\n    }\r\n    &__imginputfile{\r\n        width: 100%;\r\n        height: 100%;\r\n        position: absolute;\r\n        img{\r\n            width: 100%;\r\n            height: 100%;\r\n            object-fit: cover;\r\n            \r\n        }\r\n    }\r\n    &__textarea{\r\n        font-size: 1.2rem;\r\n        padding: 1rem;\r\n        border: 1px solid darken(v.$gris20, 20);\r\n        border-radius: .5rem;\r\n        outline-color: v.$gris50;\r\n    }\r\n    &__dato{\r\n        display: flex;\r\n        input{\r\n            flex: 1;\r\n            border-top-right-radius: 0;\r\n            border-bottom-right-radius: 0;\r\n        }\r\n        label{\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            border-radius: .5rem;\r\n            border: 1px solid darken(v.$gris20, 20);\r\n            width: 4rem;\r\n            border-top-left-radius: 0;\r\n            border-bottom-left-radius: 0;\r\n            border-left: none;\r\n        }\r\n    }\r\n    &__radio{\r\n        display: flex;\r\n        gap: 2rem;\r\n    }\r\n    &__texto{\r\n        margin-top: 3rem\r\n    }\r\n    &__imagen{\r\n        max-width: 20rem\r\n    }\r\n    &__listado{\r\n       // @include m.tags;\r\n    }\r\n    &__submit{\r\n        @include m.boton(v.$azul50, v.$blanco);\r\n        align-self: flex-start;\r\n        width: auto;\r\n        border-radius: .4rem;\r\n        &--eliminar{  //aplicado en adinconfig/index.php para eliminar empleado\r\n            @include m.boton(v.$rojo60, v.$blanco);  \r\n            width: auto;\r\n            align-self: flex-start;\r\n        }\r\n        &--login{  //aplicado en login, olvide, registro y dash-cliente\r\n            @include m.boton(rgba(v.$azul50, .9), v.$blanco);\r\n            width: auto;\r\n            border-radius: .4rem;\r\n            align-self: center;    \r\n        }\r\n    }\r\n\r\n}\r\n\r\n.bloqueformulario {\r\n\r\n    &__submit {\r\n\r\n        &--login {\r\n            background-color: v.$azul50;\r\n            width: 100%;\r\n            border-radius: .4rem;\r\n            &:hover {\r\n                background-color: v.$gris80\r\n            }\r\n        }\r\n    }\r\n}","// Fuentes\r\n$fuente-principal: \"Poppins\",sans-serif;//'Outfit', sans-serif;\r\n$fuente-secundaria: 'Ubuntu', sans-serif;\r\n$fuente-adicional: 'Concert One', cursive;\r\n// Tamaño de Media Queries\r\n$telefonomini: 425px;\r\n$telefono: 480px;\r\n$telefonom: 525px;\r\n$telefonol: 570px;\r\n$telefonoxl: 633px;\r\n$tablet: 768px;\r\n$tabletl: 820px; \r\n$tabletm: 880px;\r\n$xl_tablet: 992px;\r\n$desktop: 1024px;\r\n$xl_desktop: 1200px;\r\n$xxl_desktop: 1550px;\r\n\r\n// Colores\r\n/*\r\n$barprogress: rgb(240, 101, 72);\r\n$rojo: #ff0000;\r\n$rosa: #d2095d;\r\n$verde1: #02db02;\r\n$verde2:#329f00;\r\n$verdeclaro: #d3f800;\r\n$azul: #007df4;\r\n$azul1: #0da6f3;\r\n$azul2: #3d72fc;\r\n$azul3: #3564db;\r\n$azul4: #0043ed;\r\n$azul10: #e3e9fc;\r\n$azulclaro: #eff2f7;\r\n$azuloscuro: #051453; \r\n$sidebar2: #064CDB;\r\n$sidebar3: #30419b; //utilizado en el sidebar\r\n$sidebar4: #244f96;\r\n$iconos: #7081b9; \r\n$secundario: #00c8c2;\r\n$blackdark: #000;\r\n$negro: #1a1b15;\r\n$blanco: #FFFFFF;\r\n$gris: #64748B;\r\n$grisclaro: #e1e1e1;\r\n$griswhite: #F3F3F3;\r\n$grisraton: #a5a5a5;\r\n$grisoscuro: #585858;\r\n$grisblack: #2a2d30;\r\n\r\n*/\r\n\r\n$backdrop: rgba(0, 0, 0, .40);\r\n\r\n//////////////////\r\n$cyan: #0891B2;\r\n$indigo: #4338CA;\r\n$morado: #7C3AED;\r\n\r\n$azul100: #051453;\r\n$azul90: #062b88;\r\n$azul80: #0739b9;\r\n$azul70: #0043ed;\r\n$azul60: #2563EB;\r\n$azul50: #3d72fc;\r\n$azul40: #007df4;\r\n$azul30: #0da6f3;\r\n$azul20: #a2d1ee;\r\n$azul10: #e3e9fc;\r\n$azul0: #eff2f7;\r\n\r\n$naranja100: rgb(240, 101, 72);\r\n$naranja90:#f5690b;\r\n$naranja80:#f57c0b;\r\n$naranja70:#f5900b;\r\n$naranja60:#F59E0B;\r\n$naranja50:#f1a82a;\r\n$naranja40:#f3b54b;\r\n$naranja30:#eebe6b;\r\n$naranja20:#f5d08f;\r\n$naranja10:#ffe3b3;\r\n\r\n$amarillo80:#fcd62c;\r\n$amarillo70:#ffeb38;\r\n$amarillo60:#ffef5d;\r\n$amarillo50:#fdf289;\r\n$amarillo40:#fbfd89;\r\n\r\n$rosa: #DB2777;\r\n\r\n\r\n$negro100: #000;\r\n$negro90: #1a1b15;\r\n$gris80: #3c3f42;\r\n$gris70: #464e58;\r\n$gris60: #676d7a;\r\n$gris50: #78808a;\r\n$gris40: #979ea7;\r\n$gris30: #c0c5ca;\r\n$gris20: #e1e1e1;\r\n$gris10: #F3F3F3;\r\n$blanco: #FFFFFF;\r\n\r\n$rojo100: #960707;\r\n$rojo90: rgb(169, 0, 0);\r\n$rojo80: #c40e0e;\r\n$rojo70: #d80101;\r\n$rojo60: #ff0000;\r\n$rojo50: #ff2b2b;\r\n$rojo40: #ff4848;\r\n$rojo30: #fd6459;\r\n$rojo20: #ff6f6a;\r\n$rojo10: #ff8b8b;\r\n\r\n$verde100: rgb(10, 78, 10);\r\n$verde90: rgb(8, 100, 8);\r\n$verde80: rgb(4, 124, 4);\r\n$verde70: rgb(9, 146, 9);\r\n$verde60:#02a710;\r\n$verde50:#22bd2f;\r\n$verde40:#48c953;\r\n$verde30:#6fd678;\r\n$verde20:#8ee095;\r\n$verde10:#c0ecc4;\r\n\r\n$lima: #02db02;\r\n$turquesa: #00c8c2;\r\n\r\n// Fuentes\r\n$delgada: 300;\r\n$regular: 400;\r\n$bold: 700;\r\n$black: 900;","@use 'variables' as v;\r\n\r\n/** Media Queries **/\r\n@mixin telefono {\r\n    @media (min-width: v.$telefono) {\r\n        @content;\r\n    }\r\n}\r\n@mixin telefonomini {\r\n    @media (min-width: v.$telefonomini) {\r\n        @content;\r\n    }\r\n}\r\n@mixin telefonom {\r\n    @media (min-width: v.$telefonom) {\r\n        @content;\r\n    }\r\n}\r\n@mixin telefonol {\r\n    @media (min-width: v.$telefonol) {\r\n        @content;\r\n    }\r\n}\r\n@mixin telefonoxl {\r\n    @media (min-width: v.$telefonoxl) {\r\n        @content;\r\n    }\r\n}\r\n@mixin tablet {\r\n    @media (min-width: v.$tablet) {\r\n        @content;\r\n    }\r\n}\r\n@mixin tabletl {\r\n    @media (min-width: v.$tabletl){\r\n        @content;\r\n    }\r\n}\r\n@mixin tabletm {\r\n    @media (min-width: v.$tabletm) {\r\n        @content;\r\n    }\r\n}\r\n@mixin xl_tablet {\r\n    @media (min-width: v.$xl_tablet) {\r\n        @content;\r\n    }\r\n}\r\n@mixin desktop {\r\n    @media (min-width: v.$desktop) {\r\n        @content;\r\n    }\r\n}\r\n@mixin xl_desktop {\r\n    @media (min-width: v.$xl_desktop) {\r\n        @content;\r\n    }\r\n}\r\n@mixin xxl_desktop {\r\n    @media (min-width: v.$xxl_desktop) {\r\n        @content;\r\n    }\r\n}\r\n\r\n\r\n@mixin boton($bgColor, $colorTexto) {\r\n    background-color: $bgColor;\r\n    padding: 1rem 2rem;\r\n    color: $colorTexto;\r\n    font-size: 1.4rem;\r\n    font-weight: 700;\r\n    border: none;\r\n    transition-property: background-color;\r\n    transition-duration: .3s;\r\n    text-align: center;\r\n    width: 100%;\r\n    display: inline-block;\r\n    border-radius: .5rem;\r\n    &:hover {\r\n        background-color: darken( $bgColor, 10% );\r\n        cursor: pointer;\r\n    }\r\n}\r\n\r\n@mixin grid($columnas, $espaciado ) {\r\n    display: grid;\r\n    gap: $espaciado;\r\n    grid-template-columns: repeat($columnas, 1fr);\r\n}\r\n\r\n@mixin contenedor{\r\n    //max-width: 120rem;\r\n    //width: 95%;\r\n    width: min(95%, 144rem); //igual que las 2 lineas de arriba...  menor a 1200px toma 95% y mayor a 1200px muestra los 1200ox\r\n    margin: 0 auto;\r\n}\r\n\r\n@mixin contenedor100{\r\n    width: min(100%, 144rem);\r\n    margin: 0 auto;\r\n}\r\n\r\n@mixin contenedor-sm{\r\n    width: min(95%, 60rem); \r\n    margin: 0 auto;\r\n}\r\n\r\n@mixin contenedor-xs{\r\n    width: min(95%, 35rem); \r\n    margin: 0 auto;\r\n}\r\n\r\n@mixin texto_fluido($min, $max){\r\n    font-size: clamp($min, -0.8rem + 10vw ,$max);\r\n}\r\n\r\n/*\r\n@mixin logo{\r\n    color: v.$blanco;\r\n    text-align: center;\r\n    margin-bottom: 2rem;\r\n    @include tablet{\r\n        color: v.$azuloscuro;\r\n        text-align: left;\r\n        margin: 0;\r\n    }\r\n}*/\r\n\r\n\r\n@mixin menu-social($color, $size) {\r\n    &__enlace{ // = <a>...</a>\r\n        &::before{\r\n            color: $color;\r\n            font-size: $size;\r\n            display: inline-block; // para que se ponga el elemento al lado de otro se puede aplicar pading\r\n            font-style: normal;\r\n            text-rendering: auto; //propiedad que se aplica a vectores\r\n            -webkit-font-smoothing: antialiased;\r\n            font-family: \"Font Awesome 6 brands\";\r\n        }\r\n        &[href*=\"https://facebook.com\"]::before{\r\n            content: \"\\f39e\";\r\n        }\r\n        &[href*=\"https://github.com\"]::before{\r\n            content: \"\\f09b\";\r\n        }\r\n        &[href*=\"https://tiktok.com\"]::before{\r\n            content: \"\\e07b\";\r\n        }\r\n        &[href*=\"https://instagram.com\"]::before{\r\n            content: \"\\f16d\";\r\n        }\r\n        &[href*=\"https://twitter.com\"]::before{\r\n            content: \"\\f099\";\r\n        }\r\n        &[href*=\"https://youtube.com\"]::before{\r\n            content: \"\\f167\";\r\n        }\r\n    }\r\n    &__ocultar{ //== <span></span>\r\n        display: none;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.acciones{ //hace referencia a las etiquetas <a>href=\"\"</a> en las paginas de login/registro... etc.\r\n    margin: 2rem 1rem 1rem 1rem;\r\n    display: flex;\r\n    justify-content: space-between;\r\n    &__Centrar{\r\n        @extend .acciones;\r\n        justify-content: center;\r\n    }\r\n    &__enlace{\r\n        //color: v.$negro;\r\n        color: v.$gris80;\r\n        font-size: 1.4rem;\r\n        font-weight: v.$delgada;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.wrapper {\r\n  display: flex;\r\n}\r\n.acordeon{\r\n  max-height: 0rem;\r\n  overflow: hidden;\r\n  transition: max-height 0.3s ease-out;\r\n}\r\n\r\n.showacordeon{\r\n  max-height: 100%; \r\n}\r\n\r\n\r\n///////////////// con input tipe chekbox sin usar js, en vista cerrarcaja.php//////////////////\r\n.accordion{\r\n  margin-top: 2rem;\r\n  input[type=\"checkbox\"]{\r\n    display: none;\r\n  }\r\n  .etiqueta{\r\n    cursor: pointer;\r\n    display: block;\r\n    padding: 1rem;\r\n    font-size: 1.7rem;\r\n    text-align: center;\r\n    position: relative;\r\n    &::before{\r\n      content: \"+\";\r\n      position: absolute;\r\n      right: 0;\r\n      margin-right: 1rem;\r\n      font-size: 2rem;\r\n      font-weight: 700;\r\n    }\r\n  }\r\n  .wrapper-content{\r\n    margin-top: 1rem;\r\n    flex: 1;\r\n    max-height: 0rem;\r\n    transition: max-height 0.2s ease-out;\r\n  }\r\n  .content{\r\n    max-height: 0rem;\r\n    overflow: hidden;\r\n    transition: max-height 0.3s ease-out;\r\n  }\r\n\r\n  input[type=\"checkbox\"]:checked + .etiqueta + .wrapper{\r\n    .wrapper-content{\r\n      max-height: 100%;\r\n      .content{\r\n        max-height: 100%; \r\n      }\r\n    }\r\n  }\r\n\r\n  input[type=\"checkbox\"]:checked + .etiqueta::before{\r\n    content: \"-\";\r\n  }\r\n}\r\n\r\n\r\n///////////////// con input tipe radio sin usar js, en vista index.php de almacen tab//////////////////\r\n.accordion_inv{\r\n    #infoalmacen:checked ~ .btn_inv_info_rapido .btninfoalmacen{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #stockproducto:checked ~ .btn_inv_info_rapido .btnstockproducto{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #utilidadproducto:checked ~ .btn_inv_info_rapido .btnutilidadproducto{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #sedes:checked ~ .btn_inv_info_rapido .btnsedes{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #proveedores:checked ~ .btn_inv_info_rapido .btnproveedores{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #ordenproduccion:checked ~ .btn_inv_info_rapido .btnordenproduccion{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    #codigobarras:checked ~ .btn_inv_info_rapido .btncodigobarras{\r\n      background-color: darken(v.$gris20, 0);\r\n      color: v.$gris80;\r\n      border-color: lighten(v.$gris80, 10);\r\n    }\r\n    .accordion_tab_content{\r\n      display: none;\r\n    }\r\n    input[type=\"radio\"]{\r\n      display: none;\r\n    }\r\n    #infoalmacen:checked ~ .tablas_inv_rapido .infoalmacen{\r\n      display: block;\r\n    }\r\n    #stockproducto:checked ~ .tablas_inv_rapido .tablastock{\r\n      display: block;\r\n    }\r\n    #utilidadproducto:checked ~ .tablas_inv_rapido .tablautilidad{\r\n      display: block;\r\n    }\r\n    #sedes:checked ~ .tablas_inv_rapido .sedes{\r\n      display: block;\r\n    }\r\n    #proveedores:checked ~ .tablas_inv_rapido .proveedores{\r\n      display: block;\r\n    }\r\n    #ordenproduccion:checked ~ .tablas_inv_rapido .ordenproduccion{\r\n      display: block;\r\n    }\r\n    #codigobarras:checked ~ .tablas_inv_rapido .codigobarras{\r\n      display: block;\r\n    }\r\n}\r\n\r\n///////////////// con input tipe radio sin usar js, en vista index.php de configuracion//////////////////\r\n.accordion_inv{\r\n  #btn1:checked ~ .btnsetup .btn1{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn2:checked ~ .btnsetup .btn2{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn3:checked ~ .btnsetup .btn3{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn4:checked ~ .btnsetup .btn4{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn5:checked ~ .btnsetup .btn5{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn6:checked ~ .btnsetup .btn6{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn7:checked ~ .btnsetup .btn7{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn8:checked ~ .btnsetup .btn8{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn9:checked ~ .btnsetup .btn9{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn10:checked ~ .btnsetup .btn10{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn11:checked ~ .btnsetup .btn11{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn12:checked ~ .btnsetup .btn12{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn13:checked ~ .btnsetup .btn13{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn14:checked ~ .btnsetup .btn14{\r\n    background-color: darken(v.$gris20, 0);\r\n    color: v.$gris80;\r\n    border-color: lighten(v.$gris80, 10);\r\n  }\r\n  #btn1:checked ~ .flex .btnsetup-precios .btn1{\r\n    background: linear-gradient(\r\n        135deg,\r\n        #6366f1,\r\n        #4f46e5\r\n    );\r\n    color: #fff;\r\n    border-color: #4f46e5;\r\n    transform: translateY(-1px);\r\n    box-shadow:\r\n        0 8px 20px rgba(79,70,229,.20);\r\n    border-radius: .65rem;\r\n    transform: translateY(-1px);\r\n  }\r\n  #btn2:checked ~ .flex .btnsetup-precios .btn2{\r\n    background: linear-gradient(\r\n        135deg,\r\n        #6366f1,\r\n        #4f46e5\r\n    );\r\n    color: #fff;\r\n    border-color: #4f46e5;\r\n    transform: translateY(-1px);\r\n    box-shadow:\r\n        0 8px 20px rgba(79,70,229,.20);\r\n    border-radius: .65rem;\r\n    transform: translateY(-1px);\r\n  }\r\n  #btn3:checked ~ .flex .btnsetup-precios .btn3{\r\n    background: linear-gradient(\r\n        135deg,\r\n        #6366f1,\r\n        #4f46e5\r\n    );\r\n    color: #fff;\r\n    border-color: #4f46e5;\r\n    transform: translateY(-1px);\r\n    box-shadow:\r\n        0 8px 20px rgba(79,70,229,.20);\r\n    border-radius: .65rem;\r\n    transform: translateY(-1px);\r\n  }\r\n  #btn4:checked ~ .flex .btnsetup-precios .btn4{\r\n    background: linear-gradient(\r\n        135deg,\r\n        #6366f1,\r\n        #4f46e5\r\n    );\r\n    color: #fff;\r\n    border-color: #4f46e5;\r\n    transform: translateY(-1px);\r\n    box-shadow:\r\n        0 8px 20px rgba(79,70,229,.20);\r\n    border-radius: .65rem;\r\n    transform: translateY(-1px);\r\n  }\r\n  .btnsetup-precios label{\r\n    transition:\r\n        background .25s ease,\r\n        color .25s ease,\r\n        border-color .25s ease,\r\n        box-shadow .25s ease,\r\n        transform .25s ease;\r\n  }\r\n  .accordion_tab_content{\r\n    display: none;\r\n  }\r\n  input[type=\"radio\"]{\r\n    display: none;\r\n  } \r\n  #btn1:checked ~ .contenedorsetup .contenido1{\r\n    display: block;\r\n  }\r\n  #btn2:checked ~ .contenedorsetup .contenido2{\r\n    display: block;\r\n  }\r\n  #btn3:checked ~ .contenedorsetup .contenido3{\r\n    display: block;\r\n  }\r\n  #btn4:checked ~ .contenedorsetup .contenido4{\r\n    display: block;\r\n  }\r\n  #btn5:checked ~ .contenedorsetup .contenido5{\r\n    display: block;\r\n  }\r\n  #btn6:checked ~ .contenedorsetup .contenido6{\r\n    display: block;\r\n  }\r\n  #btn7:checked ~ .contenedorsetup .contenido7{\r\n    display: block;\r\n  }\r\n  #btn8:checked ~ .contenedorsetup .contenido8{\r\n    display: block;\r\n  }\r\n  #btn9:checked ~ .contenedorsetup .contenido9{\r\n    display: block;\r\n  }\r\n  #btn10:checked ~ .contenedorsetup .contenido10{\r\n    display: block;\r\n  }\r\n  #btn11:checked ~ .contenedorsetup .contenido11{\r\n    display: block;\r\n  }\r\n  #btn12:checked ~ .contenedorsetup .contenido12{\r\n    display: block;\r\n  }\r\n  #btn13:checked ~ .contenedorsetup .contenido13{\r\n    display: block;\r\n  }\r\n  #btn14:checked ~ .contenedorsetup .contenido14{\r\n    display: block;\r\n  }\r\n}\r\n\r\n.blockInputRadio{\r\n  input[type=\"radio\"]{\r\n    display: block;\r\n  }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.alerta{\n    align-items: center;\n    border: .1rem solid transparent;\n    border-radius: 1.4rem;\n    box-shadow: 0 1.8rem 4rem rgba(15, 23, 42, .08);\n    display: flex;\n    gap: 1.2rem;\n    margin: 1rem 0;\n    overflow: hidden;\n    padding: 1.2rem 1.4rem;\n    position: relative;\n    text-transform: none;\n\n    &::before{\n        bottom: 0;\n        content: '';\n        left: 0;\n        position: absolute;\n        top: 0;\n        width: .4rem;\n    }\n\n    &__icono{\n        align-items: center;\n        border-radius: 1.2rem;\n        display: inline-flex;\n        flex: 0 0 3.8rem;\n        height: 3.8rem;\n        justify-content: center;\n        width: 3.8rem;\n\n        i{\n            font-size: 1.8rem;\n        }\n    }\n\n    &__contenido{\n        display: flex;\n        flex-direction: column;\n        gap: .2rem;\n        min-width: 0;\n\n        strong{\n            color: #0f172a;\n            font-size: 1.35rem;\n            font-weight: 800;\n            line-height: 1.2;\n        }\n\n        span{\n            font-size: 1.25rem;\n            font-weight: 700;\n            line-height: 1.35;\n        }\n    }\n\n    p{\n        margin: 0;\n\n        i{\n            font-size: 1.6rem;\r\n            margin-right: 1rem;\r\n        }\r\n    }\n    &__error{\n        background: linear-gradient(135deg, rgba(255, 241, 242, .98), rgba(255, 255, 255, .96));\n        border-color: #fecdd3;\n        color: #be123c;\n\n        &::before{\n            background: #ef4444;\n        }\n\n        .alerta__icono{\n            background: #ffe4e6;\n            color: #e11d48;\n        }\n    }\n    &__exito{\n        background: linear-gradient(135deg, rgba(236, 253, 245, .98), rgba(255, 255, 255, .96));\n        border-color: #a7f3d0;\n        color: #047857;\n\n        &::before{\n            background: #10b981;\n        }\n\n        .alerta__icono{\n            background: #d1fae5;\n            color: #059669;\n        }\n    }\n}\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.sweetbtnconfirm{  //clase de sweetalert2\r\n    font-size: 1.4rem !important;\r\n    color: v.$blanco !important;\r\n    background-color: v.$turquesa !important;\r\n}\r\n.sweetbtncancel{\r\n    font-size: 1.4rem !important;\r\n    color: v.$blanco !important;\r\n    background-color: v.$gris50 !important;\r\n}\r\n\r\n///clase interna de sweetalert2 corresponde al icono del success\r\n.swal2-success-ring{\r\n    border: 0.25em solid v.$azul60 !important;\r\n}\r\n.swal2-success-line-long, .swal2-success-line-tip{\r\n    background-color: v.$azul60 !important;\r\n}\r\n\r\n.swal2-confirm{ //clase interna de sweetalert es el boton ok despues de confirmar\r\n    background-color: v.$turquesa !important;\r\n    font-size: 1.2rem !important;\r\n}\r\n.swal2-cancel{\r\n    font-size: 1.2rem !important;\r\n}\r\n\r\n.swal2-title{  //titulo = title\n    padding-top: 2rem !important;\n}\n\n.swal2-popup.j2-confirm {\n  width: min(46rem, calc(100vw - 3.2rem)) !important;\n  padding: 0 !important;\n  border: .1rem solid rgba(226, 232, 240, .95) !important;\n  border-radius: 1.8rem !important;\n  background: #fff !important;\n  box-shadow: 0 2.4rem 7rem rgba(15, 23, 42, .22), 0 .8rem 2rem rgba(15, 23, 42, .08) !important;\n  overflow: hidden !important;\n}\n\n.j2-confirm::before {\n  content: '';\n  display: block;\n  height: .6rem;\n  background: linear-gradient(90deg, #4f46e5, #08c6bd);\n}\n\n.j2-confirm .j2-confirm__icon {\n  display: grid !important;\n  place-items: center !important;\n  width: 6rem !important;\n  height: 6rem !important;\n  margin: 3rem auto 1.6rem !important;\n  border: 0 !important;\n  border-radius: 1.8rem !important;\n  background: #eef2ff !important;\n  color: #4f46e5 !important;\n  box-shadow: 0 1.4rem 3rem rgba(79, 70, 229, .18) !important;\n}\n\n.j2-confirm .swal2-icon-content {\n  color: inherit !important;\n  font-size: 3.2rem !important;\n  font-weight: 800 !important;\n}\n\n.j2-confirm .j2-confirm__title {\n  margin: 0 !important;\n  padding: 0 3.2rem !important;\n  color: #0f172a !important;\n  font-size: 2.25rem !important;\n  font-weight: 900 !important;\n  line-height: 1.15 !important;\n}\n\n.j2-confirm .j2-confirm__text {\n  margin: 1rem auto 0 !important;\n  padding: 0 3.8rem !important;\n  max-width: 38rem;\n  color: #64748b !important;\n  font-size: 1.45rem !important;\n  font-weight: 500 !important;\n  line-height: 1.45 !important;\n}\n\n.j2-confirm .j2-confirm__input {\n  width: calc(100% - 6.4rem) !important;\n  height: 4.8rem !important;\n  margin: 2rem auto 0 !important;\n  border: .1rem solid #cbd5e1 !important;\n  border-radius: 1rem !important;\n  background: #f8fafc !important;\n  box-shadow: 0 .8rem 2rem rgba(79, 70, 229, .08) !important;\n  color: #0f172a !important;\n  font-size: 1.45rem !important;\n  font-weight: 600 !important;\n  outline: none !important;\n  padding: 0 1.5rem !important;\n  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;\n}\n\n.j2-confirm .j2-confirm__input:focus {\n  border-color: #4f46e5 !important;\n  background: #fff !important;\n  box-shadow: 0 0 0 .35rem rgba(79, 70, 229, .12), 0 .8rem 2rem rgba(79, 70, 229, .08) !important;\n}\n\n.j2-confirm .j2-confirm__input::placeholder {\n  color: #94a3b8 !important;\n  font-weight: 600 !important;\n}\n\n.j2-confirm .j2-confirm__actions {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr;\n  gap: 1rem !important;\n  width: 100% !important;\n  margin: 2.8rem 0 0 !important;\n  padding: 1.8rem 2rem 2rem !important;\n  border-top: .1rem solid #e2e8f0;\n  background: #f8fafc;\n}\n\n.j2-confirm .j2-confirm__button {\n  align-items: center;\n  border: 0;\n  border-radius: 1rem !important;\n  display: inline-flex !important;\n  font-size: 1.45rem !important;\n  font-weight: 800 !important;\n  height: 4.4rem;\n  justify-content: center;\n  margin: 0 !important;\n  padding: 0 1.8rem !important;\n  transition: transform .18s ease, box-shadow .18s ease, background-color .18s ease;\n}\n\n.j2-confirm .j2-confirm__button:hover {\n  transform: translateY(-.1rem);\n}\n\n.j2-confirm .j2-confirm__button--confirm {\n  background: linear-gradient(135deg, #14b8a6, #08c6bd) !important;\n  box-shadow: 0 1.2rem 2.4rem rgba(20, 184, 166, .24) !important;\n  color: #fff !important;\n}\n\n.j2-confirm .j2-confirm__actions--single {\n  grid-template-columns: minmax(14rem, 22rem) !important;\n  justify-content: center !important;\n}\n\n.j2-confirm .j2-confirm__button--cancel {\n  background: #eef2f7 !important;\n  color: #475569 !important;\n}\n\n.j2-confirm--dispatch .j2-confirm__icon::before {\n  content: \"\\f0d1\";\n  font-family: \"Font Awesome 6 Free\";\n  