es\r\n\r\n.btn-bluedark{\r\n    background-color:v.$azul70;\r\n    border-color:v.$azul70;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$azul70, 15);\r\n        border-color: darken(v.$azul70, 15);\r\n    }\r\n}\r\n.btn-blueintense{\r\n    background-color:v.$azul60;\r\n    border-color:v.$azul60;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$azul60, 15);\r\n        border-color: darken(v.$azul60, 15);\r\n    }\r\n}\r\n.btn-blue{\r\n    background-color:v.$azul40;\r\n    border-color:v.$azul40;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$azul40, 15);\r\n        border-color: darken(v.$azul40, 15);\r\n    }\r\n}\r\n.btn-bluelight{\r\n    background-color:v.$azul20;\r\n    border-color:v.$azul20;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$azul20, 15);\r\n        border-color: darken(v.$azul20, 15);\r\n    }\r\n}\r\n.btn-red{\r\n    background-color:v.$rojo60;\r\n    border-color:v.$rojo60;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$rojo60, 15);\r\n        border-color: darken(v.$rojo60, 15);\r\n    }\r\n}\r\n.btn-green{\r\n    background-color:v.$verde70;\r\n    border-color:v.$verde70;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$verde70, 15);\r\n        border-color: darken(v.$verde70, 15);\r\n    }\r\n}\r\n.btn-lima{\r\n    background-color:v.$lima;\r\n    border-color:v.$lima;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$lima, 15);\r\n        border-color: darken(v.$lima, 15);\r\n    }\r\n}\r\n.btn-pink{\r\n    background-color:v.$rosa;\r\n    border-color:v.$rosa;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$rosa, 15);\r\n        border-color: darken(v.$rosa, 15);\r\n    }\r\n}\r\n.btn-orange{\r\n    background-color:v.$naranja100;\r\n    border-color:v.$naranja100;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$naranja100, 15);\r\n        border-color: darken(v.$naranja100, 15);\r\n    }\r\n}\r\n.btn-yellow{\r\n    background-color:v.$amarillo80;\r\n    border-color:v.$amarillo80;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$amarillo80, 15);\r\n        border-color: darken(v.$amarillo80, 15);\r\n    }\r\n}\r\n.btn-turquoise{\r\n    background-color:v.$turquesa;\r\n    border-color:v.$turquesa;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$turquesa, 15);\r\n        border-color: darken(v.$turquesa, 15);\r\n    }\r\n}\r\n.btn-indigo{\r\n    background-color:v.$indigo;\r\n    border-color:v.$indigo;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$indigo, 15);\r\n        border-color: darken(v.$indigo, 15);\r\n    }\r\n}\r\n.btn-light{\r\n    background-color:v.$blanco;\r\n    border-color:lighten( v.$gris60, 7);\r\n    color: v.$negro90;\r\n    &:hover{\r\n        background-color: darken(v.$blanco, 15);\r\n        border-color: darken(v.$blanco, 15);\r\n    }\r\n}\r\n.btn-dark{\r\n    background-color:v.$negro90;\r\n    border-color: v.$negro90;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$gris20, 0);\r\n        color: v.$gris80;\r\n        border-color: lighten(v.$gris80, 10);\r\n    }\r\n}\r\n.btn-semidark{\r\n    background-color:v.$gris80;\r\n    border-color: v.$gris80;\r\n    color: v.$blanco;\r\n    &:hover{\r\n        background-color: darken(v.$gris20, 0);\r\n        color: v.$gris80;\r\n        border-color: lighten(v.$gris80, 10);\r\n    }\r\n}\r\n.btn-locked{\r\n    background-color:v.$gris10;\r\n    border-color:darken(v.$gris20, 7);\r\n    color: darken(v.$gris20, 7);\r\n    &:hover{\r\n        cursor: auto;\r\n    }\r\n}\r\n.btn-command{\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    max-width: 