ox\"]:checked + label:after { // cuando se chequea tomo el pseudo elemento after y crea otra caja se le quita 2 bordes se rota -55º y que listo el tiket \r\n        content: \"\";\r\n        width: 1.4rem;\r\n        height: .8rem;\r\n        border: 4px solid v.$turquesa;\r\n        float: left;\r\n        margin-left: -2.8rem;\r\n        margin-top: .7rem;\r\n        border-right: 0;\r\n        border-top: 0;\r\n        transform: rotate(-55deg);\r\n    }  \r\n}\r\n\r\n///////////////////////////////////////////////////////////////////////\r\n.styleradio{\r\n    min-width: 10rem;\r\n    //white-space: nowrap;\r\n    input[type=\"radio\"] {\r\n        display: none;\r\n    }\r\n    input[type=\"radio\"] + label {\r\n        line-height: 2rem;\r\n        cursor: pointer;\r\n    }\r\n    input[type=\"radio\"] + label:before{ //crea una caja cuadrada con :before\r\n        content: \"\";\r\n        width: 2.2rem;\r\n        height: 2.2rem;\r\n        float: left;\r\n        border: 1px solid darken(v.$gris20, 20);\r\n        background-color: v.$blanco;\r\n        margin-right: 1rem;\r\n        border-radius: .5rem;\r\n    }\r\n    input[type=\"radio\"]:checked + label:before{  // cuando este chequeado toma el pseudo elemento before y pinta verde\r\n        border-color: v.$turquesa;\r\n    }\r\n    input[type=\"radio\"]:checked + label:after { // cuando se chequea tomo el pseudo elemento after y crea otra caja se le quita 2 bordes se rota -55º y que listo el tiket \r\n        content: \"\";\r\n        width: 1.4rem;\r\n        height: .8rem;\r\n        border: 4px solid v.$turquesa;\r\n        float: left;\r\n        margin-left: -2.8rem;\r\n        margin-top: .7rem;\r\n        border-right: 0;\r\n        border-top: 0;\r\n        transform: rotate(-55deg);\r\n    }\r\n}\r\n\r\n\r\n////////////////////////////////////////////////////////////////////////////////\r\n.radio-button {\r\n    //display: inline-block;\r\n    position: relative;\r\n    cursor: pointer;\r\n    .radio-button__input {\r\n        position: absolute;\r\n        opacity: 0;\r\n        width: 0;\r\n        height: 0;\r\n    }\r\n      \r\n    .radio-button__label {\r\n        display: inline-block;\r\n        padding-left: 3rem;\r\n        //margin-bottom: 1rem;\r\n        position: relative;\r\n        font-size: 1.4rem;\r\n        color: v.$blanco;\r\n        cursor: pointer;\r\n        transition: all 0.3s ease-in-out;\r\n    }\r\n      \r\n    .radio-button__span {\r\n        position: absolute;\r\n        top: 50%;\r\n        left: 0;\r\n        transform: translateY(-50%);\r\n        width: 2rem;\r\n        height: 2rem;\r\n        border-radius: 50%;\r\n        border: 2px solid v.$gris50;\r\n        transition: all 0.3s ease-in-out;\r\n    }\r\n\r\n    .radio-button__input:checked + .radio-button__label .radio-button__span {\r\n        transform: translateY(-50%) scale(0.9);\r\n        border: 5px solid v.$azul60;\r\n        color: v.$azul60;\r\n    }\r\n    .radio-button__input:checked + .radio-button__label {\r\n        color: v.$azul60;\r\n    } \r\n    .radio-button__label:hover .radio-button__span {\r\n        transform: translateY(-20%) scale(1.2);\r\n        border-color: v.$azul60;\r\n        box-shadow: 0 0 10px v.$azul60;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.midialog-sm{\r\n    &::backdrop{\r\n        background-color: v.$backdrop;\r\n    }\r\n    width: 90%;\r\n    max-width: 50rem;\r\n    border: none;\r\n    border-radius: .4rem;\r\n    .ocultar{\r\n        display: none;\r\n    }\r\n    .select2-selection__rendered{\r\n        font-size: 1.2rem;\r\n    }\r\n}\r\n.midialog-xs{\r\n    &::backdrop{\r\n        background-color: v.$backdrop;\r\n    }\r\n    width: 90%;\r\n    max-width: 32rem;\r\n    border: none;\r\n    border-radius: .4rem;\r\n}\r\n.midialog-md{\r\n    &::backdrop{\r\n        background-color: v.$backdrop;\r\n    }\r\n    width: 95%;\r\n    max-width: 60rem;\r\n    border: none;\r\n    border-radius: .4rem;\r\n}\r\n.midialog-lg{\r\n    &::backdrop{\r\n        background-color: v.$backdrop;\r\n    }\r\n    width: 95%;\r\n    max-width: 72rem;\r\n    border: none;\r\n    border-radius: .4rem;\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.tabs{\r\n  text-align: center;\r\n  .tabs-content{\r\n      display: inline-flex;\r\n      flex-wrap: wrap;\r\n      border: 1px solid #4338ca;\r\n      padding: 0.3rem;\r\n      border-radius: 0.5rem;\r\n      label{\r\n          flex: 1 1 auto;\r\n          text-align: center;\r\n      }\r\n      input[type=\"radio\"] {\r\n          clip-path: inset(100%); //recorta el elemento\r\n          display: none; \r\n      }\r\n      label span {\r\n          display: block;\r\n          cursor: pointer;\r\n          padding: .7rem 1.2rem;\r\n          font-size: 1.3rem;\r\n          color: #4338ca;\r\n          font-weight: 400;\r\n          &:hover{\r\n              background-color: v.$azul10;\r\n          }\r\n      }\r\n      input[type=\"radio\"]:checked + span{\r\n          background-color: #4338ca;\r\n          color: v.$blanco;\r\n          border-radius: 0.5rem;\r\n          font-weight: 500;\r\n      }\r\n  }\r\n}\r\n\r\n\r\n.tabslife{\r\n  .tabslife-content{\r\n      display: flex;\r\n      flex-wrap: wrap;\r\n      margin-top: 0.5rem;\r\n      justify-content: center;\r\n      input[type=\"radio\"] {\r\n          clip-path: inset(100%); //recorta el elemento\r\n          display: none;\r\n      }\r\n      label span {\r\n          display: block;\r\n          cursor: pointer;\r\n          color: v.$gris80;\r\n          background-color: v.$blanco;\r\n          padding: .8rem 1.4rem;\r\n          border: 1px solid v.$gris20;\r\n          transition: background-color .3s ease;\r\n      }\r\n      input[type=\"radio\"]:checked + span{\r\n          background-color: darken(v.$azul10, 3);\r\n          color: #0043ed;\r\n          border-color: #0043ed;\r\n      }\r\n      label:first-child span {\r\n      border-radius: .375em 0 0 .375em;\r\n      }\r\n      label:last-child span {\r\n      border-radius: 0 .375em .375em 0;\r\n      }\r\n  }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.content-spinner{\r\n  position: absolute;\r\n  //z-index: 3;\r\n  width: 100%;\r\n  //height: 100vh;\r\n  height: 100%;\r\n  top: 0;\r\n  display: grid;\r\n  place-items: center;\r\n  background-color: rgba(0, 0, 0, 0.4);\r\n  overflow: hidden;\r\n}\r\n.spinner{\r\n  display: inline-block;\r\n  border: 4px solid rgba(0, 0, 0, 0.1);\r\n  width: 4rem;\r\n  height: 4rem;\r\n  border-radius: 50%;\r\n  border-left-color: v.$azul60;\r\n  animation: spinner 1s linear infinite;\r\n}\r\n\r\n\r\n\r\n.content-spinner1{\r\n  position: absolute;\r\n  //z-index: 3;\r\n  width: 100%;\r\n  //height: 100vh;\r\n  height: 100%;\r\n  top: 0;\r\n  display: grid;\r\n  place-items: center;\r\n  background-color: #eff2f79c;\r\n  overflow: hidden;\r\n}\r\n.spinner1{\r\n  display: inline-block;\r\n  border: 4px solid rgba(0, 0, 0, 0.1);\r\n  width: 4rem;\r\n  height: 4rem;\r\n  border-radius: 50%;\r\n  border-left-color: v.$azul60;\r\n  animation: spinner 1s linear infinite;\r\n  position: relative;\r\n  top: -30%;\r\n}\r\n\r\n@keyframes spinner{\r\n  0%{\r\n      transform: rotate(0deg);\r\n  }\r\n  100%{\r\n      transform: rotate(360deg);\r\n  }\r\n}",".pagination {\r\n  display: flex;\r\n  justify-content: center;\r\n  gap: 0.5rem;\r\n\r\n  li {\r\n    a {\r\n      display: inline-block;\r\n      padding: 0.5rem 1rem;\r\n      border: 1px solid #ddd;\r\n      border-radius: 0.25rem;\r\n      text-decoration: none;\r\n      color: #333;\r\n\r\n      &.disabled {\r\n        opacity: 0.4;\r\n        pointer-events: none;\r\n        cursor: default;\r\n      }\r\n\r\n      &:hover:not(.disabled) {\r\n        background-color: #f1f1f1;\r\n      }\r\n    }\r\n\r\n    &.active a {\r\n      background-color: #6366f1;\r\n      color: white;\r\n      border-color: #6366f1;\r\n    }\r\n  }\r\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.content-dropdawn{\r\n    position: relative;\r\n}\r\n\r\n.btnmultiselect{\r\n    display: flex;\r\n    justify-content: space-between;\r\n    //height: 5rem;\r\n    align-items: center;\r\n    padding: 1rem 1.2rem;\r\n    border-radius: 1rem;\r\n    cursor: pointer;\r\n    background-color: v.$blanco;\r\n    max-width: 32rem;\r\n    //min-width: 26rem;\r\n    .btnmultiselect-text{\r\n        font-size: 1.5rem;\r\n        font-weight: 400;\r\n        color: v.$gris70;\r\n        margin-right: 1rem;\r\n    }\r\n    .arrow{\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        height: 2.2rem;\r\n        width: 2.2rem;\r\n        background-color: v.$azul50;\r\n        border-radius: 50%;\r\n        color: v.$blanco;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    &.open~ .list-items{\r\n            display: block;\r\n    }\r\n\r\n     &.open .arrow{\r\n        transform: rotate(-180deg);\r\n     } \r\n    \r\n}\r\n\r\n.list-items{\r\n    display: none;\r\n    min-width: 26.3rem;\r\n    max-width: 32rem;\r\n    position: absolute;\r\n    z-index: 15;\r\n    margin-top: 1.4rem;\r\n    background-color: v.$blanco;\r\n    border-radius: 1rem;\r\n    padding: 2rem 1.5rem 0rem 1.5rem;\r\n    .item{\r\n        height: 4rem;\r\n        color: v.$gris70;\r\n    }\r\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.lineaencabezado {\r\n    font-family: v.$fuente-secundaria;\r\n    background-color: v.$azul100;\r\n    padding: 1.1rem 3rem;\r\n    color:v.$azul0;\r\n    text-align: center;\r\n    text-transform: uppercase;\r\n    font-weight: 400;\r\n    h1 {\r\n        font-size: 2.5rem;\r\n    }\r\n}\r\n.mensajetitulo {\r\n    @include m.desktop { \r\n        padding: 0 13rem;\r\n    }\r\n}\r\n.auth{\r\n    \r\n    /*max-width: 35rem;\r\n    width: 100%;\r\n    margin: 0 auto;*/\r\n    // padding: 2rem;\r\n    &__mensaje {\r\n        margin: 0 1.5rem;\r\n        @include m.desktop { \r\n            padding: 0 13rem;\r\n        }\r\n        p {\r\n            text-align: justify;\r\n            line-height: 1.4;\r\n        }\r\n    }\r\n    h2 {\r\n        margin: 1rem 1.5rem 2rem 1.5rem;\r\n    }\r\n    &__btnatras{\r\n        background-color: v.$gris50;\r\n        color: v.$blanco;\r\n        padding: 1rem 2rem;\r\n        border-radius: .35rem;\r\n        &:hover {\r\n            background-color: v.$azul100;\r\n        }\r\n    }\r\n    &__logocliente {\r\n        width: 15rem;\r\n    }\r\n    &__heading{\r\n        margin-top: 1rem;\r\n        color: v.$azul100;\r\n        text-transform: uppercase;\r\n    }\r\n    &__texto{\r\n        margin-top: 0rem;\r\n        color: v.$gris50;\r\n    }\r\n    .formulario{\r\n\r\n        &__campo{\r\n            gap: .3rem;\r\n            margin-bottom: 1.1rem;\r\n        }\r\n        &__label{\r\n            font-size: 1.4rem;\r\n        }\r\n        &__input{\r\n            padding: 1.5rem 1rem;\r\n        }\r\n    }\r\n}\r\n.bloqueauth {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: stretch;\r\n    justify-content: center;\r\n    width: 100%;\r\n    position: relative;\r\n    margin-top: -4rem;\r\n    z-index: 103;\r\n    @include m.telefonomini { \r\n        margin-top: 0;\r\n    }\r\n\r\n    // height: 100%;\r\n    @include m.tablet { \r\n        padding: 0 4rem; \r\n    }\r\n    @include m.desktop { \r\n        padding: 0 7rem;\r\n    }\r\n    &__btnregresar {\r\n       max-width: 11rem;\r\n       margin-top: 1rem;\r\n       margin-left: 1rem;\r\n       text-align: center;\r\n       padding: 1.5rem 0;\r\n    }\r\n    &__logocliente {\r\n        align-items: center;\r\n        max-width: 17rem;\r\n        margin: 3rem auto 1.3rem auto;\r\n    }\r\n    \r\n    &__logosinslider {\r\n        margin: 6rem auto 1.3rem auto;\r\n    }\r\n    \r\n    &__iniciarsesion {\r\n        color: v.$azul100;\r\n        text-align: center;\r\n        text-transform: capitalize;\r\n        font-size: 2.5rem;\r\n    }\r\n    &__subtitulo {\r\n        text-align: center;\r\n        margin-top: 1.2rem;\r\n    }\r\n}\r\n\r\n.bloqueformulario {\r\n    margin: 0 2.2rem;\r\n    @include m.desktop { \r\n        padding: 0 20rem;\r\n    }\r\n}\r\n.slider {\r\n    overflow: hidden;\r\n    // position: relative;\r\n    &__contenido {\r\n        padding: 0;\r\n        margin: 0;\r\n        \r\n    }\r\n    &__slide1 {\r\n        background-image: url(/build/img/slider1.jpg);\r\n    }\r\n    &__slide2 {\r\n        background-image: url(/build/img/slider2.jpg);\r\n    }\r\n    &__slide {\r\n        flex-shrink: 0;\r\n        position: relative;\r\n        width: 100%;\r\n        height: 4vh;\r\n        transition-property: transform;\r\n        background-repeat: no-repeat;\r\n        background-size: cover;\r\n        background-position : 0px -63px;\r\n        @include m.telefono { \r\n            height: 0vh;  \r\n        }\r\n        @include m.tablet { \r\n            display: none;\r\n        }\r\n    }\r\n}\r\n.slider {\r\n    &__contenido {\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: center;\r\n        li {\r\n            font-size: 3rem;\r\n            color: v.$blanco;\r\n            background-color: v.$blanco;\r\n            text-align: center;\r\n            align-items: center;\r\n            justify-content: center;\r\n        }\r\n    }\r\n}\r\n\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n\r\n.dashboard{\r\n    &.swal2-height-auto{  //clase interna que se agrega por js de sweetalert  una espacion al final con esto se quita\r\n        height: 100% !important;\r\n    }\r\n    \r\n    background-color: v.$azul0;\r\n    @include m.tablet{\r\n        display: flex;\r\n        height: 100vh;\r\n    }\r\n    .principal{ //clase esta en header_dashboard.php\n        background-color: