\n            .menux{\r\n                img{ \r\n                    width: 1.8rem;\r\n                    &:hover{\r\n                        cursor: pointer;\r\n                    }\r\n                }\r\n                @include m.tablet{\r\n                    display: none;\r\n                }\n            }\n        }\n        .sidebar-mini-logo{\n            background-color: rgba(255, 255, 255, .08);\n            border: 1px solid rgba(255, 255, 255, .20);\n            border-radius: 1.2rem;\n            display: block;\n            height: 5.8rem;\n            object-fit: contain;\n            padding: .35rem;\n            width: 5.8rem;\n        }\n        #logoj2{\n            display: none;\n            opacity: 0;\n            transform: scale(.85);\n            transition: opacity 300ms ease, transform 300ms ease;\n        }\n\n        &:hover,\n        &.sidebar-fija{\n            .uptask{\n                padding: 0 3rem;\n                justify-content: space-between;\n            }\n            .sidebar-mini-logo{\n                display: none;\n            }\n            #logoj2{\n                display: block;\n                opacity: 1;\n                transform: scale(1);\n            }\n        }\n\n        .noneElement{ //clase agregada en app.ts\n            display: none;\n        }\n        \r\n        &.minsidebar{ //clase agregada en app.ts\r\n            width: 8.5rem;\r\n        }\r\n\r\n        .sidebar-nav{\n            margin-top: 3.2rem;\n            a{              //el tamaÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â±o de las letras de los links a esta definido en globales.scss de 1.6rem\r\n                white-space: nowrap;\r\n                color: v.$gris30; //blanco\r\n                display: block;\r\n                margin-bottom: .8rem;\r\n                padding: 1.2rem;\n                transition-property: background-color;\r\n                transition-duration: 300ms;\n                font-size: 1.4rem;\n                text-align: center;\n                overflow: hidden;\n                .material-symbols-outlined{\n                    font-size: 2.9rem;\n                    min-width: 2.9rem;\n                }\n                label{\n                    cursor: pointer;\n                    max-width: 0;\n                    opacity: 0;\n                    overflow: hidden;\n                    transition: max-width 300ms ease, opacity 200ms ease;\n                }\n                &:hover{\n                    background-color: rgba(255, 255, 255, .14);\n                    border-radius: 0.5rem;\n                    color: v.$gris30;\n                }\n                &.activo{\n                    background-color: v.$azul0;\n                    border-radius: 0.5rem;\n                    color: v.$indigo;\n                }\n                @include m.tablet{\n                    display: flex;\n                    align-items: center;\n                    justify-content: center;\n                    gap: 0;\n                    font-size: 1.2rem;\n                    margin-bottom: .8rem;\n                    min-height: 5.4rem;\n                    text-align: left;\n                }\n            }\n        }\n\n        &:hover,\n        &.sidebar-fija{\n            .sidebar-nav{\n                margin-top: 5rem;\n                a{\n                    label{\n                        max-width: 16rem;\n                        opacity: 1;\n                    }\n                    @include m.tablet{\n                        justify-content: flex-start;\n                        gap: .5rem;\n                    }\n                }\n            }\n        }\n    \r\n    \r\n        .cerrar-sesion-mobile{  //clase al boton cerrar sesion que esta en el sidebar barra lateral\r\n            margin-top: 10rem;\r\n            @include m.tablet{\r\n               display: none;\r\n            }\r\n            p{\r\n                text-align: center;\r\n                margin: 0;\r\n                font-size: 1.4rem;\r\n                color: v.$cyan;\r\n                span{\r\n                    color: v.$blanco;\r\n                    font-weight: 700;\r\n                }\r\n            }\r\n            .cerrar-sesion{\r\n                @include m.boton(v.$indigo, v.$blanco);\r\n            }\r\n        }//cierre del .cerrar-sesion-mobile\r\n    \r\n    }//cierre del .sidebar\r\n\r\n\r\n\r\n    .barra-mobile{  //clase que esta en header.php, crea sub barra para ocultar los links <a> del sidebar en dispositivos moviles\n        &.ocultarmenu{\n            display: none;\n        }\n        background-color: v.$indigo;\n        margin-top: 0;\n        padding: 2rem 4rem;\n        position: sticky;\n        top: 0;\n        z-index: 25;\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        @include m.tablet{\r\n            display: none;\r\n        }\r\n        h1{\r\n            color: v.$blanco;\r\n            margin: 0;\r\n        }\r\n        .menu{  \r\n            img{   //iamgen de los 3 botoncitos\r\n                width: .8rem;\r\n                &:hover{\r\n                    cursor: pointer;\r\n                }\r\n            }\r\n        }\n    }\n\n    .subscription-alert-wrap{\n        align-items: center;\n        flex: 1 1 auto;\n        justify-content: center;\n        min-width: 0;\n        padding: 0 1.6rem;\n    }\n\n    .subscription-alert-wrap--mobile{\n        display: flex;\n        flex: 0 0 auto;\n        margin-top: 1.2rem;\n        padding: 0;\n        width: 100%;\n    }\n\n    .subscription-alert{\n        align-items: center;\n        background: linear-gradient(135deg, #fff7ed 0%, #fff1f2 100%);\n        border: .1rem solid #fecaca;\n        border-radius: 1.4rem;\n        box-shadow: 0 .8rem 2rem rgba(239, 68, 68, .12);\n        color: #7f1d1d;\n        cursor: pointer;\n        display: flex;\n        gap: 1rem;\n        max-width: 86rem;\n        min-height: 5.4rem;\n        overflow: hidden;\n        padding: .7rem 1.2rem .7rem .9rem;\n        position: relative;\n        text-decoration: none;\n        transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;\n        width: 100%;\n    }\n\n    .subscription-alert:hover{\n        border-color: #fb7185;\n        box-shadow: 0 1.1rem 2.6rem rgba(239, 68, 68, .18);\n        transform: translateY(-.1rem);\n    }\n\n    .subscription-alert::before{\n        background: linear-gradient(180deg, #ef4444, #f97316);\n        content: \"\";\n        height: 100%;\n        left: 0;\n        position: absolute;\n        top: 0;\n        width: .35rem;\n    }\n\n    .subscription-alert__icon{\n        align-items: center;\n        background: #fee2e2;\n        border-radius: 1rem;\n        color: #dc2626;\n        display: inline-flex;\n        flex: 0 0 3.2rem;\n        font-size: 2rem;\n        height: 3.2rem;\n        justify-content: center;\n        width: 3.2rem;\n    }\n\n    .subscription-alert__body{\n        align-items: flex-start;\n        display: flex;\n        flex-direction: column;\n        gap: .2rem;\n        min-width: 0;\n        overflow: hidden;\n    }\n\n    .subscription-alert__title{\n        color: #991b1b;\n        font-size: 1.25rem;\n        font-weight: 900;\n        line-height: 1.15;\n        max-width: 100%;\n        overflow: hidden;\n        text-overflow: ellipsis;\n        white-space: nowrap;\n    }\n\n    .subscription-alert__message{\n        color: #9f1239;\n        display: -webkit-box;\n        font-size: 1.12rem;\n        font-weight: 600;\n        line-height: 1.18;\n        min-width: 0;\n        overflow: hidden;\n        white-space: normal;\n        -webkit-box-orient: vertical;\n        -webkit-line-clamp: 2;\n    }\n\n    @media (max-width: 767px){\n        .subscription-alert{\n            align-items: flex-start;\n            border-radius: 1.2rem;\n            max-width: none;\n            min-height: auto;\n            padding: .8rem 1rem;\n        }\n\n        .subscription-alert__body{\n            align-items: flex-start;\n            flex-direction: column;\n            gap: .2rem;\n        }\n\n        .subscription-alert__message{\n            display: -webkit-box;\n            overflow: hidden;\n            white-space: normal;\n            -webkit-box-orient: vertical;\n            -webkit-line-clamp: 2;\n        }\n    }\n\n    .menu-mobile-bottom{\n        display: block;\n\n        @include m.tablet{\n            display: none;\n        }\n    }\n    \n///////////////////////estilos al header.php /////////////////////////////\n    .barra{\r\n        display: none;\r\n        background-color: v.$blanco;\r\n        /*background: rgb(239,242,247);\r\n        background: linear-gradient(90deg, rgba(239,242,247,1) 2%, rgba(255,255,255,1) 13%);*/\r\n        padding: 1rem 2rem;\r\n        box-shadow: 1px 12px 9px -13px rgba(0, 0, 0, .4);\r\n        @include m.tablet{\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n        }\r\n        .toggleanduser{\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 1rem;\r\n            .sidebartoggle{\r\n                cursor: pointer;\r\n            }\r\n            p{\r\n                margin: 0;\r\n                font-size: 1.4rem;\r\n                span{\r\n                    color: v.$indigo;\r\n                    font-weight: 700;\r\n                }\r\n            }\r\n        }\r\n        .cerrar-sesion{  // etiqueta <a> de cerrar sesion\r\n            @include m.boton(darken(v.$indigo, 20%), v.$blanco);\r\n            width: auto;\r\n        }\r\n    }\r\n    \r\n}\n\r\n\r\n\n    .precios-adicionales-tabs-wrap{\n        justify-content: flex-start !important;\n        max-width: 100%;\n        overflow-x: visible;\n        padding: .2rem 0 .4rem;\n    }\n\n    .precios-adicionales-tabs{\n        background: rgba(255, 255, 255, .96);\n        border: 1px solid #cbd5e1;\n        border-radius: .8rem;\n        box-shadow: 0 8px 22px rgba(15, 23, 42, .08);\n        display: grid;\n        gap: .55rem;\n        grid-template-columns: repeat(4, minmax(0, 1fr));\n        min-width: 0;\n        padding: .55rem;\n        width: 100%;\n    }\n\n    .precios-adicionales-tab{\n        align-items: center;\n        background: #fff;\n        border: 1px solid #d7e0ee;\n        border-radius: .65rem;\n        color: #263852;\n        cursor: pointer;\n        display: flex;\n        font-size: 1.1rem;\n        font-weight: 700;\n        gap: .45rem;\n        height: 4.1rem;\n        justify-content: center;\n        line-height: 1;\n        min-width: 0;\n        overflow: hidden;\n        padding: 0 .75rem;\n        text-overflow: ellipsis;\n        transition: background .2s ease, border-color .2s ease, box-shadow .2s ease, color .2s ease, transform .2s ease;\n        white-space: nowrap;\n\n        .material-symbols-outlined{\n            color: #4f46e5;\n            font-size: 1.65rem;\n            line-height: 1;\n        }\n\n        &:hover{\n            border-color: rgba(79,70,229,.38);\n            box-shadow: 0 8px 18px rgba(79,70,229,.10);\n            transform: translateY(-1px);\n        }\n    }\n\n#miDialogoPreciosAdicionales{\n    h3{\n        font-size: 1.78rem !important;\n        line-height: 1.12 !important;\n    }\n\n    h4,\n    h5{\n        font-size: 1.38rem !important;\n        line-height: 1.15 !important;\n    }\n\n    p{\n        font-size: 1.02rem !important;\n        line-height: 1.32 !important;\n    }\n\n    label{\n        font-size: .96rem !important;\n        line-height: 1.2 !important;\n    }\n\n    #btnMostrarNuevoPrecio{\n        font-size: 1.02rem !important;\n    }\n\n    #inputCantidadCalculada{\n        font-size: 1.38rem !important;\n    }\n\n    #lastOperation{\n        font-size: 1.08rem !important;\n    }\n\n    #textCantidadCalculada{\n        font-size: 3.35rem !important;\n    }\n}\n\n#miDialogoAddCliente{\n    h4{\n        line-height: 1.12 !important;\n    }\n\n    h5,\n    .etiqueta .block.text-xl{\n        line-height: 1.12 !important;\n    }\n\n    p,\n    .etiqueta .block.text-base{\n        line-height: 1.28 !important;\n    }\n\n    label{\n        line-height: 1.15 !important;\n    }\n\n    .formulario__campo{\n        gap: .35rem;\n        margin-bottom: 1rem;\n    }\n}\n\nbody.dashboardno{\n    @media (max-width: 767px){\n        background-color: v.$indigo;\n\n        .dashboard{\n            background-color: v.$indigo;\n            display: block;\n            min-height: 100vh;\n        }\n\n        .dashboard,\n        .principal{\n            margin-top: 0;\n            padding-top: 0;\n        }\n\n        .principal{\n            background-color: transparent;\n            overflow: visible;\n        }\n\n        .contenido{\n            background-color: v.$azul0;\n        }\n\n        .barra-mobile{\n            align-items: center;\n            justify-content: center;\n            display: flex;\n            flex-direction: column;\n            gap: .8rem;\n            margin-top: 0;\n            padding: 1.2rem 2rem;\n            position: relative;\n            top: auto;\n\n            .barra-mobile__logo{\n                align-items: center;\n                display: flex;\n                justify-content: center;\n                line-height: 0;\n                max-width: 100%;\n                width: auto;\n            }\