important;\n        min-width: 4.8rem !important;\n        width: 5rem !important;\n    }\n\n    #tablaventa td:nth-child(2) button{\n        height: 2.1rem !important;\n        width: 2.1rem !important;\n    }\n\n    #tablaventa td:nth-child(3),\n    #tablaventa td:nth-child(4){\n        font-size: 1.06rem !important;\n        font-weight: 800 !important;\n        white-space: nowrap;\n    }\n}\n\n@media (max-width: 460px){\n    #tablaventa .productselect{\n        gap: .5rem .42rem;\n        grid-template-columns: minmax(11.6rem, 1fr) minmax(6.1rem, auto) minmax(7.1rem, auto) 2.8rem;\n        padding-left: .55rem !important;\n        padding-right: .55rem !important;\n    }\n\n    #tablaventa td{\n        font-size: .96rem !important;\n        gap: .2rem;\n    }\n\n    #tablaventa td::before{\n        font-size: .76rem;\n    }\n\n    #tablaventa .inputcantidad{\n        font-size: 1.02rem !important;\n        height: 2.6rem !important;\n        max-width: 4.8rem !important;\n        min-width: 4.4rem !important;\n        width: 4.6rem !important;\n    }\n\n    #tablaventa td:nth-child(2) > div{\n        gap: .24rem !important;\n    }\n\n    #tablaventa td:nth-child(2) button{\n        height: 2rem !important;\n        width: 2rem !important;\n    }\n\n    #tablaventa td:nth-child(3),\n    #tablaventa td:nth-child(4){\n        font-size: .96rem !important;\n    }\n}\n\n.producto.producto-agregado-feedback{\n    background-color: #ffffff !important;\n    border-color: #818cf8 !important;\n    box-shadow: 0 0 0 .18rem rgba(99, 102, 241, .28), 0 1.2rem 2.4rem rgba(15, 23, 42, .10) !important;\n    position: relative;\n}\n\n.producto.producto-agregado-feedback::after{\n    align-items: center;\n    background: #22c55e;\n    border: .25rem solid #ffffff;\n    border-radius: 999px;\n    box-shadow: 0 .7rem 1.6rem rgba(34, 197, 94, .28);\n    color: #ffffff;\n    content: \"\\f00c\";\n    display: flex;\n    font-family: \"Font Awesome 6 Free\";\n    font-size: 1.35rem;\n    font-weight: 900;\n    height: 2.8rem;\n    justify-content: center;\n    line-height: 1;\n    position: absolute;\n    right: .8rem;\n    top: .8rem;\n    width: 2.8rem;\n    z-index: 2;\n}\n\n#facturarA.ventas-action-btn{\n    background: #ffffff;\n    border-color: #cbd5e1;\n    box-shadow: 0 2px 6px rgba(15, 23, 42, .08);\n    color: #0f172a;\n}\n\n#facturarA.ventas-action-btn:hover{\n    background: #f8fafc;\n    border-color: #94a3b8;\n    box-shadow: 0 8px 18px rgba(15, 23, 42, .10);\n}\n\n@include m.desktop{\n    .ventas-actions-grid{\n        grid-template-columns: repeat(3, minmax(0, 1fr)) !important;\n    }\n\n    .ventas-action-adquiriente{\n        grid-column: auto !important;\n    }\n}\n\n#addcliente.cliente-required-pulse{\n    animation: clienteRequiredPulse 1.05s ease-in-out 3;\n    border-color: #f59e0b !important;\n    box-shadow: 0 0 0 .35rem rgba(245, 158, 11, .18), 0 1rem 2.4rem rgba(15, 23, 42, .12) !important;\n}\n\n#addcliente.cliente-required-pulse #iconCliente{\n    background: #fff7ed !important;\n    color: #d97706 !important;\n}\n\n#addcliente.cliente-required-pulse #badgeEstado{\n    background: #fff7ed !important;\n    color: #b45309 !important;\n}\n\n@keyframes clienteRequiredPulse{\n    0%, 100%{\n        transform: translateY(0);\n        box-shadow: 0 0 0 .18rem rgba(245, 158, 11, .12), 0 .4rem 1rem rgba(15, 23, 42, .08);\n    }\n    50%{\n        transform: translateY(-.2rem);\n        box-shadow: 0 0 0 .48rem rgba(245, 158, 11, .26), 0 1.2rem 2.8rem rgba(15, 23, 42, .14);\n    }\n}\n","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.clientes,\n.detallecliente{\n  --clientes-primary: #4f46e5;\n  --clientes-primary-dark: #4338ca;\n  --clientes-accent: #06b6d4;\n  --clientes-border: #dbe3ef;\n  --clientes-muted: #64748b;\n  --clientes-text: #14233b;\n  --clientes-soft: #f8fafc;\n\n  @include m.contenedor100;\n  color: var(--clientes-text);\n  padding-bottom: 3rem;\n}\n\n.cliente-detail-shell{\n  background:\n    linear-gradient(180deg, rgba(79,70,229,.06), rgba(255,255,255,0) 18rem),\n    #fff;\n  border: 1px solid var(--clientes-border);\n  border-radius: .8rem;\n  box-shadow: 0 12px 28px rgba(15, 23, 42, .06);\n  display: grid;\n  gap: 1.4rem;\n  margin: 0 auto;\n  max-width: 140rem;\n  padding: 1.6rem;\n}\n\n.cliente-detail-hero{\n  align-items: center;\n  background: linear-gradient(135deg, rgba(79,70,229,.09), rgba(6,182,212,.07));\n  border: 1px solid var(--clientes-border);\n  border-radius: .8rem;\n  display: flex;\n  gap: 1.2rem;\n  padding: 1.6rem;\n}\n\n.cliente-detail-back{\n  align-items: center;\n  background: linear-gradient(135deg, #5b52f0, var(--clientes-primary-dark));\n  border-radius: .7rem;\n  box-shadow: 0 10px 22px rgba(79,70,229,.20);\n  color: #fff;\n  display: inline-flex;\n  flex: 0 0 4.6rem;\n  font-size: 1.6rem;\n  height: 4.6rem;\n  justify-content: center;\n  transition: transform .2s ease, box-shadow .2s ease;\n  width: 4.6rem;\n\n  &:hover{\n    box-shadow: 0 12px 26px rgba(79,70,229,.26);\n    color: #fff;\n    transform: translateY(-1px);\n  }\n}\n\n.cliente-detail-eyebrow{\n  color: var(--clientes-primary);\n  font-size: 1.05rem;\n  font-weight: 800;\n  letter-spacing: 0;\n  margin: 0 0 .25rem;\n  text-transform: uppercase;\n}\n\n.cliente-detail-hero__content{\n  flex: 1;\n  min-width: 0;\n\n  h1{\n    color: var(--clientes-text);\n    font-size: 2.55rem;\n    font-weight: 800;\n    line-height: 1.1;\n    margin: 0;\n    overflow-wrap: anywhere;\n  }\n\n  p:not(.cliente-detail-eyebrow){\n    color: var(--clientes-muted);\n    font-size: 1.18rem;\n    line-height: 1.35;\n    margin: .35rem 0 0;\n  }\n}\n\n.cliente-detail-hero__badge{\n  align-items: center;\n  background: rgba(255,255,255,.9);\n  border: 1px solid rgba(219,227,239,.92);\n  border-radius: .8rem;\n  display: flex;\n  flex: 0 0 auto;\n  gap: .9rem;\n  min-width: 20rem;\n  padding: .95rem;\n\n  > span{\n    align-items: center;\n    background: linear-gradient(135deg, #5b52f0, var(--clientes-primary-dark));\n    border-radius: .75rem;\n    color: #fff;\n    display: inline-flex;\n    flex: 0 0 4.6rem;\n    font-size: 1.85rem;\n    height: 4.6rem;\n    justify-content: center;\n    width: 4.6rem;\n  }\n\n  strong,\n  small{\n    display: block;\n  }\n\n  strong{\n    color: var(--clientes-text);\n    font-size: 1.9rem;\n    font-weight: 900;\n    line-height: 1;\n  }\n\n  small{\n    color: var(--clientes-muted);\n    font-size: 1.02rem;\n    font-weight: 700;\n    margin-top: .2rem;\n  }\n}\n\n.cliente-detail-profile-card,\n.cliente-detail-card{\n  background: #fff;\n  border: 1px solid var(--clientes-border);\n  border-radius: .8rem;\n  box-shadow: 0 10px 22px rgba(15, 23, 42, .045);\n  padding: 1.5rem;\n}\n\n.cliente-detail-profile-card__header,\n.cliente-detail-card__header{\n  align-items: center;\n  border-bottom: 1px solid var(--clientes-border);\n  display: flex;\n  gap: 1rem;\n  margin-bottom: 1.35rem;\n  padding-bottom: 1rem;\n\n  > span{\n    align-items: center;\n    background: rgba(79,70,229,.10);\n    border-radius: .7rem;\n    color: var(--clientes-primary);\n    display: inline-flex;\n    flex: 0 0 4.2rem;\n    font-size: 1.7rem;\n    height: 4.2rem;\n    justify-content: center;\n    width: 4.2rem;\n  }\n\n  h2{\n    color: var(--clientes-text);\n    font-size: 1.65rem;\n    font-weight: 800;\n    line-height: 1.15;\n    margin: 0;\n  }\n\n  p{\n    color: var(--clientes-muted);\n    font-size: 1.08rem;\n    line-height: 1.35;\n    margin: .2rem 0 0;\n  }\n}\n\n.cliente-detail-info-grid{\n  display: grid;\n  gap: 1rem;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.cliente-detail-info-item{\n  align-items: center;\n  background: #f8fafc;\n  border: 1px solid #e6edf7;\n  border-radius: .75rem;\n  display: flex;\n  gap: .9rem;\n  min-width: 0;\n  padding: 1rem;\n\n  > span{\n    align-items: center;\n    background: #eef2ff;\n    border-radius: .65rem;\n    color: var(--clientes-primary);\n    display: inline-flex;\n    flex: 0 0 3.8rem;\n    font-size: 1.45rem;\n    height: 3.8rem;\n    justify-content: center;\n    width: 3.8rem;\n  }\n\n  small,\n  strong{\n    display: block;\n  }\n\n  small{\n    color: var(--clientes-muted);\n    font-size: .98rem;\n    font-weight: 700;\n  }\n\n  strong{\n    color: var(--clientes-text);\n    font-size: 1.12rem;\n    font-weight: 800;\n    margin-top: .2rem;\n    overflow-wrap: anywhere;\n  }\n}\n\n.cliente-detail-kpis{\n  display: grid;\n  gap: 1rem;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.cliente-detail-kpi{\n  align-items: center;\n  background: #fff;\n  border: 1px solid var(--clientes-border);\n  border-radius: .8rem;\n  box-shadow: 0 10px 20px rgba(15, 23, 42, .045);\n  display: flex;\n  gap: 1rem;\n  min-width: 0;\n  padding: 1.25rem;\n\n  > span{\n    align-items: center;\n    border-radius: .75rem;\n    display: inline-flex;\n    flex: 0 0 4.6rem;\n    font-size: 1.85rem;\n    height: 4.6rem;\n    justify-content: center;\n    width: 4.6rem;\n  }\n\n  small,\n  strong{\n    display: block;\n  }\n\n  small{\n    color: var(--clientes-muted);\n    font-size: 1rem;\n    font-weight: 700;\n  }\n\n  strong{\n    color: var(--clientes-text);\n    font-size: 1.75rem;\n    font-weight: 900;\n    line-height: 1.1;\n    margin-top: .25rem;\n    overflow-wrap: anywhere;\n  }\n}\n\n.cliente-detail-kpi--emerald > span{\n  background: #ecfdf5;\n  color: #059669;\n}\n\n.cliente-detail-kpi--purple > span{\n  background: #eef2ff;\n  color: var(--clientes-primary);\n}\n\n.cliente-detail-kpi--cyan > span{\n  background: #ecfeff;\n  color: #0e7490;\n}\n\n.cliente-detail-kpi--rose > span{\n  background: #fff1f2;\n  color: #e11d48;\n}\n\n.cliente-detail-chart-grid{\n  display: grid;\n  gap: 1.4rem;\n  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n}\n\n.cliente-detail-chart{\n  height: 30rem;\n  min-width: 0;\n  position: relative;\n\n  canvas{\n    max-height: 100%;\n  }\n}\n\n.cliente-detail-chart--compact{\n  margin: 0 auto;\n  max-width: 34rem;\n}\n\n.cliente-detail-debtbar{\n  background: #fff;\n  border: 1px solid var(--clientes-border);\n  border-radius: .8rem;\n  box-shadow: 0 8px 22px rgba(15, 23, 42, .045);\n  display: flex;\n  flex-wrap: wrap;\n  gap: .9rem;\n  padding: 1rem;\n}\n\n.cliente-detail-debt-button{\n  align-items: center;\n  border-radius: .7rem;\n  cursor: pointer;\n  display: inline-flex;\n  font-size: 1.14rem;\n  font-weight: 800;\n  gap: .8rem;\n  justify-content: center;\n  min-height: 5rem;\n  padding: 1rem 1.25rem;\n  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;\n\n  > span:first-child{\n    align-items: center;\n    border-radius: .62rem;\n    display: inline-flex;\n    flex: 0 0 3.4rem;\n    height: 3.4rem;\n    justify-content: center;\n    width: 3.4rem;\n  }\n\n  strong{\n    margin-left: .35rem;\n  }\n\n  &:hover{\n    transform: translateY(-1px);\n  }\n}\n\n.cliente-detail-debt-button--summary{\n  background: #fff;\n  border: 1px solid #cbd5e1;\n  color: var(--clientes-text);\n\n  > span:first-child{\n    background: #eef2ff;\n    color: var(--clientes-primary);\n  }\n}\n\n.cliente-detail-debt-button--pay{\n  background: linear-gradient(135deg, #5b52f0, var(--clientes-primary-dark));\n  border: 0;\n  box-shadow: 0 12px 24px rgba(79,70,229,.22);\n  color: #fff;\n\n  > span:first-child{\n    background: rgba(255,255,255,.16);\n  }\n}\n\n.cliente-detail-debt-button--installments{\n  background: #ecfeff;\n  border: 1px solid #67e8f9;\n  color: #0e7490;\n\n  > span:first-child{\n    background: rgba(6,182,212,.12);\n  }\n}\n\n.cliente-detail-table-wrap{\n  scrollbar-color: #4f46e5 #eef2ff;\n  scrollbar-width: thin;\n  overflow-x: auto;\n  width: 100%;\n\n  &::-webkit-scrollbar{\n    height: .9rem;\n  }\n\n  &::-webkit-scrollbar-track{\n    background: #eef2ff;\n    border-radius: 999px;\n  }\n\n  &::-webkit-scrollbar-thumb{\n    background: linear-gradient(90deg, #4f46e5, #06b6d4);\n    border: 2px solid #eef2ff;\n    