ash-teal: #0f766e;\n  --dash-green: #059669;\n  --dash-red: #dc2626;\n  --dash-amber: #d97706;\n  --dash-border: #dbe4f0;\n  --dash-muted: #64748b;\n  --dash-text: #14233a;\n  --dash-soft: #f8fafc;\n\n  background:\n    linear-gradient(180deg, rgba(79,70,229,.06), rgba(255,255,255,0) 18rem),\n    #fff;\n  border: 1px solid var(--dash-border);\n  border-radius: .8rem;\n  box-shadow: 0 12px 28px rgba(15, 23, 42, .06);\n  color: var(--dash-text);\n  padding: 1.6rem;\n}\n\n.dashboard-home__inner{\n  display: flex;\n  flex-direction: column;\n  gap: 1.45rem;\n  min-width: 0;\n}\n\n.dashboard-home__header{\n  align-items: flex-start;\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n  padding-bottom: .25rem;\n}\n\n.dashboard-home__eyebrow{\n  color: var(--dash-primary);\n  font-size: 1.1rem;\n  font-weight: 800;\n  margin: 0 0 .25rem;\n  text-transform: uppercase;\n}\n\n.dashboard-home__header h1{\n  color: var(--dash-text);\n  font-size: 2.8rem;\n  font-weight: 900;\n  line-height: 1.1;\n  margin: 0;\n}\n\n.dashboard-home__subtitle{\n  color: var(--dash-muted);\n  font-size: 1.35rem;\n  margin: .35rem 0 0;\n}\n\n.dashboard-home__actions{\n  display: flex;\n  flex-wrap: wrap;\n  gap: .8rem;\n  justify-content: flex-end;\n}\n\n.dashboard-action{\n  align-items: center;\n  border-radius: .65rem;\n  cursor: pointer;\n  display: inline-flex;\n  font-size: 1.35rem;\n  font-weight: 800;\n  gap: .65rem;\n  min-height: 4.4rem;\n  padding: 0 1.3rem;\n  transition: background .2s ease, border-color .2s ease, box-shadow .2s ease, color .2s ease, transform .2s ease;\n\n  .material-symbols-outlined{\n    font-size: 2rem;\n  }\n\n  &:hover{\n    transform: translateY(-1px);\n  }\n}\n\n.dashboard-action--ghost{\n  background: #fff;\n  border: 1px solid var(--dash-border);\n  color: #263852;\n\n  &:hover{\n    border-color: rgba(79,70,229,.35);\n    box-shadow: 0 8px 18px rgba(15,23,42,.07);\n  }\n}\n\n.dashboard-action--primary{\n  background: linear-gradient(135deg, #5b52f0, var(--dash-primary-dark));\n  border: 1px solid var(--dash-primary-dark);\n  box-shadow: 0 12px 24px rgba(79,70,229,.22);\n  color: #fff;\n}\n\n.dashboard-kpis{\n  display: grid;\n  gap: 1rem;\n}\n\n.dashboard-kpis--primary{\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.dashboard-kpis--secondary{\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n}\n\n.dashboard-kpi{\n  background: #fff;\n  border: 1px solid var(--dash-border);\n  border-radius: .8rem;\n  box-shadow: 0 8px 18px rgba(15, 23, 42, .045);\n  display: flex;\n  flex-direction: column;\n  gap: .85rem;\n  min-height: 13.2rem;\n  overflow: hidden;\n  padding: 1.35rem;\n  position: relative;\n}\n\n.dashboard-kpi::before{\n  background: var(--dash-primary);\n  content: \"\";\n  height: .35rem;\n  inset: 0 0 auto;\n  position: absolute;\n}\n\n.dashboard-kpi__top{\n  align-items: center;\n  display: flex;\n  gap: .75rem;\n}\n\n.dashboard-kpi__icon{\n  align-items: center;\n  background: rgba(79,70,229,.10);\n  border-radius: .65rem;\n  color: var(--dash-primary);\n  display: inline-flex;\n  flex: 0 0 4rem;\n  font-size: 2.4rem;\n  height: 4rem;\n  justify-content: center;\n}\n\n.dashboard-kpi__label{\n  color: #526172;\n  font-size: 1.25rem;\n  font-weight: 800;\n  line-height: 1.2;\n  text-transform: uppercase;\n}\n\n.dashboard-kpi strong{\n  color: var(--dash-text);\n  display: block;\n  font-size: 2.65rem;\n  font-weight: 900;\n  line-height: 1.05;\n  overflow-wrap: anywhere;\n}\n\n.dashboard-kpi small{\n  color: var(--dash-muted);\n  font-size: 1.15rem;\n  line-height: 1.25;\n}\n\n.dashboard-kpi__pair{\n  display: grid;\n  gap: .8rem;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n.dashboard-kpi__pair > div{\n  background: var(--dash-soft);\n  border: 1px solid #e2e8f0;\n  border-radius: .65rem;\n  padding: .85rem;\n}\n\n.dashboard-kpi__product{\n  font-size: 2rem !important;\n  line-height: 1.18 !important;\n}\n\n.dashboard-kpi--success::before{ background: var(--dash-green); }\n.dashboard-kpi--success .dashboard-kpi__icon{ background: rgba(5,150,105,.11); color: var(--dash-green); }\n.dashboard-kpi--success strong{ color: var(--dash-green); }\n\n.dashboard-kpi--primary::before{ background: var(--dash-primary); }\n.dashboard-kpi--primary strong{ color: var(--dash-primary); }\n\n.dashboard-kpi--danger::before{ background: var(--dash-red); }\n.dashboard-kpi--danger .dashboard-kpi__icon{ background: rgba(220,38,38,.10); color: var(--dash-red); }\n.dashboard-kpi--danger strong{ color: var(--dash-red); }\n\n.dashboard-kpi--warning::before{ background: var(--dash-amber); }\n.dashboard-kpi--warning .dashboard-kpi__icon{ background: rgba(217,119,6,.11); color: var(--dash-amber); }\n.dashboard-kpi--warning strong{ color: var(--dash-amber); }\n\n.dashboard-kpi--neutral::before{ background: #334155; }\n.dashboard-kpi--neutral .dashboard-kpi__icon{ background: #f1f5f9; color: #334155; }\n\n.dashboard-charts,\n.dashboard-bottom{\n  display: grid;\n  gap: 1.2rem;\n  min-width: 0;\n}\n\n.dashboard-charts{\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n.dashboard-bottom{\n  grid-template-columns: minmax(0, 2fr) minmax(30rem, 1fr);\n  padding-bottom: 8rem;\n}\n\n.dashboard-panel{\n  background: #fff;\n  border: 1px solid var(--dash-border);\n  border-radius: .8rem;\n  box-shadow: 0 8px 18px rgba(15, 23, 42, .045);\n  min-width: 0;\n  padding: 1.35rem;\n}\n\n.dashboard-panel__head{\n  align-items: center;\n  border-bottom: 1px solid var(--dash-border);\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n  margin-bottom: 1.2rem;\n  padding-bottom: 1rem;\n}\n\n.dashboard-panel__head h2{\n  color: var(--dash-text);\n  font-size: 1.85rem;\n  font-weight: 900;\n  line-height: 1.15;\n  margin: 0;\n}\n\n.dashboard-panel__head p{\n  color: var(--dash-muted);\n  font-size: 1.2rem;\n  margin: .25rem 0 0;\n}\n\n.dashboard-panel__head > .material-symbols-outlined{\n  align-items: center;\n  background: rgba(79,70,229,.10);\n  border-radius: .65rem;\n  color: var(--dash-primary);\n  display: inline-flex;\n  flex: 0 0 4rem;\n  font-size: 2.35rem;\n  height: 4rem;\n  justify-content: center;\n}\n\n.dashboard-chart{\n  height: 30rem;\n  position: relative;\n  width: 100%;\n}\n\n.dashboard-chart canvas{\n  max-height: 100%;\n  width: 100% !important;\n}\n\n.dashboard-table-wrap{\n  overflow-x: auto;\n}\n\n.dashboard-table{\n  border-collapse: separate;\n  border-spacing: 0;\n  min-width: 68rem;\n  width: 100%;\n}\n\n.dashboard-table th{\n  background: #f6f8fb;\n  border-bottom: 1px solid #d5deea;\n  border-top: 1px solid #d5deea;\n  color: #26364d;\n  font-size: 1.25rem;\n  font-weight: 900;\n  padding: 1rem;\n  text-align: left;\n}\n\n.dashboard-table th:first-child{\n  border-left: 1px solid #d5deea;\n  border-radius: .55rem 0 0 .55rem;\n}\n\n.dashboard-table th:last-child{\n  border-right: 1px solid #d5deea;\n  border-radius: 0 .55rem .55rem 0;\n}\n\n.dashboard-table td{\n  border-bottom: 1px solid #e2e8f0;\n  color: #1e2d42;\n  font-size: 1.32rem;\n  padding: 1.05rem;\n}\n\n.dashboard-table td:nth-child(n+2){\n  font-weight: 700;\n  white-space: nowrap;\n}\n\n.dashboard-stock__list{\n  display: grid;\n  gap: .85rem;\n}\n\n.dashboard-stock__list li{\n  align-items: center;\n  background: var(--dash-soft);\n  border: 1px solid #e2e8f0;\n  border-radius: .7rem;\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n  padding: 1rem;\n}\n\n.dashboard-stock__list strong{\n  color: var(--dash-text);\n  display: block;\n  font-size: 1.35rem;\n  line-height: 1.25;\n}\n\n.dashboard-stock__list small{\n  color: var(--dash-muted);\n  display: block;\n  font-size: 1.15rem;\n  margin-top: .25rem;\n}\n\n.dashboard-stock__list b{\n  color: var(--dash-red);\n  display: block;\n  font-size: 1.6rem;\n  text-align: right;\n}\n\n\n.dashboard-panel:has(.dashboard-chart){\n  background: linear-gradient(180deg, rgba(248,251,255,.98), rgba(255,255,255,1));\n}\n\n.dashboard-panel:has(.dashboard-chart) .dashboard-chart{\n  background: linear-gradient(180deg, #f8fbff, #fff);\n  border: 1px solid rgba(219, 228, 240, .86);\n  border-radius: .8rem;\n  box-shadow: inset 0 1px 0 rgba(255,255,255,.95);\n  padding: 1.2rem;\n}\n\n.dashboard-panel:has(.dashboard-chart) .dashboard-panel__head{\n  margin-bottom: 1rem;\n}\n\n.dashboard-panel:has(.dashboard-chart) .dashboard-panel__head > .material-symbols-outlined{\n  background: linear-gradient(135deg, rgba(79,70,229,.12), rgba(6,182,212,.13));\n  color: var(--dash-primary);\n}\r\n@media (max-width: 1200px){\n  .dashboard-kpis--primary{\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .dashboard-bottom{\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 900px){\n  .dashboard-home{\n    padding: 1.1rem;\n  }\n\n  .dashboard-home__header{\n    flex-direction: column;\n  }\n\n  .dashboard-home__actions{\n    justify-content: stretch;\n    width: 100%;\n  }\n\n  .dashboard-action{\n    flex: 1 1 14rem;\n    justify-content: center;\n  }\n\n  .dashboard-kpis--secondary,\n  .dashboard-charts{\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 640px){\n  .dashboard-home{\n    border: 0;\n    border-radius: 0;\n    padding: 1rem;\n  }\n\n  .dashboard-home__header h1{\n    font-size: 2.35rem;\n  }\n\n  .dashboard-home__subtitle{\n    font-size: 1.25rem;\n  }\n\n  .dashboard-kpis--primary{\n    grid-template-columns: 1fr;\n  }\n\n  .dashboard-kpi{\n    min-height: 0;\n    padding: 1.15rem;\n  }\n\n  .dashboard-kpi strong{\n    font-size: 2.25rem;\n  }\n\n  .dashboard-chart{\n    height: 24rem;\n  }\n\n  .dashboard-panel{\n    padding: 1.1rem;\n  }\n\n  .dashboard-panel__head{\n    align-items: flex-start;\n  }\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.datos{\r\n    margin-top: 2rem;\r\n    &__contenedorgraficas{\r\n        margin-top: 0rem;\r\n        \r\n        @include m.xl_tablet{\r\n            display: flex;\r\n            gap: 1rem;\r\n        }\r\n        @include m.desktop{\r\n            gap: 1.5rem;\r\n        }\r\n        @include m.xl_desktop{\r\n            gap: 2rem;\r\n        }\r\n    }\r\n    &__grafica1{\r\n        background-color: v.$blanco;\r\n        padding: 1rem;\r\n        //flex-basis: calc(60% - 1rem);\r\n        @include m.xl_tablet{\r\n            width: 68%;\r\n        }\r\n       // @include m.contenedor-sm;\r\n       //width: 95%;\r\n        //max-width: 45rem;\r\n    }\r\n\r\n    &__completado{\r\n        //flex-basis: calc(40% - 1rem);\r\n        @include m.xl_tablet{\r\n            width: 31%;\r\n        }\r\n        background-color: v.$blanco;   \r\n    }\r\n    \r\n    &__bg{\r\n        position: relative;\r\n        height: 10rem;\r\n        background-image: url(/build/img/profile-img.png), linear-gradient(rgba(85,110,230,.25), rgba(85,110,230,.25));\r\n        background-repeat: no-repeat;\r\n        background-size: 15rem, cover;\r\n        background-position: center right;\r\n        padding: 2rem;\r\n    }\r\n    &__user{\r\n        position: absolute;\r\n        bottom: 0%;\r\n        left: 0%;\r\n        transform: translate(50%, 50%);\r\n        background-color: v.$blanco;\r\n        border-radius: 50%;\r\n        padding: 1rem;\r\n        i{\r\n            font-size: 3rem;\r\n            color: v.$gris60;\r\n        }\r\n    }\r\n    &__admininfo{\r\n        margin-top: 1.5rem;\r\n        padding: 1rem 2rem;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 2rem;\r\n    }\r\n    \r\n    &__infocompletado{\r\n        padding: 0 2rem;\r\n        display: flex;\r\n        justify-content: space-around;\r\n    }\r\n    &__texto{\r\n        .dailyearning{\r\n            color: v.$gris80;\r\n            font-weight: 600;\r\n            margin-bottom: 2rem;\r\n            @include m.texto_fluido(1.5rem, 3.4rem);\r\n        }\r\n    }\r\n        .rueda{\r\n            position: relative;\r\n                width: 120px;\r\n            @include m.xl_tablet{\r\n                width: 110px;\r\n            }\r\n            @include m.desktop{\r\n                width: 115px;\r\n            //height: 115px;\r\n            }\r\n            @include m.xl_desktop{\r\n                width: 140px;\r\n            //height: 140px;\r\n            }\r\n            .afuera{\r\n                width: 120px;\r\n                height: 120px;\r\n                @include m.xl_tablet{\r\n                    width: 110px;\r\n                    height: 110px;\r\n                }\r\n                @include m.desktop{\r\n                    width: 115px;\r\n                    height: 115px;\r\n                }\r\n                @include m.xl_desktop{\r\n                    width: 140px;\r\n                    height: 140px;\r\n                }\r\n                /*border: 1px solid #c0e3ee;*/\r\n                box-shadow: 6px 6px 10px -1px rgba(70, 70, 70, 0.15), -1px -1px 12px -3px rgba(207, 207, 207, 0.7);\r\n                border-radius: 50%;\r\n                display: flex;\r\n                justify-content: center;\r\n                align-items: center;\r\n                .adentro{\r\n                    width: 85px;\r\n                    height: 85px;\r\n                    @include m.xl_tablet{\r\n                        width: 75px;\r\n                        height: 75px;\r\n                    }\r\n                    @include m.desktop{\r\n                        width: 80px;\r\n                        height: 80px;\r\n                    }\r\n                    @include m.xl_desktop{\r\n                        width: 100px;\r\n                        height: 100px;\r\n                    }\r\n                    /*border: 1px solid #ad3434;*/\r\n                    box-shadow: inset 4px 4px 6px -1px rgba(70, 70, 70, 0.2);\r\n                    border-radius: 50%;\r\n                    display: flex;\r\n                    justify-content: center;\r\n                    align-items: center;\r\n                    .numero{\r\n                        color: v.$gris60;\r\n                        font-size: 1.6rem;\r\n                    }\r\n                }\r\n            }\r\n            circle{\r\n                fill: none;\r\n                stroke: url(#GradientColor1);\r\n                stroke-width: 14px;\r\n                stroke-dasharray: 440;\r\n                stroke-dashoffset: 440;\r\n                //animation: anim1 3s linear forwards;\r\n                transition: all 3s ease;\r\n            }\r\n             \r\n            .animacion{\r\n                //stroke-dashoffset: 88;\r\n            }\r\n            /*\r\n            @keyframes anim1{\r\n                100%{stroke-dashoffset: 88;}  //80% html\r\n            }*/\r\n        \r\n            svg{\r\n                position: absolute;\r\n                left: 0;\r\n                top: 0;\r\n            }\r\n            .name{\r\n                font-size: 1.8rem;\r\n                margin-top: 1rem;\r\n                color: v.$blanco;\r\n            }\r\n        }// fin rueda\r\n}","@use 'base/variables' as v;\n@use 'base/mixins' as m;\n\n.perfil{\n  --perfil-primary: #4f46e5;\n  --perfil-primary-dark: #4338ca;\n  --perfil-accent: #06b6d4;\n  --perfil-border: #dbe3ef;\n  --perfil-muted: #64748b;\n  --perfil-text: #14233b;\n  --perfil-soft: #f8fafc;\n\n  @include m.contenedor100;\n  color: var(--perfil-text);\n}\n\n.perfil-shell{\n  background:\n    linear-gradient(180deg, rgba(79,70,229,.06), rgba(255,255,255,0) 18rem),\n    #fff;\n  border: 1px solid var(--perfil-border);\n  border-radius: .8rem;\n  box-shadow: 0 12px 28px rgba(15, 23, 42, .06);\n  margin: 0 auto;\n  max-width: 128rem;\n  padding: 1.6rem;\n}\n\n.perfil-hero{\n  align-items: center;\n  background: linear-gradient(135deg, rgba(79,70,229,.09), rgba(6,182,212,.07));\n  border: 1px solid var(--perfil-border);\n  border-radius: .8rem;\n  display: flex;\n  gap: 1.4rem;\n  justify-content: space-between;\n  margin-bottom: 1.4rem;\n  padding: 1.6rem;\n}\n\n.perfil-eyebrow{\n  color: var(--perfil-primary);\n  font-size: 1.05rem;\n  font-weight: 800;\n  letter-spacing: 0;\n  margin: 0 0 .25rem;\n  text-transform: uppercase;\n}\n\n.perfil-hero__content{\n  min-width: 0;\n\n  h1{\n    color: var(--perfil-text);\n    font-size: 2.55rem;\n    font-weight: 800;\n    line-height: 1.12;\n    margin: 0;\n  }\n\n  p:not(.perfil-eyebrow){\n    color: var(--perfil-muted);\n    font-size: 1.22rem;\n    line-height: 1.35;\n    margin: .35rem 0 0;\n  }\n}\n\n.perfil-hero__identity{\n  align-items: center;\n  background: rgba(255,255,255,.86);\n  border: 1px solid rgba(219,227,239,.9);\n  border-radius: .8rem;\n  display: flex;\n  flex: 0 0 auto;\n  gap: 1rem;\n  min-width: 28rem;\n  padding: 1rem;\n\n  strong,\n  small{\n    display: block;\n    max-width: 22rem;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n  }\n\n  strong{\n    color: var(--perfil-text);\n    font-size: 1.32rem;\n    font-weight: 800;\n  }\n\n  small{\n    color: var(--perfil-muted);\n    font-size: 1.08rem;\n    margin-top: .1rem;\n  }\n}\n\n.perfil-avatar,\n.perfil-summary__avatar{\n  align-items: center;\n  background: linear-gradient(135deg, #5b52f0, var(--perfil-primary-dark));\n  border: 3px solid #fff;\n  border-radius: 50%;\n  box-shadow: 0 12px 24px rgba(79,70,229,.22);\n  color: #fff;\n  display: inline-flex;\n  flex: 0 0 auto;\n  font-weight: 900;\n  justify-content: center;\n}\n\n.perfil-avatar{\n  font-size: 1.8rem;\n  height: 5.4rem;\n  width: 5.4rem;\n}\n\n.perfil-grid{\n  align-items: flex-start;\n  display: grid;\n  gap: 1.4rem;\n  grid-template-columns: 32rem minmax(0, 1fr);\n}\n\n.perfil-summary,\n.perfil-card{\n  background: #fff;\n  border: 1px solid var(--perfil-border);\n  border-radius: .8rem;\n  box-shadow: 0 10px 22px rgba(15, 23, 42, .045);\n}\n\n.perfil-summary{\n  padding: 1.5rem;\n  position: sticky;\n  top: 1rem;\n  text-align: center;\n}\n\n.perfil-summary__avatar{\n  font-size: 2.6rem;\n  height: 8.6rem;\n  margin: 0 auto 1rem;\n  width: 8.6rem;\n}\n\n.perfil-summary{\n  h2{\n    color: var(--perfil-text);\n    font-size: 1.85rem;\n    font-weight: 800;\n    line-height: 1.15;\n    margin: 0;\n  }\n\n  > p{\n    color: var(--perfil-muted);\n    font-size: 1.12rem;\n    margin: .35rem 0 1.2rem;\n  }\n}\n\n.perfil-summary__list{\n  display: grid;\n  gap: .8rem;\n  text-align: left;\n\n  > div{\n    align-items: center;\n    background: var(--perfil-soft);\n    border: 1px solid var(--perfil-border);\n    border-radius: .75rem;\n    display: flex;\n    gap: .85rem;\n    min-width: 0;\n    padding: .95rem;\n  }\n\n  span{\n    align-items: center;\n    background: rgba(79,70,229,.10);\n    border-radius: .65rem;\n    color: var(--perfil-primary);\n    display: inline-flex;\n    flex: 0 0 3.8rem;\n    height: 3.8rem;\n    justify-content: center;\n    width: 3.8rem;\n  }\n\n  small,\n  strong{\n    display: block;\n    min-width: 0;\n  }\n\n  small{\n    color: var(--perfil-muted);\n    font-size: .98rem;\n    font-weight: 700;\n    text-transform: uppercase;\n  }\n\n  strong{\n    color: var(--perfil-text);\n    font-size: 1.12rem;\n    font-weight: 800;\n    overflow-wrap: anywhere;\n  }\n}\n\n.perfil-content,\n.perfil-form{\n  display: grid;\n  gap: 1.4rem;\n  min-width: 0;\n}\n\n.perfil-card{\n  overflow: hidden;\n  padding: 1.5rem;\n}\n\n.perfil-card--danger{\n  border-color: #fecdd3;\n}\n\n.perfil-card__header{\n  align-items: center;\n  border-bottom: 1px solid var(--perfil-border);\n  display: flex;\n  gap: 1rem;\n  margin-bottom: 1.35rem;\n  padding-bottom: 1rem;\n\n  h2{\n    color: var(--perfil-text);\n    font-size: 1.6rem;\n    font-weight: 800;\n    line-height: 1.15;\n    margin: 0;\n  }\n\n  p{\n    color: var(--perfil-muted);\n    font-size: 1.08rem;\n    line-height: 1.35;\n    margin: .18rem 0 0;\n  }\n}\n\n.perfil-card__icon{\n  align-items: center;\n  background: rgba(79,70,229,.10);\n  border-radius: .7rem;\n  color: var(--perfil-primary);\n  display: inline-flex;\n  flex: 0 0 4.4rem;\n  font-size: 1.85rem;\n  height: 4.4rem;\n  justify-content: center;\n  width: 4.4rem;\n}\n\n.perfil-card__icon--danger{\n  background: #fff1f2;\n  color: #e11d48;\n}\n\n.perfil-email{\n  align-items: center;\n  background: var(--perfil-soft);\n  border: 1px solid var(--perfil-border);\n  border-radius: .8rem;\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n  padding: 1.1rem;\n\n  small,\n  strong{\n    display: block;\n  }\n\n  small{\n    color: var(--perfil-muted);\n    font-size: 1rem;\n    font-weight: 800;\n    text-transform: uppercase;\n  }\n\n  strong{\n    color: var(--perfil-text);\n    font-size: 1.25rem;\n    font-weight: 800;\n    overflow-wrap: anywhere;\n  }\n}\n\n.perfil-form__grid{\n  display: grid;\n  gap: 1.15rem 1.25rem;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n.perfil-field{\n  display: grid;\n  gap: .55rem;\n  min-width: 0;\n\n  label{\n    color: #263852;\n    font-size: 1.16rem;\n    font-weight: 700;\n    line-height: 1.2;\n  }\n}\n\n.perfil-field--wide{\n  grid-column: 1 / -1;\n}\n\n.perfil-control{\n  align-items: center;\n  display: flex;\n  min-width: 0;\n\n  > span{\n    align-items: center;\n    background: #eef2ff;\n    border: 1px solid #cbd5e1;\n    border-radius: .65rem 0 0 .65rem;\n    color: var(--perfil-primary);\n    display: inline-flex;\n    flex: 0 0 4.6rem;\n    height: 4.6rem;\n    justify-content: center;\n    width: 4.6rem;\n  }\n\n  input{\n    background: #f8fafc;\n    border: 1px solid #cbd5e1;\n    border-left: 0;\n    border-radius: 0 .65rem .65rem 0;\n    color: #0f172a;\n    display: block;\n    font-size: 1.24rem;\n    height: 4.6rem;\n    min-width: 0;\n    outline: none;\n    padding: 0 1.1rem;\n    transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;\n    width: 100%;\n\n    &:focus{\n      background: #fff;\n      border-color: var(--perfil-primary);\n      box-shadow: 0 0 0 .3rem rgba(79,70,229,.12);\n    }\n\n    &::placeholder{\n      color: #94a3b8;\n    }\n  }\n}\n\n.perfil-help{\n  align-items: center;\n  background: #ecfeff;\n  border: 1px solid #bae6fd;\n  border-radius: .75rem;\n  color: #155e75;\n  display: flex;\n  gap: .85rem;\n  margin-top: 1.1rem;\n  padding: .95rem 1rem;\n\n  i{\n    color: var(--perfil-accent);\n  }\n\n  p{\n    font-size: 1.08rem;\n    font-weight: 600;\n    margin: 0;\n  }\n\n  a{\n    color: var(--perfil-primary);\n    font-weight: 800;\n  }\n}\n\n.perfil-actions{\n  display: flex;\n  justify-content: flex-end;\n}\n\n.perfil-button{\n  align-items: center;\n  border-radius: .65rem;\n  cursor: pointer;\n  display: inline-flex;\n  font-size: 1.2rem;\n  font-weight: 800;\n  gap: .65rem;\n  justify-content: center;\n  min-height: 4.4rem;\n  min-width: 14rem;\n  padding: 0 1.35rem;\n  transition: transform .2s ease, box-shadow .2s ease, background .2s ease, border-color .2s ease;\n}\n\ninput.perfil-button{\n  border: 0;\n}\n\n.perfil-button--primary{\n  background: linear-gradient(135deg, #5b52f0, var(--perfil-primary-dark));\n  border: 0;\n  box-shadow: 0 12px 24px rgba(79,70,229,.22);\n  color: #fff;\n\n  &:hover{\n    box-shadow: 0 14px 28px rgba(79,70,229,.28);\n    transform: translateY(-1px);\n  }\n}\n\n.perfil-button--secondary{\n  background: #fff;\n  border: 1px solid #67e8f9;\n  color: #0e7490;\n\n  &:hover{\n    background: #ecfeff;\n    border-color: var(--perfil-accent);\n  }\n}\n\n.perfil-button--ghost{\n  background: #fff;\n  border: 1px solid #cbd5e1;\n  color: #263852;\n\n  &:hover{\n    background: #f8fafc;\n  }\n}\n\n.perfil-danger{\n  align-items: center;\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n\n  > span{\n    align-items: center;\n    background: #fff1f2;\n    border-radius: 999px;\n    color: #be123c;\n    display: inline-flex;\n    font-size: 1.08rem;\n    font-weight: 800;\n    gap: .6rem;\n    min-height: 3.6rem;\n    padding: 0 1rem;\n  }\n}\n\n.perfil-danger__button{\