or: var(--reports-muted);\r\n    font-size: 1.02rem;\r\n    font-weight: 700;\r\n  }\r\n}\r\n\r\n.reportes-dashboard__charts{\r\n  display: grid;\r\n  gap: 1.4rem;\r\n  grid-template-columns: minmax(0, 2fr) minmax(30rem, 1fr);\r\n}\r\n\r\n.reportes-dashboard__chart,\r\n.reportes-dashboard__section{\r\n  background: #fff;\r\n  border: 1px solid var(--reports-border);\r\n  border-radius: .8rem;\r\n  box-shadow: 0 10px 22px rgba(15, 23, 42, .045);\r\n  padding: 1.4rem;\r\n}\r\n\r\n.reportes-dashboard__chart-header,\r\n.reportes-dashboard__section-header{\r\n  align-items: center;\r\n  border-bottom: 1px solid var(--reports-border);\r\n  display: flex;\r\n  gap: 1rem;\r\n  justify-content: space-between;\r\n  padding-bottom: 1rem;\r\n\r\n  h2{\r\n    color: var(--reports-text);\r\n    font-size: 1.65rem;\r\n    font-weight: 800;\r\n    line-height: 1.15;\r\n    margin: 0;\r\n  }\r\n\r\n  p{\r\n    color: var(--reports-muted);\r\n    font-size: 1.08rem;\r\n    line-height: 1.35;\r\n    margin: .2rem 0 0;\r\n  }\r\n}\r\n\r\n.reportes-dashboard__chart-header div > span{\r\n  color: var(--reports-primary);\r\n  display: block;\r\n  font-size: 1rem;\r\n  font-weight: 800;\r\n  margin-bottom: .2rem;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.reportes-dashboard__section-header{\r\n  justify-content: flex-start;\r\n\r\n  > span{\r\n    align-items: center;\r\n    background: #eef2ff;\r\n    border-radius: .7rem;\r\n    color: var(--reports-primary);\r\n    display: inline-flex;\r\n    flex: 0 0 4.2rem;\r\n    font-size: 1.8rem;\r\n    height: 4.2rem;\r\n    justify-content: center;\r\n    width: 4.2rem;\r\n  }\r\n}\r\n\r\n.reportes-dashboard__switch{\r\n  background: #f1f5f9;\r\n  border: 1px solid var(--reports-border);\r\n  border-radius: .75rem;\r\n  display: inline-flex;\r\n  gap: .35rem;\r\n  padding: .35rem;\r\n\r\n  button{\r\n    background: transparent;\r\n    border: 0;\r\n    border-radius: .58rem;\r\n    color: var(--reports-muted);\r\n    cursor: pointer;\r\n    