ar(--config-border);\n    border-radius: .8rem;\n    box-shadow: 0 8px 22px rgba(15, 23, 42, .06);\n    margin-bottom: 1.4rem;\n    overflow-x: auto;\n    scrollbar-color: rgba(79,70,229,.5) rgba(238,242,255,.85);\n    scrollbar-width: thin;\n    padding: .8rem;\n    position: sticky;\n    top: 0;\n    z-index: 20;\n\n    &::-webkit-scrollbar{\n      height: .8rem;\n    }\n\n    &::-webkit-scrollbar-track{\n      background: rgba(238,242,255,.85);\n      border-radius: 999px;\n      margin: 0 .4rem;\n    }\n\n    &::-webkit-scrollbar-thumb{\n      background: linear-gradient(90deg, rgba(79,70,229,.72), rgba(20,184,166,.72));\n      border: 2px solid rgba(238,242,255,.85);\n      border-radius: 999px;\n    }\n\n    &::-webkit-scrollbar-thumb:hover{\n      background: linear-gradient(90deg, rgba(79,70,229,.9), rgba(20,184,166,.9));\n    }\n  }\n\n  .configuracion-tabs__content{\n    display: flex;\n    gap: .8rem;\n    min-width: max-content;\n  }\n\n  .configuracion-tab{\n    display: block;\n    margin: 0;\n\n    input{\n      display: none;\n    }\n\n    span{\n      align-items: center;\n      background: #fff;\n      box-sizing: border-box;\n      border: 1px solid var(--config-border);\n      border-radius: .65rem;\n      color: #263852;\n      cursor: pointer;\n      display: flex;\n      font-size: 1.22rem;\n      font-weight: 700;\n      gap: .7rem;\n      height: 4.4rem;\n      justify-content: center;\n      line-height: 1;\n      min-height: 4.4rem;\n      padding: 0 1.25rem;\n      transition: background .2s ease, border-color .2s ease, box-shadow .2s ease, color .2s ease, transform .2s ease;\n      white-space: nowrap;\n\n      i{\n        align-items: center;\n        color: var(--config-primary);\n        display: inline-flex;\n        height: 1.5rem;\n        justify-content: center;\n        font-size: 1.3rem;\n        min-width: 1.5rem;\n        text-align: center;\n      }\n\n      &:hover{\n        border-color: rgba(79,70,229,.38);\n        box-shadow: 0 8px 18px rgba(79,70,229,.10);\n        transform: translateY(-1px);\n      }\n    }\n\n    input:checked + span{\n      background: linear-gradient(135deg, #5b52f0, var(--config-primary-dark));\n      border-color: var(--config-primary-dark);\n      box-shadow: 0 12px 24px rgba(79,70,229,.22);\n      color: #fff;\n\n      i{\n        color: #fff;\n      }\n    }\n  }\n\n\n  .tabs-content label.configuracion-tab > span{\n    align-items: center;\n    box-sizing: border-box;\n    display: flex;\n    gap: .85rem;\n    height: 4.4rem;\n    justify-content: center;\n    line-height: 1;\n    padding: 0 1.25rem;\n  }\n\n  .tabs-content label.configuracion-tab > span i{\n    align-items: center;\n    display: inline-flex;\n    height: 1.6rem;\n    justify-content: center;\n    line-height: 1;\n    margin: 0;\n    min-width: 1.6rem;\n  }\n  .configuracion-content{\n    background: rgba(255,255,255,.82);\n    border: 1px solid var(--config-border);\n    border-radius: .8rem;\n    min-height: 52rem;\n    padding: 1.4rem;\n  }\n\n  .paginas{\n    min-width: 0;\n  }\n\n  .config-system{\n    align-items: flex-start;\n    display: grid;\n    gap: 1.4rem;\n    grid-template-columns: 23rem minmax(0, 1fr);\n  }\n\n  .config-system-nav{\n    background: var(--config-soft);\n    border: 1px solid var(--config-border);\n    border-radius: .8rem;\n    padding: 1.2rem;\n    position: sticky;\n    top: 8.4rem;\n    z-index: 10;\n  }\n\n  .config-system-nav__heading{\n    align-items: center;\n    border-bottom: 1px solid var(--config-border);\n    display: flex;\n    gap: .9rem;\n    margin-bottom: 1rem;\n    padding-bottom: 1rem;\n    text-align: left;\n\n    .material-symbols-outlined{\n      align-items: center;\n      background: rgba(79,70,229,.10);\n      border-radius: .65rem;\n      color: var(--config-primary);\n      display: inline-flex;\n      font-size: 2.2rem;\n      height: 3.8rem;\n      justify-content: center;\n      width: 3.8rem;\n    }\n\n    strong{\n      display: block;\n      font-size: 1.28rem;\n      line-height: 1.2;\n    }\n\n    small{\n      color: var(--config-muted);\n      display: block;\n      font-size: 1rem;\n      margin-top: .2rem;\n    }\n  }\n\n  .config-system-nav__grid{\n    display: grid;\n    gap: .75rem;\n    scrollbar-color: rgba(79,70,229,.5) rgba(238,242,255,.85);\n    scrollbar-width: thin;\n\n    &::-webkit-scrollbar{\n      height: .8rem;\n      width: .8rem;\n    }\n\n    &::-webkit-scrollbar-track{\n      background: rgba(238,242,255,.85);\n      border-radius: 999px;\n      margin: 0 .4rem;\n    }\n\n    &::-webkit-scrollbar-thumb{\n      background: linear-gradient(90deg, rgba(79,70,229,.72), rgba(20,184,166,.72));\n      border: 2px solid rgba(238,242,255,.85);\n      border-radius: 999px;\n    }\n\n    &::-webkit-scrollbar-thumb:hover{\n      background: linear-gradient(90deg, rgba(79,70,229,.9), rgba(20,184,166,.9));\n    }\n  }\n\n  .config-system-tab{\n    align-items: center;\n    background: #fff;\n    border: 1px solid var(--config-border);\n    border-radius: .65rem;\n    color: #24364f;\n    cursor: pointer;\n    display: flex;\n    font-size: 1.16rem;\n    font-weight: 700;\n    gap: .8rem;\n    min-height: 3.9rem;\n    padding: 0 1rem;\n    text-align: left;\n    transition: background .2s ease, border-color .2s ease, box-shadow .2s ease, color .2s ease, transform .2s ease;\n    width: 100%;\n\n    i{\n      color: var(--config-primary);\n      font-size: 1.22rem;\n      min-width: 1.6rem;\n      text-align: center;\n    }\n\n    &:hover{\n      border-color: rgba(79,70,229,.35);\n      box-shadow: 0 8px 18px rgba(15,23,42,.07);\n      transform: translateY(-1px);\n    }\n  }\n\n  .accordion_inv{\n    #btn1:checked ~ .btnsetup .btn1,\n    #btn2:checked ~ .btnsetup .btn2,\n    #btn3:checked ~ .btnsetup .btn3,\n    #btn4:checked ~ .btnsetup .btn4,\n    #btn5:checked ~ .btnsetup .btn5,\n    #btn6:checked ~ .btnsetup .btn6,\n    #btn7:checked ~ .btnsetup .btn7,\n    #btn8:checked ~ .btnsetup .btn8,\n    #btn9:checked ~ .btnsetup .btn9,\n    #btn10:checked ~ .btnsetup .btn10{\n      background: linear-gradient(135deg, #5b52f0, var(--config-primary-dark));\n      border-color: var(--config-primary-dark);\n      box-shadow: 0 10px 20px rgba(79,70,229,.20);\n      color: #fff;\n      transform: translateY(-1px);\n\n      i{\n        color: #fff;\n      }\n    }\n  }\n\n  .config-system.accordion_inv{\n    .config-system-content > .accordion_tab_content{\n      display: none !important;\n    }\n\n    #btn1:checked ~ .config-system-content > .contenido1,\n    #btn2:checked ~ .config-system-content > .contenido2,\n    #btn3:checked ~ .config-system-content > .contenido3,\n    #btn4:checked ~ .config-system-content > .contenido4,\n    #btn5:checked ~ .config-system-content > .contenido5,\n    #btn6:checked ~ .config-system-content > .contenido6,\n    #btn7:checked ~ .config-system-content > .contenido7,\n    #btn8:checked ~ .config-system-content > .contenido8,\n    #btn9:checked ~ .config-system-content > .contenido9,\n    #btn10:checked ~ .config-system-content > .contenido10{\n      display: block !important;\n    }\n\n    #btn9:checked ~ .config-system-content > .contenido9{\n      display: grid !important;\n    }\n  }\n\n  .config-system-content{\n    background: #fff;\n    border: 1px solid var(--config-border);\n    border-radius: .8rem;\n    min-height: 48rem;\n    min-width: 0;\n    overflow: auto;\n    padding: 1.4rem;\n  }\n\n  .config-param-search{\n    align-items: center;\n    background: #f8fafc;\n    border: 1px solid var(--config-border);\n    border-radius: .75rem;\n    display: grid;\n    gap: .75rem;\n    grid-template-columns: auto minmax(0, 1fr) auto auto;\n    margin-bottom: 1.2rem;\n    padding: .75rem 1rem;\n\n    > .material-symbols-outlined{\n      color: var(--config-primary);\n      font-size: 2rem;\n      line-height: 1;\n    }\n\n    input{\n      background: transparent;\n      border: 0;\n      color: var(--config-text);\n      font-size: 1.2rem;\n      min-height: 2.8rem;\n      outline: none;\n      width: 100%;\n\n      &::placeholder{\n        color: #94a3b8;\n      }\n    }\n\n    button{\n      align-items: center;\n      background: #fff;\n      border: 1px solid #cbd5e1;\n      border-radius: .6rem;\n      color: #64748b;\n      cursor: pointer;\n      display: none;\n      height: 2.8rem;\n      justify-content: center;\n      width: 2.8rem;\n\n      .material-symbols-outlined{\n        font-size: 1.8rem;\n      }\n    }\n\n    small{\n      color: var(--config-muted);\n      font-size: 1rem;\n      white-space: nowrap;\n    }\n\n    &.has-query button{\n      display: inline-flex;\n    }\n  }\n\n  .config-param-hidden{\n    display: none !important;\n  }\n\n  .config-system.param-search-active{\n    .config-system-content .accordion_tab_content.config-param-panel-match{\n      display: block;\n    }\n  }\n\n  .config-param-match{\n    animation: configParamPulse 1.35s ease-out 1;\n    background: rgba(79,70,229,.035);\n    border: 1px solid rgba(79,70,229,.18);\n    border-radius: .9rem;\n    box-shadow: 0 .8rem 1.8rem rgba(15,23,42,.06);\n    padding: .8rem;\n  }\n\n  @keyframes configParamPulse{\n    0%{\n      border-color: rgba(79,70,229,.42);\n      box-shadow: 0 0 0 .35rem rgba(79,70,229,.16), 0 .8rem 1.8rem rgba(15,23,42,.06);\n    }\n    100%{\n      border-color: rgba(79,70,229,.18);\n      box-shadow: 0 .8rem 1.8rem rgba(15,23,42,.06);\n    }\n  }\n\n  .config-system-content{\n    h2{\n      font-size: 2rem;\n      line-height: 1.15;\n    }\n\n    h3{\n      font-size: 1.65rem;\n      line-height: 1.18;\n    }\n\n    h4,\n    h5{\n      font-size: 1.35rem;\n      line-height: 1.18;\n    }\n\n    p,\n    small{\n      font-size: 1.05rem;\n      line-height: 1.35;\n    }\n\n    label,\n    .formulario__label{\n      font-size: 1.16rem !important;\n      line-height: 1.2 !important;\n    }\n\n    input,\n    select,\n    textarea,\n    .formulario__input{\n      font-size: 1.24rem !important;\n    }\n\n    button,\n    .btn-md{\n      font-size: 1.2rem !important;\n    }\n  }\n\n  .config-system-content .accordion_tab_content{\n    min-width: 0;\n  }\n\n  .config-system-content .accordion_tab_content{\n    background: linear-gradient(180deg, #fff 0%, #fbfdff 100%) !important;\n    border: 1px solid var(--config-border);\n    border-radius: .9rem;\n    box-shadow: 0 12px 28px rgba(15,23,42,.06);\n    padding: 1.35rem !important;\n\n    > .flex:first-child{\n      align-items: center;\n      background: #f8fafc;\n      border: 1px solid #e2e8f0;\n      border-radius: .8rem;\n      margin-bottom: 1.1rem;\n      padding: .9rem 1rem;\n\n      p{\n        align-items: center;\n        display: inline-flex;\n        gap: .55rem;\n        margin: 0;\n\n        &::before{\n          background: #eef2ff;\n          border-radius: .55rem;\n          color: var(--config-primary);\n          content: \"\\f013\";\n          display: inline-flex;\n          font-family: \"Font Awesome 6 Free\";\n          font-size: 1rem;\n          font-weight: 900;\n          height: 2.4rem;\n          justify-content: center;\n          align-items: center;\n          width: 2.4rem;\n        }\n      }\n    }\n\n    > .grid{\n      align-items: stretch;\n      gap: 1rem !important;\n\n      > div{\n        background: #f8fafc;\n        border: 1px solid #dbe3ef;\n        border-radius: .9rem;\n        min-width: 0;\n        padding: 1rem;\n        transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;\n\n        &:hover{\n          border-color: rgba(79,70,229,.26);\n          box-shadow: 0 .8rem 1.8rem rgba(15,23,42,.055);\n        }\n      }\n    }\n\n    label:not(.config-system-tab){\n      color: var(--config-text) !important;\n      font-size: 1.12rem !important;\n      font-weight: 800 !important;\n      line-height: 1.25 !important;\n      margin: 0 0 .45rem !important;\n    }\n\n    p,\n    small,\n    span.block{\n      color: var(--config-muted) !important;\n      font-size: 1rem !important;\n      line-height: 1.35 !important;\n    }\n\n    input[type=\"text\"],\n    input[type=\"number\"],\n    input[type=\"password\"],\n    select,\n    textarea{\n      background-color: #fff !important;\n      border: 1px solid #cbd5e1 !important;\n      border-radius: .7rem !important;\n      color: var(--config-text) !important;\n      font-size: 1.14rem !important;\n      min-height: 3.9rem;\n      padding: .75rem .9rem !important;\n      transition: border-color .2s ease, box-shadow .2s ease, background .2s ease;\n\n      &:focus{\n        border-color: rgba(79,70,229,.7) !important;\n        box-shadow: 0 0 0 .25rem rgba(79,70,229,.12) !important;\n        outline: none;\n      }\n\n      &::placeholder{\n        color: #94a3b8;\n      }\n    }\n\n    select{\n      cursor: pointer;\n      height: 3.9rem !important;\n    }\n\n    textarea{\n      min-height: 9rem;\n      resize: vertical;\n    }\n\n    label:has(input[type=\"radio\"]){\n      background: #fff !important;\n      border: 1px solid #dbe3ef !important;\n      border-radius: .75rem !important;\n      color: var(--config-text) !important;\n      height: auto !important;\n      margin: 0 !important;\n      min-height: 3.7rem;\n      padding: .75rem .9rem !important;\n\n      span{\n        color: var(--config-text) !important;\n        font-size: 1.08rem !important;\n        font-weight: 800 !important;\n      }\n\n      input[type=\"radio\"] + div{\n        background: #fff;\n        border-color: #cbd5e1 !important;\n        flex: 0 0 auto;\n        height: 1.25rem !important;\n        width: 1.25rem !important;\n      }\n    }\n\n    label:has(input[type=\"radio\"]:checked){\n      background: #eef2ff !important;\n      border-color: rgba(79,70,229,.34) !important;\n      box-shadow: inset 0 0 0 1px rgba(79,70,229,.08);\n\n      input[type=\"radio\"] + div{\n        background: var(--config-primary) !important;\n        border-color: var(--config-primary) !important;\n        box-shadow: inset 0 0 0 .28rem #fff;\n      }\n    }\n\n    .config-param-saved{\n      animation: configParamSaved 1.8s ease-out 1;\n      background: #ecfdf5 !important;\n      border-color: rgba(16,185,129,.62) !important;\n      box-shadow: 0 0 0 .22rem rgba(16,185,129,.14), 0 .8rem 1.8rem rgba(16,185,129,.10) !important;\n\n      input[type=\"text\"],\n      input[type=\"number\"],\n      input[type=\"password\"],\n      select,\n      textarea{\n        border-color: rgba(16,185,129,.72) !important;\n        box-shadow: 0 0 0 .2rem rgba(16,185,129,.12) !important;\n      }\n\n      label:has(input[type=\"radio\"]:checked){\n        background: #d1fae5 !important;\n        border-color: rgba(16,185,129,.70) !important;\n\n        input[type=\"radio\"] + div{\n          background: #10b981 !important;\n          border-color: #10b981 !important;\n        }\n      }\n    }\n  }\n\n  @keyframes configParamSaved{\n    0%{\n      transform: translateY(-1px);\n    }\n    70%{\n      background: #ecfdf5;\n      border-color: rgba(16,185,129,.62);\n      box-shadow: 0 0 0 .22rem rgba(16,185,129,.14), 0 .8rem 1.8rem rgba(16,185,129,.10);\n    }\n    100%{\n      transform: translateY(0);\n    }\n  }\n\n  .config-whatsapp{\n    display: grid;\n    gap: 1.2rem;\n  }\n\n  .config-whatsapp__hero,\n  .config-whatsapp__section{\n    background: #fff;\n    border: 1px solid var(--config-border);\n    border-radius: .9rem;\n    box-shadow: 0 12px 28px rgba(15,23,42,.055);\n  }\n\n  .config-whatsapp__hero{\n    background: linear-gradient(135deg, rgba(79,70,229,.08), rgba(6,182,212,.055));\n    padding: 1.1rem 1.25rem;\n  }\n\n  .config-whatsapp__title,\n  .config-whatsapp__section-header,\n  .config-whatsapp-form__header,\n  .config-whatsapp-event__copy{\n    align-items: center;\n    display: flex;\n    gap: 1rem;\n  }\n\n  .config-whatsapp__title > span,\n  .config-whatsapp-form__header > span,\n  .config-whatsapp-event