  display: flex;\n  flex-wrap: wrap;\n  font-size: 1.45rem;\n  gap: .8rem;\n  margin-bottom: 1.6rem;\n  padding-bottom: 1.2rem;\n}\n\n.ordenresumen-emisor .btn-xs {\n  min-height: 3.2rem;\n  padding: .55rem 1rem;\n}\n\n.ordenresumen-metrics {\n  display: grid;\n  gap: 1rem;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  margin-bottom: 1.8rem;\n}\n\n.ordenresumen-metric-card {\n  background: #fff;\n  border: 1px solid #dbe4f0;\n  border-radius: .8rem;\n  box-shadow: 0 8px 18px rgba(15, 23, 42, .04);\n  min-height: 9.2rem;\n  padding: 1.35rem;\n  text-align: left;\n}\n\n.ordenresumen-metric-card > p:last-child,\n.ordenresumen-metric-card button {\n  font-size: 1.5rem;\n  font-weight: 600;\n}\n\n.ordenresumen-metric-label {\n  align-items: center;\n  color: #526172;\n  display: flex;\n  font-size: 1.25rem;\n  font-weight: 700;\n  gap: .6rem;\n  margin: 0 0 .8rem;\n  text-transform: uppercase;\n}\n\n.ordenresumen-metric-label .material-symbols-outlined {\n  color: #4d46e5;\n  font-size: 2.2rem;\n}\n\n.ordenresumen-state {\n  color: #0f766e;\n  font-size: 1.55rem;\n  font-weight: 800;\n  margin: 0 0 .3rem;\n}\n\n.ordenresumen-main-grid {\n  display: grid;\n  gap: 1.6rem;\n  grid-template-columns: minmax(0, 1fr) 32rem;\n}\n\n.ordenresumen-products-card,\n.ordenresumen-info-card,\n.ordenresumen-bottom {\n  background: #fff;\n  border: 1px solid #dbe4f0;\n  border-radius: .8rem;\n  box-shadow: 0 8px 18px rgba(15, 23, 42, .04);\n}\n\n.ordenresumen-products-card {\n  min-height: 42rem;\n  overflow-x: auto;\n  padding: 1.3rem;\n}\n\n.ordenresumen-card-head {\n  align-items: center;\n  display: flex;\n  gap: 1rem;\n  justify-content: space-between;\n  margin-bottom: 1rem;\n}\n\n.ordenresumen-card-title,\n.ordenresumen-info-title {\n  align-items: center;\n  color: #14233a;\n  display: flex;\n  font-size: 1.8rem;\n  font-weight: 800;\n  gap: .7rem;\n  margin: 0;\n}\n\n.ordenresumen-card-title .material-symbols-outlined,\n.ordenresumen-info-title .material-symbols-outlined {\n  color: #4d46e5;\n}\n\n.ordenresumen-count-pill {\n  background: #eef2ff;\n  border-radius: 999px;\n  color: #4338ca;\n  font-size: 1.2rem;\n  font-weight: 700;\n  padding: .55rem .9rem;\n  white-space: nowrap;\n}\n\n.ordenresumen-table {\n  border-collapse: separate;\n  border-spacing: 0;\n  color: #1e2d42;\n  min-width: 76rem;\n  width: 100%;\n}\n\n.ordenresumen-table thead th {\n  background: #f6f8fb;\n  border-bottom: 1px solid #d5deea;\n  border-top: 1px solid #d5deea;\n  color: #26364d;\n  font-size: 1.25rem;\n  font-weight: 800;\n  padding: 1rem;\n  text-align: left;\n}\n\n.ordenresumen-table thead th:first-child {\n  border-left: 1px solid #d5deea;\n  border-radius: .55rem 0 0 .55rem;\n}\n\n.ordenresumen-table thead th:last-child {\n  border-right: 1px solid #d5deea;\n  border-radius: 0 .55rem .55rem 0;\n}\n\n.ordenresumen-table tbody td,\n.ordenresumen-table tfoot td,\n.ordenresumen-table tfoot th {\n  border-bottom: 1px solid #e2e8f0;\n  font-size: 1.35rem;\n  padding: 1.05rem;\n  vertical-align: middle;\n}\n\n.ordenresumen-table tfoot th,\n.ordenresumen-table tfoot td {\n  background: #f8fafc;\n  color: #111827;\n  font-weight: 800;\n}\n\n.ordenresumen-product-cell {\n  color: #14233a;\n  font-weight: 700;\n}\n\n.ordenresumen-product-info {\n  align-items: center;\n  display: flex;\n  gap: 1rem;\n  min-width: 28rem;\n}\n\n.ordenresumen-product-img {\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: .55rem;\n  height: 5.8rem;\n  object-fit: contain;\n  padding: .25rem;\n  width: 5.8rem;\n}\n\n.ordenresumen-side {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.ordenresumen-info-card {\n  padding: 1.25rem;\n}\n\n.ordenresumen-info-title {\n  font-size: 1.55rem;\n  margin-bottom: 1rem;\n}\n\n.ordenresumen-info-line {\n  align-items: center;\n  color: #475569;\n  display: flex;\n  font-size: 1.35rem;\n  gap: .55rem;\n  line-height: 1.35;\n  margin: .3rem 0;\n}\n\n.ordenresumen-bottom {\n  margin-top: 1.6rem;\n  padding: 1.4rem;\n}\n\n.ordenresumen-bottom-grid {\n  display: grid;\n  gap: 1.4rem;\n  grid-template-columns: minmax(0, 2fr) minmax(28rem, 1fr);\n}\n\n.ordenresumen-observations,\n.ordenresumen-payment-summary {\n  background: #f8fafc;\n  border: 1px solid #dbe4f0;\n  border-radius: .8rem;\n  padding: 1.35rem;\n}\n\n.ordenresumen-payment-summary p {\n  font-size: 1.35rem !important;\n}\n\n.ordenresumen-payment-summary #total {\n  font-size: 3.6rem !important;\n  white-space: nowrap;\n}\n\n#miDialogoEliminarOrden.orden-delete-dialog[open] {\n  display: flex;\n  flex-direction: column;\n  max-height: calc(100dvh - 2.4rem);\n  overflow: hidden;\n}\n\n#miDialogoEliminarOrden .orden-delete-dialog__header {\n  flex: 0 0 auto;\n}\n\n#miDialogoEliminarOrden .orden-delete-dialog__body {\n  flex: 1 1 auto;\n  min-height: 0;\n  padding-bottom: 0;\n}\n\n#miDialogoEliminarOrden .orden-delete-dialog__products {\n  max-height: clamp(16rem, 26dvh, 24rem);\n  overflow: auto;\n}\n\n#miDialogoEliminarOrden .orden-delete-dialog__products table {\n  min-width: 46rem;\n}\n\n#miDialogoEliminarOrden .orden-delete-dialog__footer {\n  box-shadow: 0 -12px 24px rgba(15, 23, 42, .08);\n  z-index: 2;\n}\n\n@media (max-width: 1100px) {\n  .ordenresumen-metrics,\n  .ordenresumen-main-grid,\n  .ordenresumen-bottom-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .ordenresumen-side {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 768px) {\n  .ordenresumen-page {\n    padding: 1rem;\n  }\n\n  .ordenresumen-actions {\n    display: grid;\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .ordenresumen-actions .btn-command {\n    max-width: none;\n    min-width: 0;\n    width: 100%;\n  }\n\n  .ordenresumen-metrics,\n  .ordenresumen-side {\n    grid-template-columns: 1fr;\n  }\n\n  .ordenresumen-card-head {\n    align-items: flex-start;\n    flex-direction: column;\n  }\n\n  .ordenresumen-products-card,\n  .ordenresumen-bottom {\n    padding: 1rem;\n  }\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.creditos{\r\n  --creditos-primary: #4f46e5;\r\n  --creditos-primary-dark: #4338ca;\r\n  --creditos-accent: #06b6d4;\r\n  --creditos-border: #dbe3ef;\r\n  --creditos-muted: #64748b;\r\n  --creditos-text: #14233b;\r\n\r\n  @include m.contenedor100;\r\n  color: var(--creditos-text);\r\n  padding-bottom: 3rem;\r\n}\r\n\r\n.creditos-shell{\r\n  background:\r\n    linear-gradient(180deg, rgba(79,70,229,.06), rgba(255,255,255,0) 18rem),\r\n    #fff;\r\n  border: 1px solid var(--creditos-border);\r\n  border-radius: .8rem;\r\n  box-shadow: 0 12px 28px rgba(15, 23, 42, .06);\r\n  display: grid;\r\n  gap: 1.4rem;\r\n  margin: 0 auto;\r\n  max-width: 150rem;\r\n  padding: 1.6rem;\r\n}\r\n\r\n.creditos-hero{\r\n  align-items: center;\r\n  background: linear-gradient(135deg, rgba(79,70,229,.09), rgba(6,182,212,.08));\r\n  border: 1px solid var(--creditos-border);\r\n  border-radius: .8rem;\r\n  display: flex;\r\n  gap: 1.3rem;\r\n  justify-content: space-between;\r\n  padding: 1.7rem;\r\n}\r\n\r\n.creditos-eyebrow{\r\n  color: var(--creditos-primary);\r\n  font-size: 1.05rem;\r\n  font-weight: 800;\r\n  letter-spacing: 0;\r\n  margin: 0 0 .25rem;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.creditos-hero__content{\r\n  min-width: 0;\r\n\r\n  h1{\r\n    color: var(--creditos-text);\r\n    font-size: 2.65rem;\r\n    font-weight: 800;\r\n    line-height: 1.1;\r\n    margin: 0;\r\n  }\r\n\r\n  p:not(.creditos-eyebrow){\r\n    color: var(--creditos-muted);\r\n    font-size: 1.18rem;\r\n    line-height: 1.35;\r\n    margin: .35rem 0 0;\r\n  }\r\n}\r\n\r\n.creditos-hero__metrics{\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: .9rem;\r\n  justify-content: flex-end;\r\n}\r\n\r\n.creditos-stat{\r\n  align-items: center;\r\n  background: rgba(255,255,255,.9);\r\n  border: 1px solid rgba(219,227,239,.95);\r\n  border-radius: .8rem;\r\n  display: flex;\r\n  gap: .9rem;\r\n  min-width: 18rem;\r\n  padding: .95rem;\r\n\r\n  > span{\r\n    align-items: center;\r\n    background: linear-gradient(135deg, #5b52f0, var(--creditos-primary-dark));\r\n    border-radius: .75rem;\r\n    color: #fff;\r\n    display: inline-flex;\r\n    flex: 0 0 4.6rem;\r\n    font-size: 1.9rem;\r\n    height: 4.6rem;\r\n    justify-content: center;\r\n    width: 4.6rem;\r\n  }\r\n\r\n  strong,\r\n  small{\r\n    display: block;\r\n  }\r\n\r\n  strong{\r\n    color: var(--creditos-text);\r\n    font-size: 1.65rem;\r\n    font-weight: 900;\r\n    line-height: 1;\r\n    white-space: nowrap;\r\n  }\r\n\r\n  small{\r\n    color: var(--creditos-muted);\r\n    font-size: 1.02rem;\r\n    font-weight: 700;\r\n    margin-top: .22rem;\r\n  }\r\n}\r\n\r\n.creditos-stat--accent > span{\r\n  background: linear-gradient(135deg, #08c6bd, #0891b2);\r\n}\r\n\r\n.creditos-actions{\r\n  align-items: center;\r\n  background: #fff;\r\n  border: 1px solid var(--creditos-border);\r\n  border-radius: .8rem;\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: .8rem;\r\n  padding: 1rem;\r\n}\r\n\r\n.creditos-button{\r\n  align-items: center;\r\n  border-radius: .65rem;\r\n  display: inline-flex;\r\n  font-size: 1.15rem;\r\n  font-weight: 800;\r\n  gap: .6rem;\r\n  justify-content: center;\r\n  min-height: 4.4rem;\r\n  min-width: 15rem;\r\n  padding: 0 1.25rem;\r\n  text-align: center;\r\n  text-decoration: none;\r\n  transition: transform .2s ease, box-shadow .2s ease, background .2s ease, border-color .2s ease;\r\n\r\n  span{\r\n    font-size: 1.55rem;\r\n  }\r\n}\r\n\r\n.creditos-button--primary{\r\n  background: linear-gradient(135deg, #5b52f0, var(--creditos-primary-dark));\r\n  box-shadow: 0 12px 24px rgba(79,70,229,.22);\r\n  color: #fff;\r\n\r\n  &:hover{\r\n    box-shadow: 0 14px 28px rgba(79,70,229,.28);\r\n    color: #fff;\r\n    transform: translateY(-1px);\r\n  }\r\n}\r\n\r\n.creditos-button--secondary{\r\n  background: #ecfeff;\r\n  border: 1px solid #67e8f9;\r\n  color: #0e7490;\r\n\r\n  &:hover