-weight: 500;\n    line-height: 1.2;\n    margin-top: 0.6rem;\n  }\n  @keyframes carritoFeedbackPulse {\n    0% {\n      transform: scale(1);\n    }\n    45% {\n      transform: scale(1.08);\n    }\n    100% {\n      transform: scale(1);\n    }\n  }\n}\n/*\n// 1. Unificamos la estructura repetida de la tabla para pantallas < 1573px\n@mixin card-table-layout {\n  display: block !important;\n  width: 100% !important;\n\n  tbody {\n    display: block !important;\n    width: 100% !important;\n  }\n\n  thead {\n    display: none !important;\n  }\n\n  .productselect {\n    background-color: #ffffff;\n    border: .1rem solid #e2e8f0 !important;\n    border-radius: .9rem;\n    display: grid !important;\n  }\n\n  td {\n    display: flex !important;\n    align-items: center;\n    border: 0 !important;\n    padding: 0 !important;\n    width: auto !important;\n    min-width: 0;\n\n    &::before {\n      color: #64748b;\n      font-weight: 800;\n      letter-spacing: 0;\n      text-transform: uppercase;\n    }\n\n    &:nth-child(1) { grid-column: 1 / -1; }\n\n    &:nth-child(2) {\n      grid-column: 1;\n      justify-content: flex-start;\n      &::before { content: \"Cant.\"; }\n\n      > div {\n        min-width: 0 !important;\n      }\n    }\n\n    &:nth-child(3) {\n      grid-column: 2;\n      justify-content: center;\n      &::before { content: \"Und\"; }\n    }\n\n    &:nth-child(4) {\n      grid-column: 3;\n      justify-content: flex-end;\n      &::before { content: \"Total\"; }\n    }\n\n    &:nth-child(5) {\n      grid-column: 4;\n      justify-content: flex-end;\n    }\n  }\n}\n\n// 2. Estilos Base\n#contenedorDesktop,\n#contenidocarrito,\n#tablaventa {\n  min-width: 0;\n}\n\n#tablaventa {\n  table-layout: fixed;\n\n  th, td {\n    min-width: 0;\n  }\n\n  .nombreproducto {\n    overflow-wrap: anywhere;\n    word-break: normal;\n  }\n\n  // ---------------------------------------------\n  // Pantallas Grandes (Desktop > 1573px)\n  // ---------------------------------------------\n  @media (min-width: 1573px) {\n    th, td {\n      padding-left: .45rem !important;\n      padding-right: .45rem !important;\n      font-size: 1.15rem !important;\n\n      // Anchos por columna\n      &:nth-child(1) { width: 31%; }\n      &:nth-child(2) { width: 24%; }\n      &:nth-child(3) { width: 14%; }\n      &:nth-child(4) { width: 23%; }\n      &:nth-child(5) { width: 8%; }\n    }\n\n    th {\n      white-space: nowrap;\n    }\n\n    td:nth-child(2) {\n      > div {\n        gap: .45rem !important;\n        justify-content: center !important;\n        min-width: 0 !important;\n        width: 100% !important;\n      }\n      button {\n        height: 2.2rem !important;\n        width: 2.2rem !important;\n      }\n    }\n\n    td:nth-child(3),\n    td:nth-child(4) {\n      font-size: 1.08rem !important;\n      white-space: nowrap;\n    }\n\n    .nombreproducto {\n      font-size: 1.2rem !important;\n      line-height: 1.22 !important;\n      max-width: none !important;\n    }\n\n    .inputcantidad {\n      font-size: 1.12rem !important;\n      height: 2.8rem !important;\n      max-width: 6.6rem !important;\n      min-width: 5.8rem !important;\n      padding-left: .35rem !important;\n      padding-right: .35rem !important;\n      width: 6.4rem !important;\n    }\n\n    .menos, .mas {\n      font-size: 1.3rem !important;\n      height: 1.8rem !important;\n      width: 1.8rem !important;\n    }\n\n    .eliminarProducto {\n      height: 2.8rem !important;\n      width: 2.8rem !important;\n    }\n  }\n\n  // ---------------------------------------------\n  // Modos Card (Pantallas < 1573px)\n  // ---------------------------------------------\n  @media (max-width: 1572px) {\n    @include card-table-layout;\n  }\n\n  // Ajustes específicos entre 992px y 1572px\n  @media (min-width: 992px) and (max-width: 1572px) {\n    .productselect {\n      gap: .45rem .62rem;\n      grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\n      margin: .55rem;\n      padding: .65rem !important;\n    }\n\n    td {\n      font-size: 1.12rem !important;\n      gap: .28rem;\n\n      &::before { font-size: .9rem; }\n    }\n\n    .nombreproducto {\n      font-size: 1.22rem !important;\n      line-height: 1.18 !important;\n      margin-bottom: 0 !important;\n    }\n\n    td:nth-child(2) {\n      > div { gap: .34rem !important; }\n      button { height: 2.1rem !important; width: 2.1rem !important; }\n    }\n  }\n\n  // Ajustes específicos < 991px\n  @media (max-width: 991px) {\n    .productselect {\n      gap: .55rem .58rem;\n      grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\n      margin: .65rem;\n      padding: .75rem .65rem !important;\n    }\n\n    td {\n      font-size: 1.06rem !important;\n      gap: .26rem;\n\n      &::before { font-size: .9rem; }\n    }\n\n    .nombreproducto {\n      font-size: 1.22rem !important;\n      line-height: 1.2 !important;\n      margin-bottom: 0 !important;\n      max-width: none !important;\n    }\n\n    td:nth-child(2) {\n      > div { gap: .32rem !important; }\n      button { height: 2.1rem !important; width: 2.1rem !important; }\n    }\n  }\n\n  // Ajustes específicos < 460px\n  @media (max-width: 460px) {\n    .productselect {\n      gap: .5rem .42rem;\n      grid-template-columns: minmax(11.6rem, 1fr) minmax(6.1rem, auto) minmax(7.1rem, auto) 2.8rem;\n      padding-left: .55rem !important;\n      padding-right: .55rem !important;\n    }\n\n    td {\n      font-size: .96rem !important;\n      gap: .2rem;\n\n      &::before { font-size: .76rem; }\n    }\n\n    td:nth-child(2) {\n      > div { gap: .24rem !important; }\n      button { height: 2rem !important; width: 2rem !important; }\n    }\n\n    td:nth-child(3),\n    td:nth-child(4) {\n      font-size: .96rem !important;\n    }\n  }\n}\n\n// Estilos globales de contenedores fuera de la tabla\n@media (min-width: 1573px) {\n  #contenedorDesktop {\n    overflow-x: hidden !important;\n  }\n}\n\n@media (min-width: 992px) and (max-width: 1572px) {\n  .ventas > .flex > div:first-child {\n    flex-basis: 60% !important;\n  }\n\n  #contenedorDesktop {\n    flex-basis: 40% !important;\n  }\n}*/\n#tablaventa thead {\n  display: none !important;\n}\n#tablaventa .productselect {\n  background-color: #ffffff;\n  border: 0.1rem solid #e2e8f0 !important;\n  border-radius: 0.9rem;\n  display: grid !important;\n  grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\n  margin: 0.55rem;\n  padding: 0.65rem;\n  gap: 0.4rem 0.6rem;\n}\n#tablaventa td {\n  display: flex !important;\n  align-items: center;\n  border: 0 !important;\n  padding: 0 !important;\n  width: auto !important;\n  min-width: 0;\n  gap: 0.26rem;\n}\n#tablaventa td .nombreproducto {\n  margin-bottom: 0;\n  overflow-wrap: anywhere;\n  word-break: normal;\n  max-width: none !important;\n}\n#tablaventa td::before {\n  color: #64748b;\n  font-weight: 800;\n  letter-spacing: 0;\n  text-transform: uppercase;\n}\n#tablaventa td:nth-child(1) {\n  grid-column: 1/-1;\n}\n#tablaventa td:nth-child(2) {\n  grid-column: 1;\n  justify-content: flex-start;\n}\n#tablaventa td:nth-child(2)::before {\n  content: \"Cant.\";\n  font-size: 1rem;\n}\n#tablaventa td:nth-child(2) > div {\n  min-width: 0 !important;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.4rem;\n}\n#tablaventa td:nth-child(2) button {\n  height: 2rem;\n  width: 2rem;\n}\n#tablaventa td:nth-child(3) {\n  grid-column: 2;\n  justify-content: center;\n}\n#tablaventa td:nth-child(3)::before {\n  content: \"Und\";\n  font-size: 1rem;\n}\n#tablaventa td:nth-child(4) {\n  grid-column: 3;\n  justify-content: flex-end;\n}\n#tablaventa td:nth-child(4)::before {\n  content: \"Total\";\n  font-size: 1rem;\n}\n#tablaventa td:nth-child(5) {\n  grid-column: 4;\n  justify-content: flex-end;\n}\n\n@media (min-width: 768px) {\n  .headerapp {\n    background-image: linear-gradient(to left, rgba(26, 27, 21, 0.3), rgba(26, 27, 21, 0.03)), url(/build/img/portada1.jpg);\n    background-repeat: no-repeat;\n    background-position: center;\n    background-size: cover;\n  }\n}\n@media (min-width: 1200px) {\n  .headerapp {\n    background-repeat: no-repeat;\n    background-position: center;\n    background-size: cover;\n    background-image: linear-gradient(to left, rgba(26, 27, 21, 0.3), rgba(26, 27, 21, 0.03)), url(/build/img/portada1.jpg);\n  }\n}\n.headerapp__contenedor {\n  position: relative;\n  background-color: #060021;\n  width: min(95%, 144rem);\n  margin: 0 auto;\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n@media (min-width: 768px) {\n  .headerapp__contenedor {\n    background-color: transparent;\n  }\n}\n@media screen and (max-width: 1024px) and (orientation: landscape) {\n  .headerapp__contenedor {\n    height: 64rem;\n  }\n}\n.headerapp__barra {\n  background-image: linear-gradient(to left, rgba(26, 27, 21, 0.3), rgba(26, 27, 21, 0.03)), url(/build/img/portadamoviltransp.png);\n  background-repeat: no-repeat;\n  background-position: center;\n  background-size: cover;\n  height: 50%;\n}\n@media (min-width: 768px) {\n  .headerapp__barra {\n    background-image: none;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    height: auto;\n    margin-top: 2rem;\n    margin-right: 2rem;\n  }\n}\n@media screen and (max-width: 740px) and (orientation: landscape) {\n  .headerapp__barra {\n    height: 83%;\n  }\n}\n.headerapp__logo {\n  flex: 0 0 25%;\n}\n.headerapp__nav {\n  flex: 0 0 75%;\n  display: none;\n}\n@media (min-width: 768px) {\n  .headerapp__nav {\n    display: flex;\n    justify-content: right;\n    gap: 11rem;\n    text-transform: uppercase;\n  }\n}\n@media (min-width: 992px) {\n  .headerapp__nav {\n    gap: 17rem;\n  }\n}\n@media (min-width: 1200px) {\n  .headerapp__nav {\n    gap: 23rem;\n  }\n}\n.headerapp__nav a {\n  color: #FFFFFF;\n  font-size: 1.7rem;\n}\n.headerapp__nav a:hover {\n  color: #DB2777;\n}\n.headerapp__nav a:nth-of-type(4) {\n  background-color: rgb(240, 101, 72);\n  padding: 2rem 4rem;\n}\n.headerapp__nav a:nth-of-type(4):hover {\n  background-color: transparent;\n  border: 1px solid rgb(240, 101, 72);\n  color: rgb(240, 101, 72);\n}\n.headerapp__menu {\n  display: block;\n  position: relative;\n}\n@media (min-width: 768px) {\n  .headerapp__menu {\n    display: none;\n  }\n}\n.headerapp__menubars {\n  background-color: rgba(6, 0, 33, 0.45);\n  color: #FFFFFF;\n  display: flex;\n  justify-content: flex-end;\n  padding: 1rem 2rem;\n}\n.headerapp__bars {\n  background-color: rgba(6, 0, 33, 0.451);\n  padding: 0.7rem 1rem;\n  display: flex;\n  align-items: center;\n  border-radius: 0.8rem;\n}\n.headerapp__bars span {\n  font-size: 1.6rem;\n  font-weight: 600;\n  margin-right: 1rem;\n}\n.headerapp__bars i {\n  font-size: 2rem;\n}\n.headerapp__bars:hover {\n  cursor: pointer;\n}\n.headerapp__navmenu {\n  height: 0rem;\n  text-align: center;\n  background-color: rgba(6, 0, 33, 0.451);\n  overflow: hidden;\n  position: absolute;\n  z-index: 100;\n  width: 100%;\n  transition: all 0.6s ease;\n}\n.headerapp__navmenu a {\n  display: block;\n  color: #FFFFFF;\n  margin-bottom: 2rem;\n  text-transform: uppercase;\n  font-weight: 500;\n}\n.headerapp__navmenu a:hover {\n  color: #ae1c34;\n}\n.headerapp__navmenu.mostrar {\n  padding: 1rem;\n  height: 27rem;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-evenly;\n  align-items: center;\n  text-transform: uppercase;\n  font-weight: 500;\n}\n.headerapp__contenido {\n  position: absolute;\n  top: 31.8rem;\n  background-color: #060021;\n}\n@media (min-width: 768px) {\n  .headerapp__contenido {\n    display: grid;\n    grid-template-columns: 8fr 8fr;\n    justify-content: center;\n    align-items: center;\n    top: 1.8rem;\n    background-color: transparent;\n  }\n}\n@media (min-width: 768px) and (min-width: 1550px) {\n  .headerapp__contenido {\n    width: 100%