t2\r\n    font-size: 1.4rem !important;\r\n    color: v.$blanco !important;\r\n    background-color: v.$turquesa !important;\r\n}\r\n.sweetbtncancel{\r\n    font-size: 1.4rem !important;\r\n    color: v.$blanco !important;\r\n    background-color: v.$gris50 !important;\r\n}\r\n\r\n///clase interna de sweetalert2 corresponde al icono del success\r\n.swal2-success-ring{\r\n    border: 0.25em solid v.$azul60 !important;\r\n}\r\n.swal2-success-line-long, .swal2-success-line-tip{\r\n    background-color: v.$azul60 !important;\r\n}\r\n\r\n.swal2-confirm{ //clase interna de sweetalert es el boton ok despues de confirmar\r\n    background-color: v.$turquesa !important;\r\n    font-size: 1.2rem !important;\r\n}\r\n.swal2-cancel{\r\n    font-size: 1.2rem !important;\r\n}\r\n\r\n.swal2-title{  //titulo = title\r\n    padding-top: 2rem !important;\r\n}\r\n\r\n.swal2-popup.j2-confirm {\r\n  width: min(46rem, calc(100vw - 3.2rem)) !important;\r\n  padding: 0 !important;\r\n  border: .1rem solid rgba(226, 232, 240, .95) !important;\r\n  border-radius: 1.8rem !important;\r\n  background: #fff !important;\r\n  box-shadow: 0 2.4rem 7rem rgba(15, 23, 42, .22), 0 .8rem 2rem rgba(15, 23, 42, .08) !important;\r\n  overflow: hidden !important;\r\n}\r\n\r\n.j2-confirm::before {\r\n  content: '';\r\n  display: block;\r\n  height: .6rem;\r\n  background: linear-gradient(90deg, #4f46e5, #08c6bd);\r\n}\r\n\r\n.j2-confirm .j2-confirm__icon {\r\n  display: grid !important;\r\n  place-items: center !important;\r\n  width: 6rem !important;\r\n  height: 6rem !important;\r\n  margin: 3rem auto 1.6rem !important;\r\n  border: 0 !important;\r\n  border-radius: 1.8rem !important;\r\n  background: #eef2ff !important;\r\n  color: #4f46e5 !important;\r\n  box-shadow: 0 1.4rem 3rem rgba(79, 70, 229, .18) !important;\r\n}\r\n\r\n.j2-confirm .swal2-icon-content {\r\n  color: inherit !important;\r\n  font-size: 3.2rem !important;\r\n  font-weight: 800 !important;\r\n}\r\n\r\n.j2-confirm .j2-confirm__title {\r\n  margin: 0 !important;\r\n  padding: 0 3.2rem !important;\r\n  color: #0f172a !important;\r\n  font-size: 2.25rem !important;\r\n  font-weight: 900 !important;\r\n  line-height: 1.15 !important;\r\n}\r\n\r\n.j2-confirm .j2-confirm__text {\r\n  margin: 1rem auto 0 !important;\r\n  padding: 0 3.8rem !important;\r\n  max-width: 38rem;\r\n  color: #64748b !important;\r\n  font-size: 1.45rem !important;\r\n  font-weight: 500 !important;\r\n  line-height: 1.45 !important;\r\n}\r\n\r\n.j2-confirm .j2-confirm__actions {\r\n  display: grid !important;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 1rem !important;\r\n  width: 100% !important;\r\n  margin: 2.8rem 0 0 !important;\r\n  padding: 1.8rem 2rem 2rem !important;\r\n  border-top: .1rem solid #e2e8f0;\r\n  background: #f8fafc;\r\n}\r\n\r\n.j2-confirm .j2-confirm__button {\r\n  align-items: center;\r\n  border: 0;\r\n  border-radius: 1rem !important;\r\n  display: inline-flex !important;\r\n  font-size: 1.45rem !important;\r\n  font-weight: 800 !important;\r\n  height: 4.4rem;\r\n  justify-content: center;\r\n  margin: 0 !important;\r\n  padding: 0 1.8rem !important;\r\n  transition: transform .18s ease, box-shadow .18s ease, background-color .18s ease;\r\n}\r\n\r\n.j2-confirm .j2-confirm__button:hover {\r\n  transform: translateY(-.1rem);\r\n}\r\n\r\n.j2-confirm .j2-confirm__button--confirm {\r\n  background: linear-gradient(135deg, #14b8a6, #08c6bd) !important;\r\n  box-shadow: 0 1.2rem 2.4rem rgba(20, 184, 166, .24) !important;\r\n  color: #fff !important;\r\n}\r\n\r\n.j2-confirm .j2-confirm__actions--single {\r\n  grid-template-columns: minmax(14rem, 22rem) !important;\r\n  justify-content: center !important;\r\n}\r\n\r\n.j2-confirm .j2-confirm__button--cancel {\r\n  background: #eef2f7 !important;\r\n  color: #475569 !important;\r\n}\r\n\r\n.j2-confirm--dispatch .j2-confirm__icon::before {\r\n  content: \"\\f0d1\";\r\n  font-family: \"Font Awesome 6 Free\";\r\n  font-size: 2.6rem;\r\n  font-weight: 900;\r\n  lin