-color: lighten(v.$gris80, 10);\r\n    }\r\n}\r\n.btn-locked{\r\n    background-color:v.$gris10;\r\n    border-color:darken(v.$gris20, 7);\r\n    color: darken(v.$gris20, 7);\r\n    &:hover{\r\n        cursor: auto;\r\n    }\r\n}\r\n.btn-command{\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: center;\r\n    justify-content: center;\r\n    max-width: 9.6rem;\r\n    width: 100%;\r\n    padding: .7rem;\r\n    border: solid 1px v.$gris30;\r\n    border-radius: .5rem;\r\n    height: 7rem;\r\n    color: v.$gris50;\r\n    font-size: 1.25rem;\r\n    &:hover{\r\n        //background-color: v.$negro90;\r\n        color: v.$gris80;\r\n        //border-color: v.$azul40;\r\n    }\r\n}\r\n//animacion de botones de alternancia de flecha\r\n.btnrotated{\r\n    position: relative;\r\n    padding-right: 3rem;\r\n}\r\n#arrow{\r\n    position: absolute;\r\n    right: .9rem;\r\n    transition: transform 0.3s ease;\r\n}\r\n.rotated {\r\n    transform: rotate(180deg);\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.paginacion{\r\n    text-align: center;\r\n    margin-top: 1rem;\r\n    overflow-x: scroll;\r\n    overflow-y: hidden;\r\n    &__enlace{\r\n        &--actual{\r\n            font-weight: 700;\r\n            color: v.$turquesa;\r\n            font-size: 1.7rem;\r\n        }\r\n        &--numero{\r\n            color: v.$gris80;\r\n            margin: 0 .8rem;\r\n        }\r\n        &--texto{\r\n            color: v.$gris80;\r\n        }\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.stylecheckbox{\r\n    min-width: 10rem;\r\n    //white-space: nowrap;\r\n    input[type=\"checkbox\"] {\r\n        display: none;\r\n    }\r\n    input[type=\"checkbox\"] + label {\r\n        line-height: 2rem;\r\n        cursor: pointer;\r\n    }\r\n    input[type=\"checkbox\"] + label:before{ //crea una caja cuadrada con :before\r\n        content: \"\";\r\n        width: 2.2rem;\r\n        height: 2.2rem;\r\n        