oat: left;\r\n        margin-left: -2.8rem;\r\n        margin-top: .7rem;\r\n        border-right: 0;\r\n        border-top: 0;\r\n        transform: rotate(-55deg);\r\n    }\r\n}\r\n\r\n\r\n////////////////////////////////////////////////////////////////////////////////\r\n.radio-button {\r\n    //display: inline-block;\r\n    position: relative;\r\n    cursor: pointer;\r\n    .radio-button__input {\r\n        position: absolute;\r\n        opacity: 0;\r\n        width: 0;\r\n        height: 0;\r\n    }\r\n      \r\n    .radio-button__label {\r\n        display: inline-block;\r\n        padding-left: 3rem;\r\n        //margin-bottom: 1rem;\r\n        position: relative;\r\n        font-size: 1.4rem;\r\n        color: v.$blanco;\r\n        cursor: pointer;\r\n        transition: all 0.3s ease-in-out;\r\n    }\r\n      \r\n    .radio-button__span {\r\n        position: absolute;\r\n        top: 50%;\r\n        left: 0;\r\n        transform: translateY(-50%);\r\n        width: 2rem;\r\n        height: 2rem;\r\n        border-radius: 50%;\r\n        border: 2px solid v.$gris50;\r\n        transition: all 0.3s ease-in-out;\r\n    }\r\n\r\n    .radio-button__input:checked + .radio-button__label .radio-button__span {\r\n        transform: translateY(-50%) scale(0.9);\r\n        border: 5px solid v.$azul60;\r\n        color: v.$azul60;\r\n    }\r\n    .radio-button__input:checked + .radio-button__label {\r\n        color: v.$azul60;\r\n    } \r\n    .radio-button__label:hover .radio-button__span {\r\n        transform: translateY(-20%) scale(1.2);\r\n        border-color: v.$azul60;\r\n        box-shadow: 0 0 10px v.$azul60;\r\n    }\r\n}","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.midialog-sm{\r\n    &::backdrop{\r\n        background-color: v.$backdrop;\r\n    }\r\n    width: 90%;\r\n    max-width: 50rem;\r\n    border: none;\r\n    border-radius: .4rem;\r\n    .ocultar{\r\n        display: none;\r\n    }\r\n    .select2-selection__rendered{\r\n    