       min-width: 2.9rem;\r\n                }\r\n                label{\r\n                    cursor: pointer;\r\n                    max-width: 0;\r\n                    opacity: 0;\r\n                    overflow: hidden;\r\n                    transition: max-width 300ms ease, opacity 200ms ease;\r\n                }\r\n                &:hover{\r\n                    background-color: rgba(255, 255, 255, .14);\r\n                    border-radius: 0.5rem;\r\n                    color: v.$gris30;\r\n                }\r\n                &.activo{\r\n                    background-color: v.$azul0;\r\n                    border-radius: 0.5rem;\r\n                    color: v.$indigo;\r\n                }\r\n                @include m.tablet{\r\n                    display: flex;\r\n                    align-items: center;\r\n                    justify-content: center;\r\n                    gap: 0;\r\n                    font-size: 1.2rem;\r\n                    margin-bottom: .8rem;\r\n                    min-height: 5.4rem;\r\n                    text-align: left;\r\n                }\r\n            }\r\n        }\r\n\r\n        &:hover,\r\n        &.sidebar-fija{\r\n            .sidebar-nav{\r\n                margin-top: 5rem;\r\n                a{\r\n                    label{\r\n                        max-width: 16rem;\r\n                        opacity: 1;\r\n                    }\r\n                    @include m.tablet{\r\n                        justify-content: flex-start;\r\n                        gap: .5rem;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    \r\n    }//cierre del .sidebar\r\n\r\n\r\n\r\n    .barra-mobile{  //clase que esta en header.php, crea sub barra para ocultar los links <a> del sidebar en dispositivos moviles\r\n        &.ocultarmenu{\r\n            display: none;\r\n        }\r\n        background-color: v.$indigo;\r\n        margin-top: 0;\r\n        padding: 2rem 4rem;\r\n        position: sti