 span{\r\n        align-items: center;\r\n        background: #eef2ff;\r\n        border-radius: .7rem;\r\n        color: var(--config-primary);\r\n        display: inline-flex;\r\n        height: 3.4rem;\r\n        justify-content: center;\r\n        width: 3.4rem;\r\n      }\r\n    }\r\n\r\n    h3{\r\n      color: var(--config-text);\r\n      font-size: 1.55rem;\r\n      font-weight: 800;\r\n      line-height: 1.15;\r\n      margin: 0;\r\n    }\r\n\r\n    p{\r\n      color: var(--config-muted) !important;\r\n      font-size: 1.05rem !important;\r\n      margin: .2rem 0 0 !important;\r\n    }\r\n\r\n    small{\r\n      background: #eef2ff;\r\n      border: 1px solid #c7d2fe;\r\n      border-radius: 999px;\r\n      color: var(--config-primary-dark);\r\n      font-size: 1rem;\r\n      font-weight: 700;\r\n      padding: .35rem .75rem;\r\n      white-space: nowrap;\r\n    }\r\n  }\r\n\r\n  .config-subscription-history__table{\r\n    overflow-x: auto;\r\n\r\n    table{\r\n      border-collapse: collapse;\r\n      width: 100%;\r\n    }\r\n\r\n    th{\r\n      background: #f1f5f9;\r\n      color: #64748b;\r\n      font-size: 1rem;\r\n      font-weight: 700;\r\n      letter-spacing: .02em;\r\n      padding: .9rem 1rem;\r\n      text-transform: uppercase;\r\n      white-space: nowrap;\r\n    }\r\n\r\n    td{\r\n      border-top: 1px solid #e2e8f0;\r\n      color: var(--config-text);\r\n      font-size: 1.08rem;\r\n      padding: .9rem 1rem;\r\n      vertical-align: middle;\r\n      white-space: nowrap;\r\n    }\r\n\r\n    tr:hover td{\r\n      background: #fbfdff;\r\n    }\r\n  }\r\n\r\n  .config-subscription-pill{\r\n    background: #ecfeff;\r\n    border: 1px solid #a5f3fc;\r\n    color: #0f766e;\r\n  }\r\n\r\n  .config-subscription-empty{\r\n    color: var(--config-muted) !important;\r\n    text-align: center;\r\n  }\r\n\r\n  .config-subscription-dialog{\r\n    background: #fff;\r\n    border: 0;\r\n    border-radius: 1.1rem;\r\n    box-shadow: 0 2.4rem 7rem rgba(15,23,42,.22);\r\n    max-width: 62rem;\r\n    overflow: hidden;\r\n    padding: 0;\r\n    width: min(94vw, 62rem);\r\n\r\n    &::backdrop{\r\n      background: rgba(15,23,42,.54);\r\n      backdrop-filter: blur(.35rem);\r\n    }\r\n  }\r\n\r\n  .config-subscription-dialog__header{\r\n    align-items: center;\r\n    background: linear-gradient(135deg, rgba(79,70,229,.10), rgba(6,182,212,.08));\r\n    border-bottom: 1px solid #dbe3ef;\r\n    display: grid;\r\n    gap: 1rem;\r\n    grid-template-columns: auto minmax(0, 1fr) auto;\r\n    padding: 1.5rem;\r\n\r\n    > span{\r\n      align-items: center;\r\n      background: #fff;\r\n      border: 1px solid #dbe3ef;\r\n      border-radius: .75rem;\r\n      color: var(--config-primary);\r\n      display: inline-flex;\r\n      font-size: 1.7rem;\r\n      height: 4.4rem;\r\n      justify-content: center;\r\n      width: 4.4rem;\r\n    }\r\n\r\n    small{\r\n      color: var(--config-primary);\r\n      display: block;\r\n      font-size: 1rem;\r\n      font-weight: 800;\r\n      letter-spacing: .08em;\r\n    }\r\n\r\n    h4{\r\n      color: var(--config-text);\r\n      font-size: 2rem;\r\n      font-weight: 800;\r\n      line-height: 1.1;\r\n      margin: 0;\r\n    }\r\n\r\n    p{\r\n      color: var(--config-muted) !important;\r\n      font-size: 1.08rem !important;\r\n      margin: .25rem 0 0 !important;\r\n    }\r\n  }\r\n\r\n  .config-subscription-dialog__close{\r\n    align-items: center;\r\n    background: #fff1f2;\r\n    border: 0;\r\n    border-radius: 999px;\r\n    color: #ef4444;\r\n    cursor: pointer;\r\n    display: inline-flex;\r\n    height: 3.4rem;\r\n    justify-content: center;\r\n    width: 3.4rem;\r\n  }\r\n\r\n  .config-subscription-dialog__form{\r\n    padding: 1.4rem;\r\n  }\r\n\r\n  .config-subscription-dialog__grid{\r\n    display: grid;\r\n    gap: 1rem;\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n\r\n    label{\r\n      display: grid;\r\n      gap: .45rem;\r\n      margin: 0;\r\n\r\n      > span{\r\n        color: var(--config-text);\r\n        font-size: 1.08rem;\r\n        font-weight: 700;\r\n      }\r\n    }\r\n\r\n    input,\r\n    select,\r\n    textarea{\r\n      background: #f8fafc !important;\r\n      border: 1px solid #cbd5e1 !important;\r\n      border-radius: .75rem !important;\r\n      color: var(--config-text) !important;\r\n      font-size: 1.15rem !important;\r\n      min-height: 4rem !important;\r\n      outline: none;\r\n      padding: .8rem .95rem !important;\r\n      width: 100%;\r\n\r\n      &:focus{\r\n        border-color: rgba(79,70,229,.70) !important;\r\n        box-shadow: 0 0 0 .25rem rgba(79,70,229,.12) !important;\r\n      }\r\n    }\r\n\r\n    textarea{\r\n      min-height: 8.5rem !important;\r\n      resize: vertical;\r\n    }\r\n  }\r\n\r\n  .config-subscription-dialog__wide{\r\n    grid-column: 1 / -1;\r\n  }\r\n\r\n  .config-subscription-dialog__actions{\r\n    border-top: 1px solid #e2e8f0;\r\n    display: grid;\r\n    gap: .8rem;\r\n    grid-template-columns: 1fr 1fr;\r\n    margin-top: 1.2rem;\r\n    padding-top: 1.2rem;\r\n\r\n    input{\r\n      width: 100%;\r\n    }\r\n  }\r\n\r\n  @media (max-width: 1100px){\r\n    .config-subscription__grid,\r\n    .config-subscription-metrics{\r\n      grid-template-columns: 1fr 1fr;\r\n    }\r\n  }\r\n\r\n  @media (max-width: 720px){\r\n    .config-subscription__hero,\r\n    .config-subscription-card__header,\r\n    .config-subscription-history__header{\r\n      align-items: flex-start;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .config-subscription__actions,\r\n    .config-subscription__button{\r\n      width: 100%;\r\n    }\r\n\r\n    .config-subscription__grid,\r\n    .config-subscription-metrics,\r\n    .config-subscription-dialog__grid,\r\n    .config-subscription-dialog__actions{\r\n      grid-template-columns: 1fr;\r\n    }\r\n  }\r\n\r\n  .config-list-panel{\r\n    background: linear-gradient(180deg, rgba(248,250,252,.95), #fff);\r\n    border: 1px solid