  margin: 0;\r\n    }\r\n\r\n    .config-datatable-custom-label{\r\n      color: var(--config-text);\r\n      font-size: 1.12rem;\r\n      font-weight: 800;\r\n    }\r\n\r\n    select,\r\n    input{\r\n      background: #f8fafc;\r\n      border: 1px solid #cbd5e1;\r\n      border-radius: .65rem;\r\n      color: var(--config-text);\r\n      font-size: 1.08rem;\r\n      font-weight: 700;\r\n      height: 3.2rem;\r\n      outline: none;\r\n    }\r\n\r\n    select{\r\n      min-width: 6.6rem;\r\n      padding: 0 2.8rem 0 .9rem;\r\n    }\r\n\r\n    input{\r\n      min-width: 24rem;\r\n      padding: 0 1rem;\r\n    }\r\n\r\n    select:focus,\r\n    input:focus{\r\n      border-color: var(--config-primary);\r\n      box-shadow: 0 0 0 .25rem rgba(79, 70, 229, .12);\r\n    }\r\n  }\r\n\r\n  .config-datatable-length-select{\r\n    position: relative;\r\n  }\r\n\r\n  .config-datatable-length-select__button{\r\n    align-items: center;\r\n    background: #f8fafc;\r\n    border: 1px solid #cbd5e1;\r\n    border-radius: .65rem;\r\n    color: var(--config-text);\r\n    display: inline-flex;\r\n    font-size: 1.08rem;\r\n    font-weight: 800;\r\n    gap: 1.1rem;\r\n    height: 3.2rem;\r\n    justify-content: space-between;\r\n    min-width: 7rem;\r\n    padding: 0 .85rem;\r\n    transition: border-color .2s ease, box-shadow .2s ease;\r\n\r\n    i{\r\n      color: #64748b;\r\n      font-size: .85rem;\r\n      transition: transform .2s ease;\r\n    }\r\n  }\r\n\r\n  .config-datatable-length-select__menu{\r\n    background: #fff;\r\n    border: 1px solid #cbd5e1;\r\n    border-radius: .75rem;\r\n    box-shadow: 0 1.4rem 3rem rgba(15, 23, 42, .16);\r\n    display: none;\r\n    left: 0;\r\n    min-width: 7rem;\r\n    overflow: hidden;\r\n    padding: .35rem;\r\n    position: absolute;\r\n    top: calc(100% + .45rem);\r\n    z-index: 20;\r\n\r\n    button{\r\n      background: transparent;\r\n      border: 0;\r\n      border-radius: .55rem;\r\n      color: var(--config-text);\r\n      di