er-bottom: 1px solid #d5deea;\r\n  border-top: 1px solid #d5deea;\r\n  color: #26364d;\r\n  font-size: 1.25rem;\r\n  font-weight: 800;\r\n  padding: 1rem;\r\n  text-align: left;\r\n}\r\n\r\n.ordenresumen-table thead th:first-child {\r\n  border-left: 1px solid #d5deea;\r\n  border-radius: .55rem 0 0 .55rem;\r\n}\r\n\r\n.ordenresumen-table thead th:last-child {\r\n  border-right: 1px solid #d5deea;\r\n  border-radius: 0 .55rem .55rem 0;\r\n}\r\n\r\n.ordenresumen-table tbody td,\r\n.ordenresumen-table tfoot td,\r\n.ordenresumen-table tfoot th {\r\n  border-bottom: 1px solid #e2e8f0;\r\n  font-size: 1.35rem;\r\n  padding: 1.05rem;\r\n  vertical-align: middle;\r\n}\r\n\r\n.ordenresumen-table tfoot th,\r\n.ordenresumen-table tfoot td {\r\n  background: #f8fafc;\r\n  color: #111827;\r\n  font-weight: 800;\r\n}\r\n\r\n.ordenresumen-product-cell {\r\n  color: #14233a;\r\n  font-weight: 700;\r\n}\r\n\r\n.ordenresumen-product-info {\r\n  align-items: center;\r\n  display: flex;\r\n  gap: 1rem;\r\n  min-width: 28rem;\r\n}\r\n\r\n.ordenresumen-product-img {\r\n  background: #f8fafc;\r\n  border: 1px solid #e2e8f0;\r\n  border-radius: .55rem;\r\n  height: 5.8rem;\r\n  object-fit: contain;\r\n  padding: .25rem;\r\n  width: 5.8rem;\r\n}\r\n\r\n.ordenresumen-side {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1rem;\r\n}\r\n\r\n.ordenresumen-info-card {\r\n  padding: 1.25rem;\r\n}\r\n\r\n.ordenresumen-info-title {\r\n  font-size: 1.55rem;\r\n  margin-bottom: 1rem;\r\n}\r\n\r\n.ordenresumen-info-line {\r\n  align-items: center;\r\n  color: #475569;\r\n  display: flex;\r\n  font-size: 1.35rem;\r\n  gap: .55rem;\r\n  line-height: 1.35;\r\n  margin: .3rem 0;\r\n}\r\n\r\n.ordenresumen-bottom {\r\n  margin-top: 1.6rem;\r\n  padding: 1.4rem;\r\n}\r\n\r\n.ordenresumen-bottom-grid {\r\n  display: grid;\r\n  gap: 1.4rem;\r\n  grid-template-columns: minmax(0, 2fr) minmax(28rem, 1fr);\r\n}\r\n\r\n.ordenresumen-observations,\r\n.ordenresumen-payment-summary {\r\n  background: #f8fafc;\r\n  border: 1px solid #dbe4f0;\r\n  border-radius: .8rem;\r\n  padding: 1.35rem;\r\n}\r\n\r\n#miDialogoEliminarOrden.orden-delete-dialog[open] {\r\n  display: flex;\r\n  flex-direction: column;\r\n  max-height: calc(100dvh - 2.4rem);\r\n  overflow: hidden;\r\n}\r\n\r\n#miDialogoEliminarOrden .orden-delete-dialog__body {\r\n  flex: 1 1 auto;\r\n  min-height: 0;\r\n  padding-bottom: 0;\r\n}\r\n\r\n#miDialogoEliminarOrden .orden-delete-dialog__products {\r\n  max-height: clamp(16rem, 26dvh, 24rem);\r\n  overflow: auto;\r\n}\r\n\r\n#miDialogoEliminarOrden .orden-delete-dialog__products table {\r\n  min-width: 46rem;\r\n}\r\n\r\n#miDialogoEliminarOrden .orden-delete-dialog__footer {\r\n  box-shadow: 0 -12px 24px rgba(15, 23, 42, .08);\r\n  z-index: 2;\r\n}\r\n\r\n@media (max-width: 1100px) {\r\n  .ordenresumen-metrics,\r\n  .ordenresumen-main-grid,\r\n  .ordenresumen-bottom-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .ordenresumen-side {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n@media (max-width: 768px) {\r\n  .ordenresumen-page {\r\n    padding: 1rem;\r\n  }\r\n\r\n  .ordenresumen-actions {\r\n    display: grid;\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  }\r\n\r\n  .ordenresumen-actions .btn-command {\r\n    max-width: none;\r\n    min-width: 0;\r\n  }\r\n\r\n  .ordenresumen-side {\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .ordenresumen-card-head {\r\n    align-items: flex-start;\r\n    flex-direction: column;\r\n  }\r\n\r\n  .ordenresumen-products-card,\r\n  .ordenresumen-bottom {\r\n    padding: 1rem;\r\n  }\r\n}\r\n","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n@media (max-width: 991px) {\r\n\r\n  .producto {\r\n    position: relative;\r\n\r\n    //indicador ok cuando se selecciona un producto en modo movil\r\n    &.producto-agregado-feedback {\r\n        background-color: #ffffff;\r\n        border-color: #818cf8;\r\n        box-shadow: 0 0 0 .18rem rgba(99, 102, 241, .28), 0 1.2rem 2.4rem rgba(15, 23, 42, .10) !important;\r\n        position: relative;\r\n\r\n      &::after {\r\n          display: flex;\r\n          align-items: center;\r\n          justify-content: center;\r\n          background: #22c55e;\r\n          border: .25rem solid #ffffff;\r\n          border-radius: 999px;\r\n          box-shadow: 0 .7rem 1.6rem rgba(34, 197, 94, .28);\r\n          color: #ffffff;\r\n          content: \"\\f00c\";\r\n          font-family: \"Font Awesome 6 Free\";\r\n          font-size: 1.35rem;\r\n          font-weight: 900;\r\n          height: 2.8rem;\r\n          line-height: 1;\r\n          position: absolute;\r\n          right: .8rem;\r\n          top: .8rem;\r\n          width: 2.8rem;\r\n          z-index: 2;\r\n      }\r\n    }\r\n  }\r\n\r\n  //contandor de productos en el boton para abrir modal para facturar/cotizar\r\n  #carritoMovilBadge {\r\n    align-items: center;\r\n    background: #fff;\r\n    border: 2px solid #0ea5e9;\r\n    border-radius: 999px;\r\n    color: #4338ca;\r\n    display: none;\r\n    font-size: 1.2rem;\r\n    font-weight: 900;\r\n    height: 2.6rem;\r\n    justify-content: center;\r\n    min-width: 2.6rem;\r\n    padding: 0 .55rem;\r\n    position: absolute;\r\n    right: -.25rem;\r\n    top: -.35rem;\r\n    box-shadow: 0 .6rem 1.4rem rgba(15, 23, 42, .18);\r\n\r\n    &.is-visible {\r\n      display: inline-flex;\r\n    }\r\n  }\r\n\r\n  //contador animado tipo modal o toast al seleccionar producto en pantalla pequeña\r\n  #ventaCarritoToast {\r\n    display: flex;\r\n    align-items: center;\r\n    background: rgba(255, 255, 255, .98);\r\n    border: 1px solid #dbe4f0;\r\n    border-left: .45rem solid #16a34a;\r\n    border-radius: 1.2rem;\r\n    box-shadow: 0 1.4rem 3rem rgba(15, 23, 42, .18);\r\n    color: #0f172a;\r\n    gap: .9rem;\r\n    left: 50%;\r\n    max-width: calc(100vw - 3.2rem);\r\n    opacity: 0;\r\n    padding: 1rem 1.2rem;\r\n    pointer-events: none;\r\n    position: fixed;\r\n    top: 1rem;\r\n    transform: translate(-50%, -1.2rem);\r\n    transition: opacity .22s ease, transform .22s ease;\r\n    width: min(34rem, calc(100vw - 3.2rem));\r\n    z-index: 70;\r\n\r\n    &.is-visible {\r\n      opacity: 1;\r\n      transform: translate(-50%, 0);\r\n    }\r\n  }\r\n\r\n  .venta-carrito-toast{\r\n    &__icon {\r\n      align-items: center;\r\n      background: #dcfce7;\r\n      border-radius: .9rem;\r\n      color: #16a34a;\r\n      display: inline-flex;\r\n      flex: 0 0 3.4rem;\r\n      height: 3.4rem;\r\n      justify-content: center;\r\n      width: 3.4rem;\r\n    }\r\n\r\n    &__title {\r\n      color: #0f172a;\r\n      display: block;\r\n      font-size: 1.4rem;\r\n      font-weight: 700;\r\n      line-height: 1.15;\r\n      margin: 0;\r\n    }\r\n\r\n    &__meta {\r\n      color: #5c6b80;\r\n      display: block;\r\n      font-size: 1.2rem;\r\n      font-weight: 500;\r\n      line-height: 1.2;\r\n      margin-top: .6rem;\r\n    }\r\n  }\r\n\r\n  @keyframes carritoFeedbackPulse {\r\n    0% {\r\n      transform: scale(1);\r\n    }\r\n\r\n    45% {\r\n      transform: scale(1.08);\r\n    }\r\n\r\n    100% {\r\n      transform: scale(1);\r\n    }\r\n  }\r\n}\r\n\r\n\r\n/*\r\n// 1. Unificamos la estructura repetida de la tabla para pantallas < 1573px\r\n@mixin card-table-layout {\r\n  display: block !important;\r\n  width: 100% !important;\r\n\r\n  tbody {\r\n    display: block !important;\r\n    width: 100% !important;\r\n  }\r\n\r\n  thead {\r\n    display: none !important;\r\n  }\r\n\r\n  .productselect {\r\n    background-color: #ffffff;\r\n    border: .1rem solid #e2e8f0 !important;\r\n    border-radius: .9rem;\r\n    display: grid !important;\r\n  }\r\n\r\n  td {\r\n    display: flex !important;\r\n    align-items: center;\r\n    border: 0 !important;\r\n    padding: 0 !important;\r\n    width: auto !important;\r\n    min-width: 0;\r\n\r\n    &::before {\r\n      color: #64748b;\r\n      font-weight: 800;\r\n      letter-spacing: 0;\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    &:nth-child(1) { grid-column: 1 / -1; }\r\n    \r\n    &:nth-child(2) {\r\n      grid-column: 1;\r\n      justify-content: flex-start;\r\n      &::before { content: \"Cant.\"; }\r\n      \r\n      > div {\r\n        min-width: 0 !important;\r\n      }\r\n    }\r\n\r\n    &:nth-child(3) {\r\n      grid-column: 2;\r\n      justify-content: center;\r\n      &::before { content: \"Und\"; }\r\n    }\r\n\r\n    &:nth-child(4) {\r\n      grid-column: 3;\r\n      justify-content: flex-end;\r\n      &::before { content: \"Total\"; }\r\n    }\r\n\r\n    &:nth-child(5) {\r\n      grid-column: 4;\r\n      justify-content: flex-end;\r\n    }\r\n  }\r\n}\r\n\r\n// 2. Estilos Base\r\n#contenedorDesktop,\r\n#contenidocarrito,\r\n#tablaventa {\r\n  min-width: 0;\r\n}\r\n\r\n#tablaventa {\r\n  table-layout: fixed;\r\n\r\n  th, td {\r\n    min-width: 0;\r\n  }\r\n\r\n  .nombreproducto {\r\n    overflow-wrap: anywhere;\r\n    word-break: normal;\r\n  }\r\n\r\n  // ---------------------------------------------\r\n  // Pantallas Grandes (Desktop > 1573px)\r\n  // ---------------------------------------------\r\n  @media (min-width: 1573px) {\r\n    th, td {\r\n      padding-left: .45rem !important;\r\n      padding-right: .45rem !important;\r\n      font-size: 1.15rem !important;\r\n\r\n      // Anchos por columna\r\n      &:nth-child(1) { width: 31%; }\r\n      &:nth-child(2) { width: 24%; }\r\n      &:nth-child(3) { width: 14%; }\r\n      &:nth-child(4) { width: 23%; }\r\n      &:nth-child(5) { width: 8%; }\r\n    }\r\n\r\n    th {\r\n      white-space: nowrap;\r\n    }\r\n\r\n    td:nth-child(2) {\r\n      > div {\r\n        gap: .45rem !important;\r\n        justify-content: center !important;\r\n        min-width: 0 !important;\r\n        width: 100% !important;\r\n      }\r\n      button {\r\n        height: 2.2rem !important;\r\n        width: 2.2rem !important;\r\n      }\r\n    }\r\n\r\n    td:nth-child(3),\r\n    td:nth-child(4) {\r\n      font-size: 1.08rem !important;\r\n      white-space: nowrap;\r\n    }\r\n\r\n    .nombreproducto {\r\n      font-size: 1.2rem !important;\r\n      line-height: 1.22 !important;\r\n      max-width: none !important;\r\n    }\r\n\r\n    .inputcantidad {\r\n      font-size: 1.12rem !important;\r\n      height: 2.8rem !important;\r\n      max-width: 6.6rem !important;\r\n      min-width: 5.8rem !important;\r\n      padding-left: .35rem !important;\r\n      padding-right: .35rem !important;\r\n      width: 6.4rem !important;\r\n    }\r\n\r\n    .menos, .mas {\r\n      font-size: 1.3rem !important;\r\n      height: 1.8rem !important;\r\n      width: 1.8rem !important;\r\n    }\r\n\r\n    .eliminarProducto {\r\n      height: 2.8rem !important;\r\n      width: 2.8rem !important;\r\n    }\r\n  }\r\n\r\n  // ---------------------------------------------\r\n  // Modos Card (Pantallas < 1573px)\r\n  // ---------------------------------------------\r\n  @media (max-width: 1572px) {\r\n    @include card-table-layout;\r\n  }\r\n\r\n  // Ajustes específicos entre 992px y 1572px\r\n  @media (min-width: 992px) and (max-width: 1572px) {\r\n    .productselect {\r\n      gap: .45rem .62rem;\r\n      grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\r\n      margin: .55rem;\r\n      padding: .65rem !important;\r\n    }\r\n\r\n    td {\r\n      font-size: 1.12rem !important;\r\n      gap: .28rem;\r\n\r\n      &::before { font-size: .9rem; }\r\n    }\r\n\r\n    .nombreproducto {\r\n      font-size: 1.22rem !important;\r\n      line-height: 1.18 !important;\r\n      margin-bottom: 0 !important;\r\n    }\r\n\r\n    td:nth-child(2) {\r\n      > div { gap: .34rem !important; }\r\n      button { height: 2.1rem !important; width: 2.1rem !important; }\r\n    }\r\n  }\r\n\r\n  // Ajustes específicos < 991px\r\n  @media (max-width: 991px) {\r\n    .productselect {\r\n      gap: .55rem .58rem;\r\n      grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\r\n      margin: .65rem;\r\n      padding: .75rem .65rem !important;\r\n    }\r\n\r\n    td {\r\n      font-size: 1.06rem !important;\r\n      gap: .26rem;\r\n\r\n      &::before { font-size: .9rem; }\r\n    }\r\n\r\n    .nombreproducto {\r\n      font-size: 1.22rem !important;\r\n      line-height: 1.2 !important;\r\n      margin-bottom: 0 !important;\r\n      max-width: none !important;\r\n    }\r\n\r\n    td:nth-child(2) {\r\n      > div { gap: .32rem !important; }\r\n      button { height: 2.1rem !important; width: 2.1rem !important; }\r\n    }\r\n  }\r\n\r\n  // Ajustes específicos < 460px\r\n  @media (max-width: 460px) {\r\n    .productselect {\r\n      gap: .5rem .42rem;\r\n      grid-template-columns: minmax(11.6rem, 1fr) minmax(6.1rem, auto) minmax(7.1rem, auto) 2.8rem;\r\n      padding-left: .55rem !important;\r\n      padding-right: .55rem !important;\r\n    }\r\n\r\n    td {\r\n      font-size: .96rem !important;\r\n      gap: .2rem;\r\n\r\n      &::before { font-size: .76rem; }\r\n    }\r\n\r\n    td:nth-child(2) {\r\n      > div { gap: .24rem !important; }\r\n      button { height: 2rem !important; width: 2rem !important; }\r\n    }\r\n\r\n    td:nth-child(3),\r\n    td:nth-child(4) {\r\n      font-size: .96rem !important;\r\n    }\r\n  }\r\n}\r\n\r\n// Estilos globales de contenedores fuera de la tabla\r\n@media (min-width: 1573px) {\r\n  #contenedorDesktop {\r\n    overflow-x: hidden !important;\r\n  }\r\n}\r\n\r\n@media (min-width: 992px) and (max-width: 1572px) {\r\n  .ventas > .flex > div:first-child {\r\n    flex-basis: 60% !important;\r\n  }\r\n\r\n  #contenedorDesktop {\r\n    flex-basis: 40% !important;\r\n  }\r\n}*/\r\n\r\n// TABLA DE CARRITO DE VENTAS\r\n#tablaventa {\r\n    thead {\r\n        display: none !important;\r\n    }\r\n\r\n    .productselect { //fila de la tabla <tr>\r\n        background-color: #ffffff;\r\n        border: .1rem solid #e2e8f0 !important;\r\n        border-radius: .9rem;\r\n        display: grid !important;\r\n        grid-template-columns: minmax(14rem, 1fr) minmax(6.8rem, auto) minmax(8rem, auto) 3rem;\r\n        margin: .55rem;\r\n        padding: .65rem;\r\n        gap: .4rem .6rem;\r\n    }\r\n\r\n    td {\r\n        display: flex !important;\r\n        align-items: center;\r\n        border: 0 !important;\r\n        padding: 0 !important;\r\n        width: auto !important;\r\n        min-width: 0;\r\n        gap: .26rem;\r\n        .nombreproducto {\r\n            margin-bottom: 0;\r\n            overflow-wrap: anywhere;\r\n            word-break: normal;\r\n            max-width: none !important;\r\n        }\r\n        &::before {\r\n        color: #64748b;\r\n        font-weight: 800;\r\n        letter-spacing: 0;\r\n        text-transform: uppercase;\r\n        }\r\n        &:nth-child(1) { \r\n            grid-column: 1 / -1; \r\n        }\r\n        &:nth-child(2) {\r\n            grid-column: 1;\r\n            justify-content: flex-start;\r\n            &::before { \r\n                content: \"Cant.\";\r\n                font-size: 1rem; \r\n            }\r\n            \r\n            > div {\r\n                min-width: 0 !important;\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: center;\r\n                gap: 0.4rem;\r\n            }\r\n            button { \r\n                height: 2rem; \r\n                width: 2rem; \r\n            }\r\n        }\r\n        &:nth-child(3) {\r\n            grid-column: 2;\r\n            justify-content: center;\r\n            &::before { \r\n                content: \"Und\";\r\n                font-size: 1rem;\r\n            }\r\n        }\r\n        &:nth-child(4) {\r\n            grid-column: 3;\r\n            justify-content: flex-end;\r\n            &::before { \r\n                content: \"Total\";\r\n                font-size: 1rem;\r\n            }\r\n        }\r\n        &:nth-child(5) {\r\n            grid-column: 4;\r\n            justify-content: flex-end;\r\n        }\r\n    } //fin td\r\n}\r\n// fin tabla de carrito de compras","@use 'base/variables' as v;\r\n@use 'base/mixins' as m;\r\n\r\n.headerapp {\r\n    @include m.tablet { \r\n        background-image:linear-gradient(to left, rgba(v.$negro90, .3), rgba(v.$negro90, .03)), url(/build/img/portada1.jpg);\r\n        // //linear-gradient(to left, rgba(v.$negro90, .1), rgba(v.$negro90, 1)), \r\n        background-repeat: no-repeat;\r\n        background-position: center;\r\n        background-size: cover;\r\n    }\r\n    \r\n    // height: 10%;\r\n    @include m.xl_desktop { \r\n        background-repeat: no-repeat;\r\n        background-position: center;\r\n        background-size: cover;\r\n        background-image:linear-gradient(to left, rgba(v.$negro90, .3), rgba(v.$negro90, .03)), url(/build/img/portada1.jpg);\r\n    }\r\n    &__contenedor{\r\n        position: relative;\r\n        background-color: #060021;\r\n        @include m.contenedor;\r\n        height: 100vh;\r\n        display: flex;\r\n        flex-direction: column;\r\n        width: 100%;\r\n        @include m.tablet { \r\n            background-color: transparent;\r\n        }\r\n        // @include m.desktop { \r\n        //     height: 74%;\r\n        // }\r\n        @media screen and (max-width: 1024px) and (orientation: landscape) {\r\n            height: 64rem;\r\n        }\r\n    }\r\n    &__barra{\r\n        background-image:linear-gradient(to left, rgba(v.$negro90, .3), rgba(v.$negro90, .03)), url(/build/img/portadamoviltransp.png);\r\n        background-repeat: no-repeat;\r\n        background-position: center;\r\n        background-size: cover;\r\n        height: 50%;\r\n       \r\n        // padding-top: 2rem;\r\n        @include m.tablet {\r\n            background-image: none;\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            height: auto;\r\n            margin-top: 2rem;\r\n            margin-right: 2rem;\r\n        }\r\n        @media screen and (max-width: 740px) and (orientation: landscape) {\r\n            height: 83%;\r\n        }\r\n    }\r\n    &__logo{\r\n        //background-color: aquamarine;\r\n        //width: 25%;\r\n        flex: 0 0 25%;\r\n        \r\n    }\r\n    &__nav{\r\n        //width: 75%;\r\n        flex: 0 0 75%;\r\n        //background-color: blue;\r\n        display: none;\r\n        @include m.tablet{\r\n        display: flex;\r\n        justify-content: right;\r\n        gap: 11rem;\r\n        text-transform: uppercase;\r\n        }\r\n        @include m.xl_tablet { \r\n            gap: 17rem;\r\n        }\r\n        @include m.xl_desktop { \r\n            gap: 23rem;\r\n        }\r\n        a{\r\n            color: v.$blanco;\r\n            font-size: 1.7rem;\r\n            &:hover {\r\n                color: v.$rosa;\r\n            }\r\n            &:nth-of-type(4){\r\n                background-color: v.$naranja100;\r\n                padding: 2rem 4rem;\r\n                &:hover{\r\n                    background-color: transparent;\r\n                    border: 1px solid v.$naranja100;\r\n                    color: v.$naranja100;\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    &__menu{\r\n        display: block;\r\n        position: relative;\r\n        @include m.tablet{\r\n            display: none;\r\n        }\r\n    }\r\n    &__menubars{\r\n        background-color: rgba(6, 0, 33, 45%);\r\n        color: v.$blanco;\r\n        display: flex;\r\n        justify-content: flex-end;\r\n        padding: 1rem 2rem;\r\n        // border-top-left-radius: 0.8rem;\r\n        // border-top-right-radius: 0.8rem;\r\n    }\r\n    &__bars{\r\n        background-color: rgba(6, 0, 33, 0.451);\r\n        padding: .7rem 1rem;\r\n        display: flex;\r\n        align-items: center;\r\n        border-radius: .8rem;\r\n        span{\r\n            font-size: 1.6rem;\r\n            font-weight: 600;\r\n            margin-right: 1rem;\r\n        }\r\n        i{\r\n            font-size: 2rem;\r\n        }\r\n        &:hover{\r\n            cursor: pointer;\r\n        }\r\n    }\r\n    &__navmenu{\r\n        height: 0rem;\r\n        text-align: center;\r\n        background-color: rgba(6, 0, 33, 0.451);\r\n        overflow: hidden;\r\n        position: absolute;\r\n        z-index: 100;\r\n        width: 100%;\r\n        a{\r\n            display: block;\r\n            color: v.$blanco;\r\n            margin-bottom: 2rem;\r\n            text-transform: uppercase;\r\n            font-weight: 500;\r\n            &:hover {\r\n               color: #ae1c34;  \r\n            }\r\n        }\r\n        transition: all .6s ease;\r\n        &.mostrar{ \r\n            padding: 1rem;\r\n            height: 27rem;\r\n            display: flex;\r\n            flex-direction: column;\r\n            justify-content: space-evenly;\r\n            align-items: center;\r\n            text-transform: uppercase;\r\n            font-weight: 500;\r\n        }\r\n    }\r\n\r\n    &__contenido{\r\n        position: absolute;\r\n        top: 31.8rem;\r\n        background-color: #060021;\r\n        @include m.tablet{\r\n            display: grid;\r\n            grid-template-columns: 8fr 8fr;\r\n            justify-content: center;\r\n            align-items: center;\r\n            top: 1.8rem;\r\n            background-color: transparent;\r\n            @include m.xxl_desktop { \r\n                width: 100%;\r\n            }\r\n        }\r\n    }\r\n    &__texto{\r\n        //background-color: bisque;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: center;\r\n        align-items: center;\r\n        // padding: 5rem 0;\r\n        \r\n        @include m.tablet{\r\n            // flex: 0 0 55%;\r\n        }\r\n        @include m.xl_tablet{\r\n            flex: 0 0 48%;\r\n        }\r\n        color: v.$blanco; \r\n    }\r\n\r\n    &__logoInnovaTech {\r\n       \r\n        img {\r\n            width: 13rem;\r\n            margin: 1.5rem 0;\r\n\r\n            @include m.telefono { \r\n                width: 16rem;\r\n            }\r\n        }\r\n    }\r\n\r\n    &__bloqueTexto {\r\n       display: flex;\r\n       flex-direction: column;\r\n       align-items: center;\r\n       justify-content: center;\r\n        h1 {\r\n            font-family: v.$fuente-secundaria;\r\n            text-align: center;\r\n            line-height: 1.38;\r\n            font-size: 2rem;\r\n            margin: 0 1.5rem 2rem 1.5rem;\r\n            text-transform: uppercase;\r\n            // @include m.texto_fluido(2.5rem, 2.3rem);\r\n            //font-family: cursive;\r\n            span {\r\n                display: block;\r\n                color: #ae1c34;\r\n                font-size: 4.3rem;\r\n                text-transform: uppercase;\r\n                font-weight: 700;\r\n            }\r\n        }\r\n        p {\r\n            line-height: 1.5;\r\n            margin: 0 1.5rem 2.5rem 1.5rem;\r\n            font-size: 1.1rem;\r\n            text-align: center;\r\n            width: 80%;\r\n            span{\r\n                color: v.$rojo60;\r\n            }\r\n            @include m.desktop { \r\n                max-width: 70%;\r\n            }\r\n            @include m.xxl_desktop { \r\n                max-width: 70%;\r\n            }\r\n        }\r\n\r\n        a { \r\n            color: v.$blanco;\r\n            background-color: #ae1c34;\r\n            padding: 1.8rem 0;\r\n            border-radius: .8rem;\r\n            display: flex;\r\n            margin: 0 1rem 1rem 1rem;\r\n            align-items: center;\r\n            justify-content: center;\r\n            width: 90%;\r\n            border: 1px solid #ae1c34;\r\n            @include m.telefono { \r\n                font-size: 1.8rem;\r\n                max-width: 45%;\r\n                text-align: center;\r\n            }\r\n\r\n            &:hover{\r\n                background-color: transparent;\r\n                border: 1px solid #ae1c34;\r\n                color: v.$blanco;\r\n            }\r\n        }\r\n    }     \r\n}\r\n\r\n//Redes Sociales\r\n.rrss {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 3.4rem;\r\n    margin-top: 2rem;\r\n    margin-bottom: 1rem;\r\n    a {    \r\n        svg {\r\n            font-size: 2.8rem;\r\n        }\r\n    }\r\n}\r\n\r\n.app {\r\n    color: white;\r\n    font-size: 2rem;\r\n    text-align: center;\r\n}\r\n  \r\n@media screen and (max-width: 980px) and (orientation: landscape) {\r\n    .app {\r\n        display: block;\r\n        height: 65rem;\r\n        width: 100%;\r\n    }\r\n}","\n\n html {\n    line-height: 1.15; /* 1 */\n    -webkit-text-size-adjust: 100%; /* 2 */\n  }\n  \n  /* Sections\n     ========================================================================== */\n  \n  /**\n   * Remove the margin in all browsers.\n   */\n  \n  body {\n    margin: 0;\n  }\n  \n  /**\n   * Render the `main` element consistently in IE.\n   */\n  \n  main {\n    display: block;\n  }\n  \n  /**\n   * Correct the font size and margin on `h1` elements within `section` and\n   * `article` contexts in Chrome, Firefox, and Safari.\n   */\n  \n  h1 {\n    font-size: 2em;\n    margin: 0.67em 0;\n  }\n  \n  /* Grouping content\n     ========================================================================== */\n  \n  /**\n   * 1. Add the correct box sizing in Firefox.\n   * 2. Show the overflow in Edge and IE.\n   */\n  \n  hr {\n    box-sizing: content-box; /* 1 */\n    height: 0; /* 1 */\n    overflow: visible; /* 2 */\n  }\n  \n  /**\n   * 1. Correct the inheritance and scaling of font size in all browsers.\n   * 2. Correct the odd `em` font sizing in all browsers.\n   */\n  \n  pre {\n    font-family: monospace, monospace; /* 1 */\n    font-size: 1em; /* 2 */\n  }\n  \n  /* Text-level semantics\n     ========================================================================== */\n  \n  /**\n   * Remove the gray background on active links in IE 10.\n   */\n  \n  a {\n    background-color: transparent;\n  }\n  \n  /**\n   * 1. Remove the bottom border in Chrome 57-\n   * 2. Add the correct text decoration in Chrome, Edge, IE, Opera, and Safari.\n   */\n  \n  abbr[title] {\n    border-bottom: none; /* 1 */\n    text-decoration: underline; /* 2 */\n    text-decoration: underline dotted; /* 2 */\n  }\n  \n  /**\n   * Add the correct font weight in Chrome, Edge, and Safari.\n   */\n  \n  b,\n  strong {\n    font-weight: bolder;\n  }\n  \n  /**\n   * 1. Correct the inheritance and scaling of font size in all browsers.\n   * 2. Correct the odd `em` font sizing in all browsers.\n   */\n  \n  code,\n  kbd,\n  samp {\n    font-family: monospace, monospace; /* 1 */\n    font-size: 1em; /* 2 */\n  }\n  \n  /**\n   * Add the correct font size in all browsers.\n   */\n  \n  small {\n    font-size: 80%;\n  }\n  \n  /**\n   * Prevent `sub` and `sup` elements from affecting the line height in\n   * all browsers.\n   */\n  \n  sub,\n  sup {\n    font-size: 75%;\n    line-height: 0;\n    position: relative;\n    vertical-align: baseline;\n  }\n  \n  sub {\n    bottom: -0.25em;\n  }\n  \n  sup {\n    top: -0.5em;\n  }\n  \n  /* Embedded content\n     ========================================================================== */\n  \n  /**\n   * Remove the border on images inside links in IE 10.\n   */\n  \n  img {\n    border-style: none;\n  }\n  \n  /* Forms\n     ========================================================================== */\n  \n  /**\n   * 1. Change the font styles in all browsers.\n   * 2. Remove the margin in Firefox and Safari.\n   */\n  \n  button,\n  input,\n  optgroup,\n  select,\n  textarea {\n    font-family: inherit; /* 1 */\n    font-size: 100%; /* 1 */\n    line-height: 1.15; /* 1 */\n    margin: 0; /* 2 */\n  }\n  \n  /**\n   * Show the overflow in IE.\n   * 1. Show the